/* ==================== Script 69 id="amiyo-memstore" ==================== */
/* When a page is opened straight from the phone's storage (content:// or file://) or inside a sandbox, the browser blocks
   localStorage/sessionStorage and every read or write throws. Use a session-only copy instead so nothing crashes, and share it
   with the embedded editor so your work survives switching tabs inside the app. */
(function(){
  var bag; try{ bag=(window.parent&&window.parent!==window&&window.parent.__amiyoMem)||null; }catch(e){ bag=null; }
  if(!bag) bag={}; try{ window.__amiyoMem=bag; }catch(e){window.__swl&&window.__swl(e)}
  function mem(n){
    var d=bag[n]||(bag[n]={});
    return { getItem:function(k){ return Object.prototype.hasOwnProperty.call(d,k)?d[k]:null; }, setItem:function(k,v){ d[k]=String(v); },
      removeItem:function(k){ delete d[k]; }, clear:function(){ for(var k in d) delete d[k]; }, key:function(i){ return Object.keys(d)[i]||null; },
      get length(){ return Object.keys(d).length; } };
  }
  ["localStorage","sessionStorage"].forEach(function(n){
    var ok=false;
    try{ var s=window[n], t="__amiyo_t"+Math.random(); s.setItem(t,"1"); s.removeItem(t); ok=true; }catch(e){window.__swl&&window.__swl(e)}
    if(!ok){ try{ Object.defineProperty(window,n,{value:mem(n),configurable:true}); window.__amiyoMemStorage=true; }catch(e){window.__swl&&window.__swl(e)} }
  });
})();

