/* ==================== Script 70 id="amiyo-storage-guard" ==================== */
/* Some browsers/embedded viewers refuse navigator.storage.persist() ("not supported in this context"). Make it quietly answer false instead of raising an error toast. */
try{ var _sm=navigator.storage; if(_sm&&!_sm.__amiyoSafe){ _sm.__amiyoSafe=1; ["persist","persisted","estimate"].forEach(function(k){ var f=_sm[k]; if(typeof f!=="function") return; _sm[k]=function(){ try{ return Promise.resolve(f.apply(_sm,arguments)).catch(function(){ return k==="estimate"?{usage:0,quota:0}:false; }); }catch(e){ return Promise.resolve(k==="estimate"?{usage:0,quota:0}:false); } }; }); } }catch(e){window.__swl&&window.__swl(e)}

;
