"use strict";

const $ = id => document.getElementById(id);
const uid = (p="id") => p + "_" + Math.random().toString(36).slice(2,10) + Date.now().toString(36).slice(-4);
const clamp = (n,a,b)=>Math.min(b,Math.max(a,n));
const fmt = s => {
  s = Math.max(0, Number(s)||0);
  const m = Math.floor(s/60), sec = Math.floor(s%60), ms = Math.floor((s%1)*1000);
  return `${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}.${String(ms).padStart(3,"0")}`;
};
const escapeHtml = s => String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));

/* Amiyo: media bytes live in a Blob store (memory + IndexedDB), never inside the project JSON —
   autosave no longer hits the storage quota and undo history no longer copies every video. */
window.amiyoFade=window.amiyoFade||function(){return 1};
window.amiyoNeedsStack=function(c){ return !!((c.look&&c.look!=="none")||(c.lut&&c.lut.enabled&&c.lut.table)||(c.chromaKey&&c.chromaKey.enabled)||(c.blendMode&&c.blendMode!=="normal")); };
const ASSET_BLOBS=new Map(), ASSET_URLS=new Map();
function dataUrlToBlob(u,mime){
  const i=u.indexOf(","), meta=u.slice(5,i), bin=atob(u.slice(i+1)), arr=new Uint8Array(bin.length);
  for(let k=0;k<bin.length;k++) arr[k]=bin.charCodeAt(k);
  return new Blob([arr],{type:(meta.split(";")[0])||mime||"application/octet-stream"});
}
function assetUrl(id){
  let u=ASSET_URLS.get(id); if(u) return u;
  let b=ASSET_BLOBS.get(id);
  if(!b){ const a=project&&project.assets&&project.assets[id]; if(a&&typeof a.fileData==="string"&&a.fileData.indexOf("data:")===0){ b=dataUrlToBlob(a.fileData,a.mime); ASSET_BLOBS.set(id,b); } }
  if(!b) return null;
  u=URL.createObjectURL(b); ASSET_URLS.set(id,u); return u;
}
function thumbHTML(a){
  const u=assetUrl(a.id)||"";
  const inner=a.type==="image"?`<img src="${u}" alt="">`:a.type==="video"?`<video src="${u}#t=0.1" muted playsinline preload="metadata"></video>`:`<span>${String(a.type).toUpperCase()}</span>`;
  return inner+`<button type="button" class="asset-add" data-add="${a.id}" aria-label="Add to timeline" title="Add to timeline">＋</button>`;
}
/* Step 97: tell "no clip here" apart from "the clip's media is gone / can't be played" */
function amiyoAssetMissing(id){
  const a=project&&project.assets&&project.assets[id]; if(!a) return !!id;
  const k=a.id||id;
  if(ASSET_BLOBS.has(k)||ASSET_URLS.has(k)) return false;
  if(typeof a.fileData==="string"&&a.fileData.indexOf("data:")===0) return false;
  if(a.runtimeUrl) return false;
  return true;
}
function amiyoWhyBlank(vc){
  if(!vc||!vc.clip||!vc.clip.assetId) return null;
  const c=vc.clip, a=project.assets[c.assetId], nm=(a&&a.name)||"this file";
  if(!a||amiyoAssetMissing(c.assetId)) return {kind:"missing",asset:a||null,name:nm,title:"Media missing: "+nm,sub:"Import the file again to relink it"};
  if(a.type==="video"&&videoEl.error) return {kind:"error",asset:a,name:nm,title:"Can't play: "+nm,sub:(videoEl.error&&videoEl.error.message)||"Convert it to MP4 (H.264) or WebM"};
  return {kind:"loading",asset:a,name:nm,title:"Loading "+nm+"…",sub:""};
}
window.amiyoAssetMissing=amiyoAssetMissing; window.amiyoWhyBlank=amiyoWhyBlank;
var store = {
  key:"amiyo.video.studio.v1",
  async save(project){ localStorage.setItem(this.key, JSON.stringify(project)); },
  async load(){ try{return JSON.parse(localStorage.getItem(this.key)||"null")}catch{return null} }
};

