/* step 9: reusable scratch canvases so per-frame effects stop allocating a new canvas every frame */
var __scratch=new Map();
function amiyoScratch(key,w,h,opts){ var c=__scratch.get(key); if(!c){ c=document.createElement("canvas"); __scratch.set(key,c); }
  if(c.width!==w||c.height!==h){ c.width=w; c.height=h; } else { c.getContext("2d",opts).clearRect(0,0,w,h); } return c; }
window.amiyoScratch=amiyoScratch;
/* step 11: persistent cache for timeline thumbnails and waveforms (stored beside the media, keyed by asset id + size) */
window.amiyoCacheKey=function(kind,a){ return "cache:"+kind+":"+a.id+":"+(a.size||0); };
window.amiyoCacheGet=async function(kind,a){ try{ var v=await window.amiyoGetBlob(window.amiyoCacheKey(kind,a)); return v&&v.v===1?v.data:null; }catch(e){ return null; } };
window.amiyoCachePut=function(kind,a,data){ try{ return window.amiyoPutBlob(window.amiyoCacheKey(kind,a),{v:1,data:data}); }catch(e){window.__swl&&window.__swl(e)} };
var __slots=0,__waitQ=[];
function amiyoSlot(){ return new Promise(function(res){ function go(){ if(__slots<2){ __slots++; res(function(){ __slots--; var n=__waitQ.shift(); if(n) n(); }); } else __waitQ.push(go); } go(); }); }
window.amiyoSlot=amiyoSlot;
