          caps.forEach(x=>t.clips.push({id:uid2("cap"),kind:"caption",name:"Caption",start:x.start,duration:Math.max(.05,x.end-x.start),text:x.text,x:.5,y:.84,opacity:1,textStyle:{fontSize:38,weight:700,color:"#fff",shadow:true}}));
