/* ---------- capability system ---------- */
function capabilityMatrix(){
  return {
    WebCodecs:!!window.VideoDecoder,
    WebGPU:!!navigator.gpu,
    WebGL:!!document.createElement("canvas").getContext("webgl"),
    IndexedDB:(function(){try{return !!window.indexedDB}catch(e){return false}})(),
    Workers:!!window.Worker,
    OffscreenCanvas:!!window.OffscreenCanvas,
    MediaRecorder:!!window.MediaRecorder,
    CanvasCapture:!!HTMLCanvasElement.prototype.captureStream,
    ScreenCapture:!!navigator.mediaDevices?.getDisplayMedia,
    Camera:!!navigator.mediaDevices?.getUserMedia,
    AudioWorklet:!!window.AudioWorkletNode,
    SpeechRecognition:!!(window.SpeechRecognition||window.webkitSpeechRecognition)
  };
}

/* ---------- project inspector + pre-export QC ---------- */
function projectQC(){
  const issues=[], warnings=[];
  const duration=getProjectDuration();
  if(!project.tracks.length)issues.push("No timeline tracks exist.");
  for(const t of project.tracks)for(const c of t.clips){
    if(c.assetId&&!getAsset(c.assetId))issues.push(`Missing asset for clip ${c.id}`);
    if(c.duration<.05)warnings.push(`Very short clip at ${fmt(c.start)}`);
    if(c.opacity<=0)warnings.push(`Invisible clip at ${fmt(c.start)}`);
  }
  const caps=project.tracks.filter(t=>t.kind==="caption").flatMap(t=>t.clips);
  for(const c of caps)if((c.text||"").length>120)warnings.push("Long caption may overflow safe zones.");
  if(duration>3600)warnings.push("Sequence is longer than one hour.");
  if(project.settings.width>1920||project.settings.height>1920)warnings.push("High-resolution export may be memory intensive in-browser.");
  const orphan=Object.keys(project.assets).filter(id=>!project.tracks.some(t=>t.clips.some(c=>c.assetId===id)));
  return (window.__s161QC||function(r){return r;})({ok:issues.length===0,issues,warnings,assets:Object.keys(project.assets).length,duration,orphan});
}
window.runPreExportQC=()=>{
  const q=projectQC(), caps=capabilityMatrix();
  openModal("AMIYO PRE-EXPORT CHECK",`
    <div class="kpi-grid">
      <div class="kpi"><span>Result</span><b>${q.ok?"READY":"BLOCKED"}</b></div>
      <div class="kpi"><span>Duration</span><b>${fmt(q.duration)}</b></div>
      <div class="kpi"><span>Assets</span><b>${q.assets}</b></div>
      <div class="kpi"><span>WebCodecs</span><b>${caps.WebCodecs?"Available":"Unavailable"}</b></div>
    </div>
    ${q.issues.length?`<h4>Blocking issues</h4><ul>${q.issues.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:"<p style='color:#75e6a6'>No blocking project integrity errors detected.</p>"}
    ${q.warnings.length?`<h4>Warnings</h4><ul>${q.warnings.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:"<p>No warnings detected.</p>"}
    <div class="mini-row" style="margin-top:14px">
      <button class="chip" id="qcRunExport" ${q.ok?"":"disabled"}>Validate & Export</button>
      <button class="chip" id="qcDiag">Open Diagnostics</button>
    </div>`);
  q.ok&&setTimeout(()=>q.qcRunExport=q,0);
  document.getElementById("qcRunExport")?.addEventListener("click",()=>{closeModal();exportProject()});
  document.getElementById("qcDiag")?.addEventListener("click",()=>{closeModal();showDiagnostics()});
};
window.showProjectInspector=()=>{
  const q=projectQC();
  const tracks=project.tracks.map(t=>`<div class="kpi"><span>${escapeHtml(t.name)}</span><b>${t.clips.length} clips</b></div>`).join("");
  openModal("Project Inspector",`
  <div class="kpi-grid">
    <div class="kpi"><span>Sequence</span><b>${escapeHtml(project.sequences.find(s=>s.id===project.activeSequenceId)?.name||"Main")}</b></div>
    <div class="kpi"><span>Format</span><b>${project.settings.width}×${project.settings.height}</b></div>
    <div class="kpi"><span>FPS</span><b>${project.settings.fps}</b></div>
    <div class="kpi"><span>Duration</span><b>${fmt(q.duration)}</b></div>
    <div class="kpi"><span>Effects</span><b>${project.tracks.reduce((n,t)=>n+t.clips.reduce((a,c)=>a+(c.effects?.length||0),0),0)}</b></div>
    <div class="kpi"><span>Markers</span><b>${project.markers.length}</b></div>
  </div><h4>Tracks</h4>${tracks}`);
};

/* ---------- structured Amiyo Agent ---------- */
const Agent={
  parse(text){
    const s=String(text||"").trim().toLowerCase(), actions=[];
    let m;
    if((m=s.match(/remove (?:the )?first (\d+(?:\.\d+)?) seconds?/)))actions.push({action:"TRIM_HEAD",seconds:Number(m[1])});
    if((m=s.match(/split.*?(\d{1,2}:\d{2}(?::\d{2})?(?:\.\d+)?)/)))actions.push({action:"SPLIT_AT",time:m[1]});
    if(s.includes("remove silence")||s.includes("cut long pauses"))actions.push({action:"REMOVE_SILENCE",requiresProvider:true});
    if(s.includes("add subtitles")||s.includes("add captions"))actions.push({action:"ADD_CAPTIONS",requiresProvider:true});
    if(s.includes("make captions larger"))actions.push({action:"CAPTION_SCALE",factor:1.25});
    if(s.includes("background music")||s.includes("music"))actions.push({action:"ADD_MUSIC",requiresProvider:true});
    if(s.includes("vertical")||s.includes("9:16"))actions.push({action:"SET_ASPECT",aspect:"9:16"});
    const sm=s.match(/(?:make|turn).*(?:into|a) (15|30|45|60) second short/);
    if(sm)actions.push({action:"CREATE_SHORT",seconds:Number(sm[1]),requiresProvider:true});
    if(s.includes("cinematic"))actions.push({action:"APPLY_CINEMATIC"});
    if(s.includes("export captions"))actions.push({action:"EXPORT_CAPTIONS"});
    if(!actions.length)actions.push({action:"UNMAPPED",query:text});
    return actions;
  },
  async execute(actions,{confirmDestructive=true}={}){
    const destructive=actions.some(a=>["TRIM_HEAD","REMOVE_SILENCE","CREATE_SHORT","SET_ASPECT"].includes(a.action));
    if(destructive&&confirmDestructive){
      const names=actions.map(a=>a.action.replaceAll("_"," ")).join(", ");
      if(!await amiyoOk(`Amiyo Agent will execute: ${names}\nContinue?`,{okLabel:"Run"}))return {cancelled:true};
    }
    const results=[];
    for(const a of actions){
      try{
        if(a.action==="TRIM_HEAD"){
          const f=getClip();if(f)transact("Agent: trim head",()=>{f.clip.start=Math.max(0,f.clip.start);f.clip.inPoint=(f.clip.inPoint||0)+a.seconds;f.clip.duration=Math.max(.05,f.clip.duration-a.seconds)});
          results.push("Trimmed selected clip");
        }else if(a.action==="SPLIT_AT"){const t=parseTimecode(a.time);if(t!=null){setCurrentTime(t);splitSelected();results.push("Split at "+a.time)}}
        else if(a.action==="CAPTION_SCALE"){transact("Agent: enlarge captions",()=>project.tracks.filter(t=>t.kind==="caption").forEach(t=>t.clips.forEach(c=>c.textStyle={...(c.textStyle||{}),fontSize:(c.textStyle?.fontSize||38)*a.factor})));results.push("Caption size increased")}
        else if(a.action==="SET_ASPECT"){const map={"9:16":[720,1280],"16:9":[1280,720],"1:1":[1080,1080],"4:5":[1080,1350]};const d=map[a.aspect]||map["16:9"];transact("Agent: aspect ratio",()=>{project.settings.width=d[0];project.settings.height=d[1];project.settings.aspect=a.aspect});results.push("Aspect set to "+a.aspect)}
        else if(a.action==="APPLY_CINEMATIC"){const f=getClip();if(f){transact("Agent: cinematic",()=>{f.clip.effects=[...(f.clip.effects||[]),{id:mkid("fx"),name:"contrast",value:1.12,enabled:true},{id:mkid("fx"),name:"vignette",value:.3,enabled:true}]});results.push("Cinematic effects applied")}}
        else if(a.action==="EXPORT_CAPTIONS"){exportCaptions();results.push("Caption export started")}
        else if(a.requiresProvider)results.push(`${a.action}: unavailable locally — configure a compatible AI/processing connector`);
        else if(a.action==="UNMAPPED")results.push("No safe local action matched the request.");
      }catch(e){results.push(`${a.action}: failed — ${e.message||"unknown error"}`)}
    }
    project.agentActions.push({id:mkid("agent"),at:nowIso(),request:"structured-action",actions,results});
    scheduleAutosave();renderAll();return {results};
  }
};
V.Agent=Agent;
window.runAgentCommand=text=>{
  const actions=Agent.parse(text);
  openModal("AMIYO AGENT PLAN",`
    <p style="color:var(--muted)">The request was converted into validated editor actions. Unavailable provider-dependent steps are explicitly separated.</p>
    <div class="codebox">${escapeHtml(JSON.stringify(actions,null,2))}</div>
    <div class="mini-row"><button class="chip" id="agentCancel">Cancel</button><button class="chip" id="agentRun">Execute actions</button></div>`);
  document.getElementById("agentCancel").onclick=closeModal;
  document.getElementById("agentRun").onclick=async()=>{closeModal();const r=await Agent.execute(actions);if(r?.results)notify(r.results.join(" · "),5000)};
};

/* ---------- AI workspace / command palette ---------- */
function commandList(){
  return [
    ["Split selected clip","splitSelected()"],["Delete selected clips","multiDelete()"],["Ripple delete","rippleDelete()"],
    ["Duplicate selected clips","duplicateSelected()"],["Group selected","groupSelected()"],["Ungroup selected","ungroupSelected()"],
    ["Link selected","linkSelected()"],["Unlink selected","unlinkSelected()"],["Add marker","addMarker('Marker')"],
    ["Project inspector","showProjectInspector()"],["Pre-export check","runPreExportQC()"],["System diagnostics","showDiagnostics()"],
    ["Toggle safe zones","toggleSafeZones()"],["Create sequence","createSequence()"],["Export captions","exportCaptions()"]
  ];
}
window.commandList=commandList;
window.openCommandPalette=()=>{
  const cmds=commandList();
  openModal("AMIYO COMMAND PALETTE",`
    <input id="commandPaletteSearch" class="search" placeholder="Search every editor operation…" aria-label="Search commands">
    <div id="commandPaletteList" style="margin-top:10px"></div>`);
  const list=document.getElementById("commandPaletteList"), si=document.getElementById("commandPaletteSearch");
  const run=i=>{ closeModal(); try{ Promise.resolve(window.amiyoRunCmd(cmds[i][1])).catch(e=>notify((e&&e.message)||"Command failed")); }catch(e){ notify((e&&e.message)||"Command failed"); } };
  const render=()=>{
    const qv=(si.value||"").toLowerCase().trim();
    const hits=cmds.map((c,k)=>[c,k]).filter(x=>x[0][0].toLowerCase().includes(qv));
    list.innerHTML=hits.map(x=>`<button class="toolbtn" style="width:100%;text-align:left;margin:4px 0" data-cmd="${x[1]}">${escapeHtml(x[0][0])}</button>`).join("")||`<div style="color:var(--muted);font-size:12px;padding:6px">No matching command</div>`;
    list.querySelectorAll("[data-cmd]").forEach(b=>b.onclick=()=>run(+b.dataset.cmd));
  };
  si.oninput=render;
  si.onkeydown=e=>{ if(e.key==="Enter"){ const b=list.querySelector("[data-cmd]"); if(b){ e.preventDefault(); run(+b.dataset.cmd); } } };
  render(); si.focus();
};
