/* =========================================================================
   AMIYO PRO TOOLS — Batch 2, Feature 2
   7) Speed / Duration (Rate Stretch) tool — Premiere-style clip speed
      changes that properly retime the clip's timeline length, with an
      option to ripple the duration or keep it fixed and crop the source.
   ========================================================================= */
(function(){
"use strict";

let rippleOn=true;

function injectSpeedDurationPanel(){
  const f=getClip(); if(!f) return;
  if(f.track.kind!=="video" && f.track.kind!=="audio") return;
  const insp=$("inspector"); if(!insp) return;
  const c=f.clip;
  const pct=Math.round((c.speed||1)*100);
  const group=document.createElement("div"); group.className="group"; group.id="speedRippleGroup";
  group.innerHTML=`<h3>Speed / Duration</h3>
    <div class="fieldrow">
      <div><label class="field">Speed %</label><input id="iSpeedPct" type="number" min="1" max="800" step="5" value="${pct}"></div>
      <div><label class="field">Resulting duration</label><input id="iSpeedDurOut" type="text" value="${fmt(c.duration)}" disabled></div>
    </div>
    <label style="display:flex;align-items:center;gap:6px;margin-top:8px;font-size:11px;color:#aeb8c7">
      <input type="checkbox" id="iRipple" ${rippleOn?"checked":""}> Ripple duration with speed
    </label>
    <div class="mini-row" style="margin-top:8px"><button class="chip" id="speedReset">100%</button><button class="chip" id="speedHalf">50%</button><button class="chip" id="speedDouble">200%</button><button class="chip" id="speedQuad">400%</button></div>`;
  const header=insp.querySelector(".group");
  if(header && header.nextSibling) header.parentNode.insertBefore(group,header.nextSibling);
  else insp.appendChild(group);

  function applyPct(newPct){
    newPct=clamp(newPct,1,800);
    const newSpeed=newPct/100;
    const before=deepClone(serializableProject());
    if(rippleOn){
      const srcLen=(c.outPoint??c.duration)-(c.inPoint||0);
      c.speed=newSpeed;
      c.duration=Math.max(.05,srcLen/newSpeed);
    }else{
      const asset=getAsset(c.assetId);
      c.speed=newSpeed;
      let newOut=(c.inPoint||0)+c.duration*newSpeed;
      if(asset && asset.duration && newOut>asset.duration){newOut=asset.duration;notify("Clamped to source length");}
      c.outPoint=newOut;
    }
    const after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Change speed",before,after}); project.history.index++;
    scheduleAutosave(); renderAll();
  }
  const pctEl=$("iSpeedPct"); if(pctEl) pctEl.onchange=e=>applyPct(Number(e.target.value)||100);
  const rippleEl=$("iRipple"); if(rippleEl) rippleEl.onchange=e=>{rippleOn=e.target.checked;};
  const r1=$("speedReset"); if(r1) r1.onclick=()=>{pctEl.value=100;applyPct(100);};
  const r2=$("speedHalf"); if(r2) r2.onclick=()=>{pctEl.value=50;applyPct(50);};
  const r3=$("speedDouble"); if(r3) r3.onclick=()=>{pctEl.value=200;applyPct(200);};
  const r4=$("speedQuad"); if(r4) r4.onclick=()=>{pctEl.value=400;applyPct(400);};
}

const riPrev=window.renderInspector;
window.renderInspector=function(){
  riPrev();
  injectSpeedDurationPanel();
};

})();

