/* ==================== Script 78 ==================== */
/* =========================================================================
   AMIYO PRO TOOLS — Batch 3, Feature 1
   9) Real rendered Transitions: Cross Dissolve / Wipe / Zoom between
      adjacent clips on a track (not just a solo fade-to-black). Applying
      a transition overlaps the clip onto its neighbor and ripples the
      rest of the track to close the gap, exactly like Premiere's default
      (non-MCJ) transition drop. A transition badge is drawn on the
      timeline at the cut, and the Inspector gets a Transition group with
      a duration field and a remove button.
   ========================================================================= */
(function(){
"use strict";

const transitionFrameCache={};
function cacheClipFrame(clipId){
  if(!clipId) return;
  if(!project.tracks.some(function(t){ return t.clips.some(function(c){ return c.transitionIn; }); })) return;  /* step 9: no transitions, no full-frame copy */
  const W=canvas.width,H=canvas.height;
  let entry=transitionFrameCache[clipId];
  if(!entry || entry.w!==W || entry.h!==H){
    entry={cv:document.createElement("canvas"),w:W,h:H};
    entry.cv.width=W; entry.cv.height=H;
    transitionFrameCache[clipId]=entry;
  }
  entry.cv.getContext("2d").drawImage(canvas,0,0); entry.t=currentTime;   /* export step 2: remember WHEN this picture was taken, so a copy from a different moment is never shown as the outgoing picture */
}

/* ---- apply transition: overlap onto previous clip + ripple track ---- */
window.applyTransition=function(name){
  const f=getClip();
  if(!f){toast("Select the clip receiving the transition");return;}
  if(f.track.kind!=="video"){toast("Transitions apply to video clips");return;}
  const track=f.track, clip=f.clip;
  const sorted=[...track.clips].sort((a,b)=>a.start-b.start);
  const idx=sorted.findIndex(c=>c.id===clip.id);
  const prev=idx>0?sorted[idx-1]:null;
  if(!prev || prev.start+prev.duration>clip.start+0.02){toast("Add a clip right before this one on the same track first");return;}
  const maxDur=Math.max(0,Math.min(clip.duration,prev.duration)-0.1);
  if(maxDur<0.15){toast("Clips are too short for a transition");return;}
  const dur=clamp(clip.transitionIn?.duration||0.75,0.15,maxDur);
  const before=deepClone(serializableProject());
  const origStart=clip.start;
  clip.transitionIn={name,duration:dur};
  clip.start=origStart-dur;
  prev.transitionOut={name,duration:dur};
  for(const other of track.clips){
    if(other.id!==clip.id && other.id!==prev.id && other.start>=origStart-0.001) other.start-=dur;
  }
  const after=serializableProject();
  project.history.entries=project.history.entries.slice(0,project.history.index+1);
  project.history.entries.push({label:"Add transition",before,after}); project.history.index++;
  scheduleAutosave(); renderAll(); notify(name+" transition applied — downstream clips rippled to close the gap");
};

/* ---- composite the previous clip's cached frame over the new clip ---- */
const origRenderPreviewFrame3=window.renderPreviewFrame;
/* step 4: if you jump straight into a transition, the outgoing clip was never drawn, so there is nothing to blend.
   Draw its last frame once, keep it, then carry on. */
async function primeOutgoing(preVc){
  const clip=preVc.clip, dur=(clip.transitionIn&&clip.transitionIn.duration)||0.5, local=currentTime-clip.start;
  if(!(local>=0&&local<dur)||window.__amiyoPriming) return;
  const sorted=[...preVc.track.clips].sort((a,b)=>a.start-b.start), i=sorted.findIndex(c=>c.id===clip.id), prev=i>0?sorted[i-1]:null;
  if(!prev) return;
  const e=transitionFrameCache[prev.id]; if(e&&e.w===canvas.width&&e.h===canvas.height&&typeof e.t==="number"&&e.t>=clip.start-0.45&&e.t<=clip.start+0.001) return;   /* export step 2: only a picture taken just before the transition counts */
  const t0=currentTime; window.__amiyoPriming=true;
  try{ currentTime=Math.max(prev.start,clip.start-0.03); await origRenderPreviewFrame3(); cacheClipFrame(prev.id); }
  catch(err){ try{ console.warn("Outgoing frame could not be drawn",err); }catch(_){window.__swl&&window.__swl(_)} }
  finally{ currentTime=t0; window.__amiyoPriming=false; }
}
/* Export step 10: with a second video track on top (picture-in-picture, overlay) the outgoing clip of a transition was never saved and the transition was never found,
   because only the top track's clip was looked at. Now each track is checked on its own: the transitioning clip is found on any video track, and the last picture of every clip
   that is followed by a transition on its own track is saved while it plays. */
function amiyoTransClipAt(time){
  let best=null;
  for(const t of project.tracks){
    if(t.kind!=="video"||t.hidden) continue;
    for(const c of t.clips){
      if(c.off||!c.transitionIn) continue;
      const d=c.transitionIn.duration||0.5, l=time-c.start;
      if(l>=0&&l<d) best={track:t,clip:c};
    }
  }
  return best;
}
window.__amiyoCacheClipFrame=cacheClipFrame;
/* Export follow-up 1: the multi-layer compositor calls this right after it paints a clip, so a transition on that clip's track is drawn even when an overlay is on screen. */
window.__amiyoStackTransition=function(track,clip){
  const tin=clip&&clip.transitionIn; if(!tin) return;
  const dur=tin.duration||0.5, local=currentTime-clip.start; if(!(local>=0&&local<dur)) return;
  const sorted=[...track.clips].sort((a,b)=>a.start-b.start), i=sorted.findIndex(c=>c.id===clip.id), prev=i>0?sorted[i-1]:null; if(!prev) return;
  const cache=transitionFrameCache[prev.id]; if(!cache||cache.w!==canvas.width||cache.h!==canvas.height) return;
  const p=clamp(local/dur,0,1), W=canvas.width, H=canvas.height;
  ctx.save();
  try{
    if(window.AMIYO_TRANSITIONS){ window.AMIYO_TRANSITIONS.draw(tin.name,p,cache.cv,W,H); }
    else{ ctx.globalAlpha=1-p; ctx.drawImage(cache.cv,0,0,W,H); }
  }finally{ ctx.restore(); }
};
function amiyoSaveOutgoing(time){
  for(const t of project.tracks){
    if(t.kind!=="video"||t.hidden) continue;
    const sorted=[...t.clips].sort((a,b)=>a.start-b.start);
    for(let i=0;i<sorted.length-1;i++){
      const c=sorted[i], n=sorted[i+1];
      if(c.off||!n.transitionIn) continue;
      if(time>=c.start&&time<c.start+c.duration&&time<n.start) cacheClipFrame(c.id);   /* step 13: once the next clip has started (the overlap) the screen holds the transition itself, so it must not be saved again as the outgoing picture */
    }
  }
}
window.__amiyoSaveOutgoing=amiyoSaveOutgoing;
window.renderPreviewFrame=async function(){
  const preVc=amiyoTransClipAt(currentTime)||activeClipAt(currentTime,"video");
  if(preVc && preVc.clip.transitionIn) await primeOutgoing(preVc);
  await origRenderPreviewFrame3();
  if(preVc && preVc.clip.transitionIn){
    const dur=preVc.clip.transitionIn.duration||0.5;
    const local=currentTime-preVc.clip.start;
    if(local>=0 && local<dur){
      const track=preVc.track;
      const sorted=[...track.clips].sort((a,b)=>a.start-b.start);
      const idx=sorted.findIndex(c=>c.id===preVc.clip.id);
      const prev=idx>0?sorted[idx-1]:null;
      const cache=prev&&transitionFrameCache[prev.id];
      if(cache){
        const p=clamp(local/dur,0,1);
        const W=canvas.width,H=canvas.height;
        ctx.save();
        if(window.AMIYO_TRANSITIONS){ window.AMIYO_TRANSITIONS.draw(preVc.clip.transitionIn.name,p,cache.cv,W,H); }
        else if(preVc.clip.transitionIn.name==="wipe"){
          ctx.beginPath(); ctx.rect(W*p,0,W*(1-p),H); ctx.clip();
          ctx.globalAlpha=1; ctx.drawImage(cache.cv,0,0,W,H);
        }else if(preVc.clip.transitionIn.name==="zoom"){
          ctx.globalAlpha=1-p;
          const s=1+p*0.35;
          ctx.translate(W/2,H/2); ctx.scale(s,s); ctx.translate(-W/2,-H/2);
          ctx.drawImage(cache.cv,0,0,W,H);
        }else{
          ctx.globalAlpha=1-p;
          ctx.drawImage(cache.cv,0,0,W,H);
        }
        ctx.restore();
      }
    }
  }
  if(preVc) cacheClipFrame(preVc.clip.id);
};

/* ---- timeline transition badges ---- */
function paintTransitionBadges(){
  const rows=[...document.querySelectorAll("#tracks .track-row")];
  project.tracks.forEach((t,ti)=>{
    const lane=rows[ti]?.querySelector(".track-lane"); if(!lane) return;
    lane.querySelectorAll(".transition-badge").forEach(el=>el.remove());
    if(t.kind!=="video") return;
    for(const c of t.clips){
      if(!c.transitionIn) continue;
      const left=timeToPx(c.start)+2;
      const w=Math.max(16,timeToPx(c.transitionIn.duration||0.5));
      const badge=document.createElement("div");
      badge.className="transition-badge";
      badge.title=c.transitionIn.name+" · "+(c.transitionIn.duration||0.5).toFixed(2)+"s";
      badge.style.cssText=`position:absolute;left:${left}px;top:7px;width:${w}px;height:42px;background:repeating-linear-gradient(45deg,rgba(255,180,84,.55),rgba(255,180,84,.55) 4px,rgba(255,122,61,.55) 4px,rgba(255,122,61,.55) 8px);border:1px solid rgba(255,255,255,.4);border-radius:6px;z-index:2;pointer-events:none;display:flex;align-items:center;justify-content:center;font-size:11px;color:#0b0d11;font-weight:800`;
      badge.textContent="⧗";
      lane.appendChild(badge);
    }
  });
}
const rtPrev3=window.renderTracks;
window.renderTracks=function(){ rtPrev3(); paintTransitionBadges(); };

/* ---- inspector: transition duration + remove ---- */
function injectTransitionPanel(){
  const f=getClip(); if(!f) return;
  if(f.track.kind!=="video") return;
  const c=f.clip; if(!c.transitionIn) return;
  const insp=$("inspector"); if(!insp || $("transitionGroup")) return;
  const group=document.createElement("div"); group.className="group"; group.id="transitionGroup";
  group.innerHTML=`<h3>Transition In — ${escapeHtml(c.transitionIn.name)}</h3>
    <label class="field">Duration (s)</label><input id="iTransDur" type="number" min=".15" max="4" step=".05" value="${c.transitionIn.duration}">
    <div class="mini-row" style="margin-top:8px"><button class="chip" id="removeTransition" style="color:#ff91a0">Remove transition</button></div>`;
  insp.appendChild(group);
  const durEl=$("iTransDur");
  if(durEl) durEl.onchange=e=>{
    const nd=clamp(Number(e.target.value)||0.5,.15,4);
    const before=deepClone(serializableProject());
    c.transitionIn.duration=nd;
    const after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Adjust transition",before,after}); project.history.index++;
    scheduleAutosave(); renderTracks();
  };
  const rmEl=$("removeTransition");
  if(rmEl) rmEl.onclick=()=>{
    const before=deepClone(serializableProject());
    c.transitionIn=null;
    const after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Remove transition",before,after}); project.history.index++;
    scheduleAutosave(); renderAll(); toast("Transition removed");
  };
}
const riPrev3=window.renderInspector;
window.renderInspector=function(){ riPrev3(); injectTransitionPanel(); };

setTimeout(paintTransitionBadges,450);

})();

