/* ==================== Script 79 ==================== */
/* =========================================================================
   AMIYO PRO TOOLS — Batch 3, Feature 2
   10) Keyframe Editor in the Inspector: a visual keyframe lane with
       diamond markers you can click to jump to, Prev/Next keyframe
       navigation, delete-nearest, and rotation is now a keyframeable
       property alongside position/scale/opacity.
   ========================================================================= */
(function(){
"use strict";

/* ---- extend addKeyframe to also capture rotation ---- */
window.addKeyframe=function(){
  const f=getClip(); if(!f){toast("Select a clip");return}
  f.clip.keyframes=f.clip.keyframes||[];
  const before=deepClone(serializableProject());
  f.clip.keyframes.push({t:currentTime-f.clip.start,x:f.clip.x??.5,y:f.clip.y??.5,scale:f.clip.scale??1,rotation:f.clip.rotation??0,opacity:f.clip.opacity??1,easing:"linear"});
  f.clip.keyframes.sort((a,b)=>a.t-b.t);
  const after=serializableProject();
  project.history.entries=project.history.entries.slice(0,project.history.index+1);
  project.history.entries.push({label:"Add keyframe",before,after}); project.history.index++;
  scheduleAutosave(); renderAll();
};

/* ---- interpolate rotation from keyframes (position/scale/opacity already handled by base) ---- */
const origRenderPreviewFrame4=window.renderPreviewFrame;
window.renderPreviewFrame=async function(){
  const vc=activeClipAt(currentTime,"video");
  let savedRotation;
  if(vc && vc.clip.keyframes && vc.clip.keyframes.length>1){
    const keys=[...vc.clip.keyframes].sort((a,b)=>a.t-b.t);
    const local=currentTime-vc.clip.start;
    let a=keys[0], b=keys[keys.length-1];
    for(let i=0;i<keys.length-1;i++){ if(local>=keys[i].t && local<=keys[i+1].t){a=keys[i];b=keys[i+1];break;} }
    if(a.rotation!=null || b.rotation!=null){
      const span=Math.max(.0001,b.t-a.t), p=clamp((local-a.t)/span,0,1);
      const ar=a.rotation??vc.clip.rotation??0, br=b.rotation??vc.clip.rotation??0;
      savedRotation=vc.clip.rotation;
      vc.clip.rotation=ar+(br-ar)*p;
    }
  }
  await origRenderPreviewFrame4();
  if(vc && savedRotation!==undefined) vc.clip.rotation=savedRotation;
};

/* ---- inspector keyframe lane ---- */
function injectKeyframePanel(){
  const f=getClip(); if(!f) return;
  if(f.track.kind!=="video" && f.track.kind!=="text") return;
  const c=f.clip; const insp=$("inspector"); if(!insp || $("keyframeGroup")) return;
  const keys=(c.keyframes||[]).slice().sort((a,b)=>a.t-b.t);
  const dur=Math.max(.1,c.duration);
  const localT=clamp(currentTime-c.start,0,dur);
  const marks=keys.map((k,i)=>{
    const pct=clamp(k.t/dur,0,1)*100;
    const active=Math.abs(k.t-localT)<0.03;
    return `<div data-kf="${i}" title="${fmt(c.start+k.t)} (${k.easing||"linear"})" style="position:absolute;left:${pct}%;top:5px;width:10px;height:10px;transform:translate(-50%,0) rotate(45deg);background:${active?"#ff7a3d":"#ffb454"};border:1px solid rgba(255,255,255,.6);cursor:pointer"></div>`;
  }).join("");
  const group=document.createElement("div"); group.className="group"; group.id="keyframeGroup";
  group.innerHTML=`<h3>Keyframes <span class="badge">${keys.length}</span></h3>
    <div id="kfTrack" style="position:relative;height:20px;background:#0d1218;border:1px solid var(--line);border-radius:6px;margin:6px 0">
      <div style="position:absolute;left:${clamp(localT/dur,0,1)*100}%;top:-4px;width:1px;height:28px;background:#ff506b"></div>
      ${marks}
    </div>
    <div class="mini-row">
      <button class="chip" id="kfAdd">◆ Add at playhead</button>
      <button class="chip" id="kfPrev">⏮ Prev</button>
      <button class="chip" id="kfNext">Next ⏭</button>
      ${keys.length?'<button class="chip" id="kfDel" style="color:#ff91a0">Delete nearest</button>':""}
    </div>
    <div style="font-size:10px;color:var(--muted);margin-top:6px">Keyframes animate position, scale, rotation and opacity together. Move the playhead, adjust Transform values, then Add.</div>`;
  insp.appendChild(group);
  $("kfAdd").onclick=()=>addKeyframe();
  $("kfPrev").onclick=()=>{
    const b=keys.filter(k=>k.t<localT-0.02).sort((x,y)=>y.t-x.t)[0];
    if(b) setCurrentTime(c.start+b.t); else toast("No earlier keyframe");
  };
  $("kfNext").onclick=()=>{
    const n=keys.filter(k=>k.t>localT+0.02).sort((x,y)=>x.t-y.t)[0];
    if(n) setCurrentTime(c.start+n.t); else toast("No later keyframe");
  };
  const delBtn=$("kfDel");
  if(delBtn) delBtn.onclick=()=>{
    if(!keys.length) return;
    let nearest=keys[0], nd=Math.abs(keys[0].t-localT);
    for(const k of keys){ const d=Math.abs(k.t-localT); if(d<nd){nd=d;nearest=k;} }
    const before=deepClone(serializableProject());
    c.keyframes=c.keyframes.filter(k=>k!==nearest);
    const after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Delete keyframe",before,after}); project.history.index++;
    scheduleAutosave(); renderAll();
  };
  insp.querySelectorAll("[data-kf]").forEach(el=>{
    el.addEventListener("click",()=>{ const k=keys[Number(el.dataset.kf)]; if(k) setCurrentTime(c.start+k.t); });
  });
}
const riPrev4=window.renderInspector;
window.renderInspector=function(){ riPrev4(); injectKeyframePanel(); };

})();

