/* ==================== Script 80 ==================== */
/* =========================================================================
   AMIYO PRO TOOLS — Batch 3, Feature 3
   11) Ripple Delete (Shift+Delete) and a Ripple Trim toggle — Premiere's
       signature ripple workflow. Ripple Delete removes the selected clip
       and shifts every clip on every track after it earlier to close the
       gap. With Ripple Trim armed, dragging a clip's right (out) edge
       automatically shifts everything downstream to stay glued together.
   ========================================================================= */
(function(){
"use strict";

/* ---- Ripple Delete ---- */
function rippleDeleteSelected(){
  const f=getClip(); if(!f){toast("Select a clip");return}
  const S=f.clip.start, D=f.clip.duration;
  const before=deepClone(serializableProject());
  f.track.clips=f.track.clips.filter(c=>c.id!==selectedClipId);
  for(const t of project.tracks) for(const c of t.clips) if(c.start>=S-0.0005) c.start=Math.max(0,c.start-D);
  selectedClipId=null;
  const after=serializableProject();
  project.history.entries=project.history.entries.slice(0,project.history.index+1);
  project.history.entries.push({label:"Ripple delete",before,after}); project.history.index++;
  scheduleAutosave(); renderAll(); notify("Ripple deleted — downstream clips closed the gap");
}
window.rippleDeleteSelected=rippleDeleteSelected;

document.addEventListener("keydown",e=>{
  const inField=["INPUT","TEXTAREA","SELECT"].includes(document.activeElement?.tagName);
  if(inField) return;
  if(e.shiftKey && (e.key==="Delete"||e.key==="Backspace")){
    e.preventDefault();
    rippleDeleteSelected();
  }
});

/* ---- Ripple Trim toggle: ripples downstream clips after an out-point trim ---- */
let rippleTrimOn=false;
let lastRippledIndex=-2;
let ripplingNow=false;
function maybeRippleLastTrim(){
  if(ripplingNow) return;
  const h=project.history; if(!h || h.index<0) return;
  if(h.index===lastRippledIndex) return;
  lastRippledIndex=h.index;
  if(!rippleTrimOn) return;
  const entry=h.entries[h.index]; if(!entry || entry.label!=="Trim end") return;
  const beforeMap=new Map();
  for(const t of entry.before.tracks) for(const c of t.clips) beforeMap.set(c.id,{trackId:t.id,start:c.start,duration:c.duration});
  let changed=null;
  for(const t of entry.after.tracks){
    for(const c of t.clips){
      const prevRec=beforeMap.get(c.id);
      if(prevRec && Math.abs(prevRec.duration-c.duration)>0.0005 && Math.abs(prevRec.start-c.start)<0.0005){
        changed={id:c.id,prevEnd:prevRec.start+prevRec.duration,newEnd:c.start+c.duration};
      }
    }
  }
  if(!changed) return;
  const delta=changed.newEnd-changed.prevEnd;
  if(Math.abs(delta)<0.0005) return;
  ripplingNow=true;
  for(const t of project.tracks) for(const c of t.clips) if(c.id!==changed.id && c.start>=changed.prevEnd-0.0005) c.start=Math.max(0,c.start+delta);
  ripplingNow=false;
  scheduleAutosave(); renderAll();
}
const raPrev3=window.renderAll;
window.renderAll=function(){ raPrev3(); maybeRippleLastTrim(); };

/* ---- toolbar buttons: Ripple toggle + Ripple Delete ---- */
function injectRippleButtons(){
  if($("rippleTrimToggle")) return;
  const anchor=$("snapToggle"); if(!anchor) return;
  const toggle=document.createElement("button");
  toggle.className="toolbtn"; toggle.id="rippleTrimToggle"; toggle.title="Ripple Trim: dragging a clip's out-point shifts everything downstream";
  toggle.textContent="⇥⇤ Ripple Trim";
  anchor.parentNode.insertBefore(toggle,anchor.nextSibling);
  toggle.onclick=()=>{ rippleTrimOn=!rippleTrimOn; toggle.classList.toggle("tool-active",rippleTrimOn); notify("Ripple Trim "+(rippleTrimOn?"armed":"off")); };

  const delBtn=document.createElement("button");
  delBtn.className="toolbtn"; delBtn.id="rippleDeleteBtn"; delBtn.title="Ripple Delete (Shift+Delete)";
  delBtn.textContent="⌫ Ripple Delete";
  toggle.parentNode.insertBefore(delBtn,toggle.nextSibling);
  delBtn.onclick=rippleDeleteSelected;
}
injectRippleButtons();
setTimeout(injectRippleButtons,300);

})();

