    const svgNS="http://www.w3.org/2000/svg";
    const svg=document.createElementNS(svgNS,"svg");
    svg.setAttribute("class","vol-automation");
    svg.setAttribute("width",w); svg.setAttribute("height",h);
    svg.style.cssText="position:absolute;left:0;top:0;z-index:3;pointer-events:auto";
    const keys=clip.volumeKeyframes.slice().sort((a,b)=>a.t-b.t);
    const toXY=k=>[clamp(k.t/Math.max(.05,clip.duration),0,1)*w, h-clamp(k.v,0,1)*(h-6)-3];
