    if(entry.el.error){ entry.assetId=null; window.amiyoReportOnce&&window.amiyoReportOnce("vid:"+a.id,"“"+(a.name||"A video")+"” can't be played",(entry.el.error&&entry.el.error.message)||"The browser could not decode this video."); return null; }
