    await new Promise(res=>{ vid.addEventListener("loadedmetadata",res,{once:true}); vid.addEventListener("error",res,{once:true}); });
    const dur=Number.isFinite(vid.duration)&&vid.duration>0?vid.duration:(asset.duration||5);
    const N=thumbCountFor(dur);
