  const c=f.clip; c.fadeIn=c.fadeIn||0; c.fadeOut=c.fadeOut||0;
  const insp=$("inspector"); if(!insp || $("fadeGroup")) return;
  const group=document.createElement("div"); group.className="group"; group.id="fadeGroup";
  group.innerHTML=`<h3>Fades</h3>
    <div class="fieldrow"><div><label class="field">Fade In (s)</label><input id="iFadeIn" type="number" min="0" step=".05" value="${c.fadeIn.toFixed(2)}"></div>
      <div><label class="field">Fade Out (s)</label><input id="iFadeOut" type="number" min="0" step=".05" value="${c.fadeOut.toFixed(2)}"></div></div>`;
