        ctx.save();
        const x=iv.x*canvas.width, y=iv.y*canvas.height;
        const scale=iv.scale*(s.scale??1); const rot=(c.rotation??0)*Math.PI/180;
        ctx.translate(x,y); ctx.rotate(rot); ctx.globalAlpha=clamp(iv.opacity,0,1);
        let size=(s.fontSize||64)*scale;
