  const isText = f.track.kind==="text"||f.track.kind==="caption"||f.clip.kind==="text";
  if(!isText) return;
  const c=f.clip; c.textStyle=c.textStyle||{}; const s=c.textStyle;
  const box=document.createElement("div"); box.className="group"; box.id="titleStyleGroup";
  box.innerHTML=`<h3>Title Style</h3>
    <div class="mini-row" style="gap:12px">
      <label class="field" style="display:flex;align-items:center;gap:5px;margin:0"><input type="checkbox" id="tsStroke" ${s.stroke?"checked":""}> Stroke</label>
      <label class="field" style="display:flex;align-items:center;gap:5px;margin:0"><input type="checkbox" id="tsShadow" ${s.shadow?"checked":""}> Shadow</label>
      <label class="field" style="display:flex;align-items:center;gap:5px;margin:0"><input type="checkbox" id="tsBg" ${s.bg?"checked":""}> Background</label>
    </div>
    <div class="fieldrow" style="margin-top:8px">
      <div><label class="field">Stroke color</label><input id="tsStrokeColor" type="color" value="${s.strokeColor||"#000000"}"></div>
      <div><label class="field">Stroke width</label><input id="tsStrokeW" type="number" min="0" max="30" value="${s.strokeWidth||6}"></div>
    </div>
    <div class="fieldrow">
      <div><label class="field">Background color</label><input id="tsBgColor" type="color" value="${s.bgColor||"#000000"}"></div>
      <div><label class="field">Alignment</label><select id="tsAlign">
        <option value="left" ${s.align==="left"?"selected":""}>Left</option>
        <option value="center" ${(!s.align||s.align==="center")?"selected":""}>Center</option>
        <option value="right" ${s.align==="right"?"selected":""}>Right</option>
      </select></div>
    </div>
    <h3 style="margin-top:12px">Animation Presets</h3>
    <div class="mini-row">
      <button class="chip" data-anim="fade">Fade In/Out</button>
      <button class="chip" data-anim="slide">Slide Up</button>
      <button class="chip" data-anim="pop">Pop In</button>
      <button class="chip" data-anim="typewriter">Typewriter</button>
      <button class="chip" data-anim="none">None</button>
    </div>`;
  $("inspector").appendChild(box);
  const bindCb=(id,key)=>$(id).addEventListener("change",e=>{s[key]=e.target.checked;scheduleAutosave();renderPreviewFrame();});
