  $("tsBgColor").addEventListener("input",e=>{s.bgColor=e.target.value;scheduleAutosave();renderPreviewFrame();});
  $("tsAlign").addEventListener("change",e=>{s.align=e.target.value;scheduleAutosave();renderPreviewFrame();});
  box.querySelectorAll("[data-anim]").forEach(b=>b.addEventListener("click",()=>applyAnimPreset(b.dataset.anim)));
