  const c=f.clip; const list=c.effects||[];
  const rows=list.map((fx,i)=>{
    const r=EFFECT_RANGES[fx.name]; if(!r) return "";
    return `<div style="margin-top:6px"><label class="field" id="fxlbl${i}">${escapeHtml(fx.name)} (${fx.value})</label>
      <input type="range" class="fxval" data-idx="${i}" min="${r[0]}" max="${r[1]}" step="${r[2]}" value="${fx.value}"></div>`;
  }).join("");
  if(!rows.trim()) return;
  const box=document.createElement("div"); box.className="group"; box.id="fxValuesGroup";
  box.innerHTML=`<h3>Effect Settings</h3>${rows}`;
  $("inspector").appendChild(box);
  box.querySelectorAll(".fxval").forEach(sl=>{
    sl.addEventListener("input",e=>{
      const idx=Number(e.target.dataset.idx); list[idx].value=Number(e.target.value);
      const lbl=$("fxlbl"+idx); if(lbl) lbl.textContent=`${list[idx].name} (${list[idx].value})`;
      scheduleAutosave(); renderPreviewFrame();
    });
  });
