  var body=document.createElement("div"); body.style.cssText="display:flex;flex-wrap:wrap;gap:8px;align-items:flex-start";
  function box(canvasEl,label){ var d=document.createElement("div"); d.style.cssText="text-align:center"; canvasEl.style.cssText="background:#000;border-radius:4px;display:block"; d.appendChild(canvasEl); var l=document.createElement("div"); l.textContent=label; l.style.cssText="font-size:10px;color:var(--muted);margin-top:2px"; d.appendChild(l); return d; }
