setTimeout(injectExtraNavButtons,300);

/* ---------------- 28) Scene Edit Detection ---------------- */
async function runSceneDetection(clipId,trackId){
  const f=getClipByIds(clipId,trackId); if(!f) return;
  const clip=f.clip, asset=getAsset(clip.assetId);
  if(!asset || asset.type!=="video"){ toast("Select a video clip first"); return; }
  const url=await ensureUrl(asset); if(!url){ toast("Could not load source media"); return; }
  const prog=$("sceneProgress"); if(prog) prog.textContent="Analyzing frames…";
  const probe=document.createElement("video");
  probe.muted=true; probe.preload="auto"; probe.src=url;
  await new Promise(res=>{ probe.addEventListener("loadedmetadata",res,{once:true}); probe.addEventListener("error",res,{once:true}); });
  const inP=clip.inPoint||0, outP=(clip.outPoint??(inP+clip.duration));
  const span=Math.max(.4,outP-inP);
  const step=Math.max(.25,span/60);
  const times=[]; for(let t=inP;t<outP;t+=step) times.push(Math.min(t,outP-.02));
  const W=48,H=27; const off=document.createElement("canvas"); off.width=W; off.height=H;
  const octx=off.getContext("2d",{willReadFrequently:true});
  let prevData=null; const cuts=[];
  for(let i=0;i<times.length;i++){
    const t=times[i];
    await new Promise(res=>{
      const done=()=>{ probe.removeEventListener("seeked",done); res(); };
      probe.addEventListener("seeked",done,{once:true});
      try{ probe.currentTime=Math.min(t,(probe.duration||t)-.02); }catch{ res(); }
      setTimeout(res,900);
    });
    let d;
    try{ octx.drawImage(probe,0,0,W,H); d=octx.getImageData(0,0,W,H).data; }catch{ continue; }
    if(prevData){
      let diff=0;
      for(let p=0;p<d.length;p+=4){
        const l1=d[p]*.299+d[p+1]*.587+d[p+2]*.114;
        const l2=prevData[p]*.299+prevData[p+1]*.587+prevData[p+2]*.114;
        diff+=Math.abs(l1-l2);
      }
      const avgDiff=diff/((W*H)*255);
      if(avgDiff>0.16 && (!cuts.length || t-cuts[cuts.length-1]>Math.max(.6,step*1.5))) cuts.push(t);
    }
    prevData=d;
    if(prog) prog.textContent=`Analyzing… ${Math.round(((i+1)/times.length)*100)}%`;
  }
  if(!cuts.length){ if(prog) prog.textContent="No scene changes detected."; toast("No scene changes detected"); return; }
  const speed=clip.speed||1, origStart=clip.start, origIn=clip.inPoint||0, origDur=clip.duration;
  const timelineCuts=cuts.map(ct=>origStart+(ct-origIn)/speed).filter(tt=>tt>origStart+.15 && tt<origStart+origDur-.15);
  if(!timelineCuts.length){ if(prog) prog.textContent="Detected cuts were too close to the clip edges."; return; }
  let workingId=clipId, made=0;
  for(const tt of timelineCuts){
    const cf=getClipByIds(workingId,trackId); if(!cf) break;
    const c=cf.clip;
    if(tt<=c.start+.05 || tt>=c.start+c.duration-.05) continue;
    const before=deepClone(serializableProject());
    const elapsed=tt-c.start;
    const sourceDur=(c.outPoint??c.duration)-(c.inPoint||0);
    const ratio=c.duration?elapsed/c.duration:0;
    const right=deepClone(c); right.id=uid("clip"); right.start=tt; right.duration=(c.start+c.duration)-tt;
    right.inPoint=(c.inPoint||0)+sourceDur*ratio; right.transitionIn=null;
    c.duration=elapsed; c.outPoint=right.inPoint; c.transitionOut=null;
    const idx=cf.track.clips.findIndex(x=>x.id===c.id);
    cf.track.clips.splice(idx+1,0,right);
    const after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Scene cut",before,after}); project.history.index++;
    workingId=right.id; made++;
  }
  scheduleAutosave(); renderAll();
  if(prog) prog.textContent=`Done — ${made} scene cut(s) added.`;
  toast(`Scene detection complete — ${made} cut(s) added`);
}

/* ---------------- 29) Freeze Frame / Add Frame Hold ---------------- */
async function freezeFrameAtPlayhead(){
  const f=getClip();
  if(!f || f.track.kind!=="video" || !f.clip.assetId || f.clip.kind==="adjustment"){ toast("Select a video clip to freeze"); return; }
  const track=f.track, c=f.clip;
  if(currentTime<=c.start+.05 || currentTime>=c.start+c.duration-.05){ toast("Move the playhead inside the clip first"); return; }
  const _fd=await amiyoAsk("Freeze frame duration (seconds)","3",{number:true,min:.1,step:.1,okLabel:"Freeze"}); if(_fd===null) return;
  let freezeDur=Number(_fd);
  if(!Number.isFinite(freezeDur) || freezeDur<=0) freezeDur=3;
  const before=deepClone(serializableProject());
  const elapsed=currentTime-c.start;
  const sourceDur=(c.outPoint??c.duration)-(c.inPoint||0);
  const ratio=c.duration?elapsed/c.duration:0;
  const freezeAt=(c.inPoint||0)+sourceDur*ratio;
  const rightDuration=(c.start+c.duration)-currentTime;
  const right=deepClone(c);
  right.id=uid("clip"); right.start=currentTime+freezeDur; right.duration=rightDuration; right.inPoint=freezeAt; right.transitionIn=null;
  const frozen=deepClone(c);
  frozen.id=uid("clip"); frozen.name=(c.name||"Clip")+" — Freeze"; frozen.start=currentTime; frozen.duration=freezeDur;
  frozen.inPoint=freezeAt; frozen.outPoint=freezeAt; frozen.freeze=true; frozen.freezeAt=freezeAt;
  frozen.keyframes=[]; frozen.transitionIn=null; frozen.transitionOut=null;
  const originalEnd=c.start+c.duration;
  c.duration=elapsed; c.outPoint=freezeAt; c.transitionOut=null;
  const idx=track.clips.findIndex(x=>x.id===c.id);
  track.clips.splice(idx+1,0,frozen,right);
  for(const other of track.clips){
    if(other.id===c.id||other.id===frozen.id||other.id===right.id) continue;
    if(other.start>=originalEnd-.01) other.start+=freezeDur;
  }
  track.clips.sort((a,b)=>a.start-b.start);
  selectedClipId=frozen.id; selectedTrackId=track.id;
  const after=serializableProject();
  project.history.entries=project.history.entries.slice(0,project.history.index+1);
  project.history.entries.push({label:"Add freeze frame",before,after}); project.history.index++;
  scheduleAutosave(); renderAll();
  toast(`${freezeDur}s freeze frame inserted (ripples this track)`);
}
const origComputeSeek6=window.__amiyoComputeSeek;
window.__amiyoComputeSeek=function(clip,local){
  if(clip.freeze) return clip.freezeAt||0;
  return origComputeSeek6 ? origComputeSeek6(clip,local) : (clip.inPoint||0)+local*(clip.speed||1);
};

function injectAdvancedVideoPanel(){
  const f=getClip(); if(!f || f.track.kind!=="video" || !f.clip.assetId || f.clip.kind==="adjustment") return;
  const insp=$("inspector"); if(!insp || $("advVideoGroup")) return;
  const group=document.createElement("div"); group.className="group"; group.id="advVideoGroup";
  group.innerHTML=`<h3>Scene Detection & Freeze Frame</h3>
    <div style="font-size:10px;color:var(--muted);margin-bottom:8px">Auto-detect hard cuts in the source and split, or hold the current frame — same tools as Premiere's Scene Edit Detection and Add Frame Hold.</div>
    <button class="chip" id="btnDetectScenes">Detect & split scenes</button>
    <div id="sceneProgress" style="font-size:10px;color:var(--muted);margin:6px 0"></div>
    <button class="chip" id="btnFreezeFrame">Freeze frame at playhead</button>`;
  insp.appendChild(group);
  $("btnDetectScenes").onclick=()=>runSceneDetection(f.clip.id,f.track.id);
  $("btnFreezeFrame").onclick=()=>freezeFrameAtPlayhead();
}
const riPrev6=window.renderInspector;
window.renderInspector=function(){ riPrev6(); injectAdvancedVideoPanel(); };

/* ---------------- 30) Color Match ---------------- */
function applyColorFx(clip,name,value,defVal){
  clip.effects=clip.effects||[];
  let fx=clip.effects.find(x=>x.name===name);
  if(Math.abs(value-defVal)<0.0005){ clip.effects=clip.effects.filter(x=>x.name!==name); return; }
  if(!fx){ fx={id:uid("fx"),name,value,enabled:true}; clip.effects.push(fx); } else { fx.value=value; fx.enabled=true; }
}
try{ window.applyColorFx=applyColorFx; }catch(e){}
async function sampleClipAvgColor(clip){
  const asset=getAsset(clip.assetId); if(!asset) return null;
  const url=await ensureUrl(asset); if(!url) return null;
  const v=document.createElement("video"); v.muted=true; v.preload="auto"; v.src=url;
  await new Promise(res=>{ v.addEventListener("loadedmetadata",res,{once:true}); v.addEventListener("error",res,{once:true}); });
  const inP=clip.inPoint||0, outP=clip.outPoint??(inP+clip.duration);
  const mid=inP+(outP-inP)/2;
  await new Promise(res=>{
    const done=()=>{ v.removeEventListener("seeked",done); res(); };
    v.addEventListener("seeked",done,{once:true});
    try{ v.currentTime=Math.min(mid,(v.duration||mid)-.02); }catch{ res(); }
    setTimeout(res,900);
  });
  const w=64,h=36; const c=document.createElement("canvas"); c.width=w; c.height=h;
  const cx=c.getContext("2d",{willReadFrequently:true});
  let d;
  try{ cx.drawImage(v,0,0,w,h); d=cx.getImageData(0,0,w,h).data; }catch{ return null; }
  let r=0,g=0,b=0,n=0;
  for(let i=0;i<d.length;i+=4){ r+=d[i]; g+=d[i+1]; b+=d[i+2]; n++; }
  return n?{r:r/n,g:g/n,b:b/n}:null;
}
function getSelectedVideoClip6(){ const f=getClip(); if(!f||f.track.kind!=="video") return null; return f; }
async function runColorMatch(clipId,trackId,refId){
  const status=$("colorMatchStatus");
  if(!refId){ toast("No reference clip available"); return; }
  const f=getClipByIds(clipId,trackId); if(!f) return;
  let refClip=null; for(const t of project.tracks) for(const c of t.clips) if(c.id===refId) refClip=c;
  if(!refClip){ toast("Reference clip not found"); return; }
  if(status) status.textContent="Sampling colors…";
  const [cur,ref]=await Promise.all([sampleClipAvgColor(f.clip),sampleClipAvgColor(refClip)]);
  if(!cur||!ref){ if(status) status.textContent="Couldn't sample frames from one of the clips."; return; }
  const before=deepClone(serializableProject());
  const lumaOf=c=>(c.r*.299+c.g*.587+c.b*.114)/255;
  const exposure=1+clamp(lumaOf(ref)-lumaOf(cur),-.4,.4);
  const curRB=(cur.r-cur.b)/255, refRB=(ref.r-ref.b)/255;
  const temp=clamp((refRB-curRB)*260,-80,80);
  const curG_=cur.g/255-(cur.r+cur.b)/510, refG_=ref.g/255-(ref.r+ref.b)/510;
  const tint=clamp((refG_-curG_)*260,-80,80);
  const satOf=c=>(Math.max(c.r,c.g,c.b)-Math.min(c.r,c.g,c.b))/255;
  const satRatio=clamp((satOf(ref)||.01)/(satOf(cur)||.01),.5,1.8);
  applyColorFx(f.clip,"lumBrightness",exposure,1);
  applyColorFx(f.clip,"lumSaturation",satRatio,1);
  applyColorFx(f.clip,"lumTemp",temp,0);
  applyColorFx(f.clip,"lumTint",tint,0);
  const after=serializableProject();
  project.history.entries=project.history.entries.slice(0,project.history.index+1);
  project.history.entries.push({label:"Color match",before,after}); project.history.index++;
  scheduleAutosave(); renderAll();
  if(status) status.textContent="Matched — fine-tune further with the sliders above.";
  toast("Color match applied");
}
function injectColorMatchUI(){
  const left=$("leftPanel"); if(!left) return;
  const old=$("colorMatchCard6"); if(old) old.remove();
  const f=getSelectedVideoClip6(); if(!f) return;
  const others=[];
  for(const t of project.tracks) if(t.kind==="video") for(const c of t.clips) if(c.assetId && c.id!==f.clip.id && c.kind!=="adjustment") others.push(c);
  const card=document.createElement("div"); card.className="panel-card"; card.id="colorMatchCard6";
  card.innerHTML=`<h3 style="margin:0 0 6px;font-size:12px">Color Match</h3>
    <div style="font-size:10px;color:var(--muted);margin-bottom:6px">Sample another clip's color and auto-grade this clip to match it — like Lumetri's Color Match.</div>
    <select id="colorMatchRef" class="search">${others.length?others.map(c=>`<option value="${c.id}">${escapeHtml(c.name||(getAsset(c.assetId)?.name)||"Clip")}</option>`).join(""):`<option value="">No other video clips</option>`}</select>
    <button class="chip" id="colorMatchBtn" style="margin-top:8px" ${others.length?"":"disabled"}>Match color</button>
    <div id="colorMatchStatus" style="font-size:10px;color:var(--muted);margin-top:6px"></div>`;
  left.appendChild(card);
  $("colorMatchBtn").onclick=()=>runColorMatch(f.clip.id,f.track.id,$("colorMatchRef").value);
}

