/* ==================== Script 102 ==================== */
/* =========================================================================
   AMIYO PRO TOOLS — Batch 7 (4 new features)
   31) Trim Tool Suite — Slip (Y), Slide (U) and Rolling Edit (N), the three
       Premiere trim tools that aren't plain ripple/roll-free drag: Slip
       shifts a clip's source under a fixed position, Slide moves a clip and
       lets its neighbors absorb the gap, Rolling Edit drags the shared cut
       point between two adjacent clips.
   32) Project Panel Bins — organize imported media into folders (bins),
       exactly like Premiere's Project panel: create/delete bins, drag
       assets onto a bin chip to file them, filter the grid by bin.
   33) Multicam Angle Switching — group two or more video tracks as camera
       angles, sync their in points, then "go live" and tap number keys at
       the playhead to cut between angles in real time, building a real
       edited sequence the way Premiere's multi-camera monitoring does.
   34) Render Queue — an Adobe Media Encoder-style queue: stack up several
       exports at different resolution/bitrate presets and render them all
       in one pass with per-job progress bars, each downloading on completion.
   ========================================================================= */
(function(){
"use strict";

/* ---------------- 31) Trim Tool Suite: Slip / Slide / Rolling Edit ---------------- */
const trimToolMap={slip:"toolSlip",slide:"toolSlide",roll:"toolRoll"};
const baseSetTool7=window.setTool;
window.setTool=function(t){
  baseSetTool7(t);
  Object.values(trimToolMap).forEach(id=>$(id)&&$(id).classList.remove("tool-active"));
  if(trimToolMap[t]&&$(trimToolMap[t])) $(trimToolMap[t]).classList.add("tool-active");
};
$("toolSlip")&&($("toolSlip").onclick=()=>setTool("slip"));
$("toolSlide")&&($("toolSlide").onclick=()=>setTool("slide"));
$("toolRoll")&&($("toolRoll").onclick=()=>setTool("roll"));
document.addEventListener("keydown",e=>{
  const inField=["INPUT","TEXTAREA","SELECT"].includes(document.activeElement?.tagName);
  if(inField) return;
  const k=e.key.toLowerCase();
  if(k==="y"){setTool("slip");}
  else if(k==="u"){setTool("slide");}
  else if(k==="n"){setTool("roll");}
});

let trimDrag7=null;
document.addEventListener("pointerdown",e=>{
  if(!["slip","slide","roll"].includes(window.currentTool)) return;
  const tracksEl7=$("tracks"); if(!tracksEl7||!tracksEl7.contains(e.target)) return;
  const clipEl=e.target.closest(".clip"); if(!clipEl) return;
  e.preventDefault(); e.stopPropagation();
  const trackId=clipEl.dataset.track, clipId=clipEl.dataset.clip;
  const f=getClipByIds(clipId,trackId); if(!f) return;
  const track=f.track, clip=f.clip;
  const before7=deepClone(serializableProject());
  if(window.currentTool==="roll"){
    const idx=track.clips.indexOf(clip);
    const rect=clipEl.getBoundingClientRect();
    const nearLeft=(e.clientX-rect.left)<rect.width/2;
    const neighbor=nearLeft?track.clips[idx-1]:track.clips[idx+1];
    if(!neighbor){notify("No adjacent clip to roll against");return;}
    const leftClip=nearLeft?neighbor:clip, rightClip=nearLeft?clip:neighbor;
    trimDrag7={mode:"roll",trackId,leftId:leftClip.id,rightId:rightClip.id,startX:e.clientX,
      leftStart:leftClip.start,origBoundary:rightClip.start,rightOrigDur:rightClip.duration,rightOrigIn:rightClip.inPoint||0,before:before7};
  }else if(window.currentTool==="slip"){
    const asset=getAsset(clip.assetId);
    trimDrag7={mode:"slip",trackId,clipId,startX:e.clientX,origIn:clip.inPoint||0,origOut:clip.outPoint??clip.duration,
      speed:clip.speed||1,assetDur:asset&&asset.duration?asset.duration:Infinity,before:before7};
  }else if(window.currentTool==="slide"){
    const idx=track.clips.indexOf(clip);
    const prev=track.clips[idx-1], next=track.clips[idx+1];
    trimDrag7={mode:"slide",trackId,clipId,startX:e.clientX,origStart:clip.start,duration:clip.duration,
      prevId:prev?prev.id:null,prevOrigDur:prev?prev.duration:0,
      nextId:next?next.id:null,nextOrigStart:next?next.start:0,nextOrigDur:next?next.duration:0,nextOrigIn:next?(next.inPoint||0):0,before:before7};
  }
});
document.addEventListener("pointermove",e=>{
  if(!trimDrag7) return;
  const dt=(e.clientX-trimDrag7.startX)/getTimelinePx();
  const track=project.tracks.find(t=>t.id===trimDrag7.trackId); if(!track) return;
  if(trimDrag7.mode==="slip"){
    const f=getClipByIds(trimDrag7.clipId,trimDrag7.trackId); if(!f) return;
    let delta=dt*trimDrag7.speed;
    let newIn=trimDrag7.origIn+delta, newOut=trimDrag7.origOut+delta;
    if(newIn<0){delta-=newIn;newIn=0;newOut=trimDrag7.origOut+delta;}
    if(newOut>trimDrag7.assetDur){const over=newOut-trimDrag7.assetDur;newOut-=over;newIn-=over;}
    f.clip.inPoint=Math.max(0,newIn); f.clip.outPoint=newOut;
    renderTracks(); renderInspector();
  }else if(trimDrag7.mode==="slide"){
    const f=getClipByIds(trimDrag7.clipId,trimDrag7.trackId); if(!f) return;
    const minStart=trimDrag7.prevId?(track.clips.find(x=>x.id===trimDrag7.prevId).start+0.05-trimDrag7.origStart+trimDrag7.origStart):0;
    const lo=trimDrag7.prevId?(trimDrag7.origStart-(trimDrag7.prevOrigDur-0.05)):0;
    const hi=trimDrag7.nextId?(trimDrag7.origStart+(trimDrag7.nextOrigDur-0.05)):Infinity;
    const newStart=clamp(trimDrag7.origStart+dt,lo,hi);
    const totalDelta=newStart-trimDrag7.origStart;
    f.clip.start=newStart;
    if(trimDrag7.prevId){const p=track.clips.find(x=>x.id===trimDrag7.prevId); if(p) p.duration=trimDrag7.prevOrigDur+totalDelta;}
    if(trimDrag7.nextId){
      const nx=track.clips.find(x=>x.id===trimDrag7.nextId);
      if(nx){nx.start=trimDrag7.nextOrigStart+totalDelta; nx.duration=trimDrag7.nextOrigDur-totalDelta;
        if(nx.inPoint!=null) nx.inPoint=Math.max(0,trimDrag7.nextOrigIn+totalDelta*(nx.speed||1));}
    }
    renderTracks(); renderInspector();
  }else if(trimDrag7.mode==="roll"){
    const leftClip=track.clips.find(x=>x.id===trimDrag7.leftId), rightClip=track.clips.find(x=>x.id===trimDrag7.rightId);
    if(!leftClip||!rightClip) return;
    const newBoundary=clamp(trimDrag7.origBoundary+dt, trimDrag7.leftStart+0.05, trimDrag7.origBoundary+trimDrag7.rightOrigDur-0.05);
    const boundaryDelta=newBoundary-trimDrag7.origBoundary;
    leftClip.duration=newBoundary-trimDrag7.leftStart;
    rightClip.start=newBoundary; rightClip.duration=trimDrag7.rightOrigDur-boundaryDelta;
    if(rightClip.inPoint!=null) rightClip.inPoint=Math.max(0,trimDrag7.rightOrigIn+boundaryDelta*(rightClip.speed||1));
    renderTracks(); renderInspector();
  }
});
document.addEventListener("pointerup",()=>{
  if(!trimDrag7) return;
  const after7=deepClone(serializableProject());
  if(JSON.stringify(trimDrag7.before)!==JSON.stringify(after7)){
    project.history.entries=(project.history.entries||[]).slice(0,(project.history.index??-1)+1);
    const label7=trimDrag7.mode==="slip"?"Slip":trimDrag7.mode==="slide"?"Slide":"Rolling edit";
    project.history.entries.push({label:label7,before:trimDrag7.before,after:after7});
    project.history.index++;
    scheduleAutosave();
  }
  trimDrag7=null; renderAll();
});

/* ---------------- 32) Project Panel Bins ---------------- */
function ensureBins7(){ if(!project.bins) project.bins=[]; return project.bins; }
let activeBinId7=null;
function createBin7(name){
  ensureBins7();
  const bin={id:uid("bin"),name:name||("Bin "+(project.bins.length+1))};
  project.bins.push(bin); scheduleAutosave(); renderLeftPanel();
}
function deleteBin7(id){
  ensureBins7();
  project.bins=project.bins.filter(b=>b.id!==id);
  Object.values(project.assets).forEach(a=>{if(a.binId===id)a.binId=null;});
  if(activeBinId7===id) activeBinId7=null;
  scheduleAutosave(); renderLeftPanel();
}
function moveAssetToBin7(assetId,binId){
  const a=project.assets[assetId]; if(!a) return;
  a.binId=binId||null; scheduleAutosave(); renderLeftPanel();
}
const baseRenderMediaPanel7=window.renderMediaPanel;
window.renderMediaPanel=function(){
  ensureBins7();
  const bins=project.bins, all=Object.values(project.assets);
  const shown=activeBinId7==null?all:all.filter(a=>a.binId===activeBinId7);
  return `<div class="panel-card">
    <input class="search" id="mediaSearch" placeholder="Search media…"/>
    <div class="mini-row" style="margin-top:8px"><button class="chip" id="importBtn">Import files</button><button class="chip" id="demoBtn">Load demo</button></div>
    <div class="mini-row" style="flex-wrap:wrap;gap:6px;margin-top:8px">
      <button class="chip ${activeBinId7==null?"tool-active":""}" data-bin="">All Media</button>
      ${bins.map(b=>`<button class="chip ${activeBinId7===b.id?"tool-active":""}" data-bin="${b.id}">📁 ${escapeHtml(b.name)}</button>`).join("")}
      <button class="chip" id="newBinBtn">+ New Bin</button>
      ${activeBinId7?`<button class="chip" id="deleteBinBtn">🗑 Delete Bin</button>`:""}
    </div></div>
  <div class="asset-grid">${shown.length?shown.map(a=>`<div class="asset" data-asset="${a.id}" draggable="true">
    <div class="thumb">${thumbHTML(a)}</div>
    <div class="asset-meta"><b>${escapeHtml(a.name)}</b><span>${a.type} · ${fmt(a.duration)}</span></div>
  </div>`).join(""):`<div class="panel-card" style="grid-column:1/-1;color:var(--muted);font-size:11px">${activeBinId7?"This bin is empty — drag media onto a bin chip above to file it here.":"No media yet. Import video, audio, or images to begin."}</div>`}</div>`;
};
const baseBindLeftPanel7=window.bindLeftPanel;
window.bindLeftPanel=function(){
  baseBindLeftPanel7();
  if(activePanel!=="media") return;
  $("leftPanel").querySelectorAll("[data-bin]").forEach(btn=>{
    btn.addEventListener("click",()=>{activeBinId7=btn.dataset.bin||null;renderLeftPanel();});
    btn.addEventListener("dragover",e=>e.preventDefault());
    btn.addEventListener("drop",e=>{e.preventDefault();const assetId=e.dataTransfer.getData("text/amiyo-asset");if(assetId)moveAssetToBin7(assetId,btn.dataset.bin||null);});
  });
  $("newBinBtn")&&($("newBinBtn").onclick=async()=>{const name=await amiyoAsk("Bin name","New Bin");if(name&&name.trim())createBin7(name.trim());});
  $("deleteBinBtn")&&($("deleteBinBtn").onclick=async()=>{if(activeBinId7&&await amiyoOk("Delete this bin? Media moves back to All Media.",{okLabel:"Delete",danger:true}))deleteBin7(activeBinId7);});
  $("leftPanel").querySelectorAll(".asset[draggable]").forEach(el=>{
    el.addEventListener("dragstart",e=>e.dataTransfer.setData("text/amiyo-asset",el.dataset.asset));
  });
};

/* ---------------- 33) Multicam Angle Switching ---------------- */
let multicamGroup7=[], multicamActiveTrackId7=null, multicamLive7=false;
const MC_COLORS7=["#ff5d5d","#ff884d","#3ddc97","#ffb84d","#c084fc","#ee6622","#f472b6","#a3e635","#fb923c"];
let multicamStack7=[], multicamLast7=null;
const mcTc7=s=>{s=Math.max(0,s||0);const m=Math.floor(s/60),x=s-m*60;return m+":"+(x<10?"0":"")+x.toFixed(1)};
const mcTrack7=id=>project.tracks.find(t=>t.id===id);
const mcClipAt7=(t,time)=>t&&t.clips.find(c=>time>=c.start-0.001&&time<c.start+c.duration-0.001);
const mcHasFootage7=id=>!!mcClipAt7(mcTrack7(id),currentTime);
function mcOnAir7(){
  if(multicamLive7&&multicamActiveTrackId7) return multicamActiveTrackId7;
  for(const id of multicamGroup7){const c=mcClipAt7(mcTrack7(id),currentTime); if(c&&(c.opacity==null?1:c.opacity)>.01) return id;}
  return null;
}
function mcCss7(){
  if(document.getElementById("mc-css")) return;
  const st=document.createElement("style"); st.id="mc-css";
  st.textContent=".mc-h{font-size:10px;color:var(--muted);margin:12px 0 6px;letter-spacing:.04em;text-transform:uppercase}"+
  ".mc-card{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px;margin-bottom:6px;border:1px solid var(--line);border-left:4px solid var(--c,#555);border-radius:8px;background:var(--panel2,#151310);font-size:12px}"+
  ".mc-card.off{opacity:.8;border-left-color:var(--line)}.mc-num{flex:none;width:24px;height:24px;border-radius:50%;background:var(--c);color:#111;font-weight:800;display:grid;place-items:center;font-size:12px}"+
  ".mc-name{flex:1 1 80px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mc-btns{display:flex;gap:6px;margin-left:auto}.mc-name.full{flex:1 1 calc(100% - 40px)}.mc-b{flex:none;min-width:40px;min-height:40px;border:1px solid var(--line);background:#151310;color:var(--text);border-radius:8px;cursor:pointer;font-size:12px}"+
  ".mc-b:disabled{opacity:.3;cursor:default}.mc-air{display:flex;align-items:center;gap:8px;padding:10px;border-radius:8px;background:#1a1410;border:1px solid var(--line);font-size:12px;margin-bottom:8px}"+
  ".mc-dot{width:10px;height:10px;border-radius:50%;background:#555;flex:none}.mc-live .mc-dot{background:#ff3b30;box-shadow:0 0 0 3px rgba(255,59,48,.25)}"+
  ".mc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:8px;margin-bottom:8px}"+
  ".mc-cut{min-height:64px;border-radius:10px;border:2px solid var(--line);border-top:5px solid var(--c);background:#151310;color:var(--text);cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font-size:11px;padding:4px}"+
  ".mc-cut b{font-size:18px}.mc-cut.air{border-color:#ff3b30;background:#2a1412}.mc-cut:disabled{opacity:.35;cursor:not-allowed}.mc-cut:active:not(:disabled){transform:scale(.97)}"+
  ".mc-go{width:100%;min-height:48px;border-radius:10px;border:1px solid var(--line);background:#151310;color:var(--text);font-size:13px;font-weight:700;cursor:pointer}.mc-go.on{background:#ff3b30;border-color:#ff3b30;color:#fff}.mc-go:disabled{opacity:.4}";
  document.head.appendChild(st);
}
function renderMulticamPanel7(){
  mcCss7();
  const vt=project.tracks.filter(t=>t.kind==="video");
  const grp=multicamGroup7.map(mcTrack7).filter(Boolean), rest=vt.filter(t=>!grp.includes(t));
  const ready=grp.length>=2, air=mcOnAir7(), at=mcTrack7(air);
  const col=i=>MC_COLORS7[i%MC_COLORS7.length];
  const cards=grp.map((t,i)=>`<div class="mc-card" style="--c:${col(i)}" role="group" aria-label="Angle ${i+1}: ${escapeHtml(t.name)}"><span class="mc-num">${i+1}</span><span class="mc-name full">${escapeHtml(t.name)}</span><span class="mc-btns">
    <button type="button" class="mc-b" data-mc-up="${t.id}" ${i===0?"disabled":""} aria-label="Move ${escapeHtml(t.name)} up (angle ${i})">▲</button>
    <button type="button" class="mc-b" data-mc-down="${t.id}" ${i===grp.length-1?"disabled":""} aria-label="Move ${escapeHtml(t.name)} down (angle ${i+2})">▼</button>
    <button type="button" class="mc-b" data-mc-rm="${t.id}" aria-label="Remove ${escapeHtml(t.name)} from multicam">✕</button></span></div>`).join("");
  const others=rest.map(t=>`<div class="mc-card off"><span class="mc-name">${escapeHtml(t.name)}</span><button type="button" class="mc-b" style="padding:0 12px" data-mc-add="${t.id}" aria-label="Add ${escapeHtml(t.name)} as a camera angle">＋ Add</button></div>`).join("");
  const grid=multicamLive7?`<div class="mc-grid" role="group" aria-label="Tap an angle to cut to it">${grp.map((t,i)=>`<button type="button" class="mc-cut${t.id===air?" air":""}" style="--c:${col(i)}" data-mc-cut="${t.id}" ${mcHasFootage7(t.id)?"":"disabled"} aria-label="Cut to angle ${i+1}, ${escapeHtml(t.name)}"><b>${i+1}</b><span>${escapeHtml(t.name)}</span></button>`).join("")}</div>`:"";
  return `<div class="panel-card ${multicamLive7?"mc-live":""}"><h3 style="margin:0 0 4px;font-size:12px">Multicam</h3>
    <div style="font-size:10px;color:var(--muted);line-height:1.5">Three steps: pick the angles, line them up, then go live and tap an angle to cut at the playhead while the video plays.</div>
    <div class="mc-h">1 · Angles${grp.length?" ("+grp.length+")":""}</div>
    ${cards||'<div style="font-size:11px;color:var(--muted);margin-bottom:6px">No angles yet — add two or more video tracks below.</div>'}
    ${others}
    ${vt.length<2?'<div style="font-size:11px;color:var(--muted)">You need at least two video tracks for multicam.</div>':""}
    <div class="mc-h">2 · Line them up</div>
    <button type="button" class="chip" id="mcSyncBtn" ${ready?"":"disabled"} style="width:100%">Sync angles to the same start</button>
    <div class="mc-h">3 · Cut live</div>
    <div class="mc-air"><span class="mc-dot"></span><span id="mcAirName" role="status">${at?"On air: "+escapeHtml(at.name):"On air: —"}</span><span id="mcAirTime" aria-hidden="true" style="margin-left:auto;font-family:var(--font-mono,monospace)">${mcTc7(currentTime)}</span></div>
    ${grid}
    <button type="button" class="mc-go${multicamLive7?" on":""}" id="mcLiveBtn" ${ready?"":"disabled"} aria-pressed="${multicamLive7}">${multicamLive7?"■ Stop live cutting":"● Go live"}</button>
    ${ready?"":'<div style="font-size:10px;color:var(--muted);margin-top:6px">Add at least two angles to go live.</div>'}
    ${multicamStack7.length?`<button type="button" class="chip" id="mcUndoCut" style="width:100%;margin-top:8px">↶ Undo last cut${multicamLast7?" ("+escapeHtml(multicamLast7)+")":""}</button>`:""}
    <div style="font-size:10px;color:var(--muted);margin-top:8px">${multicamLive7?`Tap a big button, or press 1–${grp.length} on a keyboard. Greyed angles have no footage at the playhead.`:""}</div>
  </div>`;
}
function bindMulticamPanel7(){
  const lp=$("leftPanel"), redo=()=>renderLeftPanel();
  lp.querySelectorAll("[data-mc-add]").forEach(b=>b.onclick=()=>{ if(!multicamGroup7.includes(b.dataset.mcAdd)) multicamGroup7.push(b.dataset.mcAdd); redo(); });
  lp.querySelectorAll("[data-mc-rm]").forEach(b=>b.onclick=()=>{ const id=b.dataset.mcRm; multicamGroup7=multicamGroup7.filter(x=>x!==id); if(multicamActiveTrackId7===id) multicamActiveTrackId7=multicamGroup7[0]||null; if(multicamGroup7.length<2) multicamLive7=false; redo(); });
  const mv=(id,d)=>{ const i=multicamGroup7.indexOf(id), j=i+d; if(i<0||j<0||j>=multicamGroup7.length) return; [multicamGroup7[i],multicamGroup7[j]]=[multicamGroup7[j],multicamGroup7[i]]; redo(); };
  lp.querySelectorAll("[data-mc-up]").forEach(b=>b.onclick=()=>mv(b.dataset.mcUp,-1));
  lp.querySelectorAll("[data-mc-down]").forEach(b=>b.onclick=()=>mv(b.dataset.mcDown,1));
  lp.querySelectorAll("[data-mc-cut]").forEach(b=>b.onclick=()=>cutToAngle7(b.dataset.mcCut));
  $("mcUndoCut")&&($("mcUndoCut").onclick=()=>{ window.undo(); multicamActiveTrackId7=multicamStack7.pop()||multicamGroup7[0]||null; multicamLast7=null; renderLeftPanel(); notify("Last cut undone"); });
  $("mcSyncBtn")&&($("mcSyncBtn").onclick=()=>{
    if(multicamGroup7.length<2) return notify("Add at least two angles first");
    transact("Sync multicam angles",()=>{
      const tracks=multicamGroup7.map(mcTrack7).filter(Boolean);
      const latestStart=Math.max(...tracks.map(t=>t.clips[0]?.start??0));
      tracks.forEach(t=>{const shift=latestStart-(t.clips[0]?.start??0);t.clips.forEach(c=>c.start+=shift);});
    });
    notify("Angles synced to the same start");
  });
  $("mcLiveBtn")&&($("mcLiveBtn").onclick=()=>{
    if(multicamGroup7.length<2) return notify("Add at least two angles first");
    multicamLive7=!multicamLive7;
    if(multicamLive7){multicamActiveTrackId7=multicamGroup7[0];multicamStack7=[];notify("Live — tap an angle to cut");}
    else notify("Live cutting off");
    renderLeftPanel();
  });
}
setInterval(()=>{
  if(activePanel!=="multicam") return;
  const n=document.getElementById("mcAirName"); if(!n) return;
  const id=mcOnAir7(), t=mcTrack7(id), txt=t?"On air: "+t.name:"On air: —";
  if(n.textContent!==txt) n.textContent=txt;
  const tm=document.getElementById("mcAirTime"); if(tm) tm.textContent=mcTc7(currentTime);
  document.querySelectorAll("[data-mc-cut]").forEach(b=>{ b.disabled=!mcHasFootage7(b.dataset.mcCut); b.classList.toggle("air",b.dataset.mcCut===id); });
},250);
const baseRenderLeftPanel7=window.renderLeftPanel;
window.renderLeftPanel=function(){
  if(activePanel==="multicam"){$("leftPanel").innerHTML=renderMulticamPanel7();bindMulticamPanel7();return;}
  baseRenderLeftPanel7();
};
function cutToAngle7(trackId){
  if(trackId===multicamActiveTrackId7){ notify("Already on that angle"); return; }
  const canCut=multicamGroup7.some(tid=>{const t=mcTrack7(tid); return t&&t.clips.some(c=>currentTime>c.start+0.02&&currentTime<c.start+c.duration-0.02);});
  if(!canCut){ notify("No angle has footage at the playhead — move it onto your clips first",3600); return; }
  multicamStack7.push(multicamActiveTrackId7); multicamLast7=(project.tracks.find(t=>t.id===trackId)||{}).name||"angle";
  const before7=deepClone(serializableProject());
  for(const tid of multicamGroup7){
    const track=project.tracks.find(t=>t.id===tid); if(!track) continue;
    const idx=track.clips.findIndex(c=>currentTime>c.start+0.02&&currentTime<c.start+c.duration-0.02);
    if(idx>=0){
      const clip=track.clips[idx];
      const right=deepClone(clip); right.id=uid("clip"); right.start=currentTime; right.duration=(clip.start+clip.duration)-currentTime;
      const elapsed=currentTime-clip.start;
      const sourceDur=(clip.outPoint??clip.duration)-(clip.inPoint??0);
      const sourceRatio=clip.duration?elapsed/clip.duration:0;
      right.inPoint=(clip.inPoint||0)+sourceDur*sourceRatio;
      clip.duration=elapsed; clip.outPoint=right.inPoint;
      track.clips.splice(idx+1,0,right);
      right.opacity=(tid===trackId)?1:0; right.volume=(tid===trackId)?1:0;
    }
  }
  multicamActiveTrackId7=trackId;
  const after7=serializableProject();
  project.history.entries=(project.history.entries||[]).slice(0,(project.history.index??-1)+1);
  project.history.entries.push({label:"Multicam cut to angle",before:before7,after:after7}); project.history.index++;
  scheduleAutosave(); renderAll(); renderLeftPanel();
  notify("Cut to "+(project.tracks.find(t=>t.id===trackId)?.name||"angle"));
}
document.addEventListener("keydown",e=>{
  if(!multicamLive7) return;
  const inField=["INPUT","TEXTAREA","SELECT"].includes(document.activeElement?.tagName);
  if(inField) return;
  const n=Number(e.key);
  if(n>=1&&n<=multicamGroup7.length){e.preventDefault();cutToAngle7(multicamGroup7[n-1]);}
});

/* ---------------- 34) Render Queue (Adobe Media Encoder-style) ---------------- */
const renderQueuePresets7=[
  {id:"source",label:"Match Source",w:null,h:null,bitrate:8000000},
  {id:"yt1080",label:"YouTube 1080p (1920×1080)",w:1920,h:1080,bitrate:12000000},
  {id:"ig-square",label:"Instagram Square (1080×1080)",w:1080,h:1080,bitrate:8000000},
  {id:"tw720",label:"Twitter/X 720p (1280×720)",w:1280,h:720,bitrate:5000000},
  {id:"reels1080",label:"Reels / Shorts / TikTok (1080×1920)",w:1080,h:1920,bitrate:10000000},
  {id:"phone720",label:"Phone 720p vertical (720×1280)",w:720,h:1280,bitrate:4000000}
];
let renderQueue7=[];
let rqRunning7=false, rqSig7="", rqLast7=0;
function rqDur7(){ return Math.max(1,window.amiyoContentEnd?window.amiyoContentEnd():getProjectDuration()); }
function rqEta7(s){ s=Math.max(0,Math.round(s)); if(s<5) return "a few seconds"; if(s<60) return s+" s"; const m=Math.floor(s/60), r=s%60; return m+" min"+(m<10&&r?" "+r+" s":""); }
function rqMb7(j){ const mb=(j.preset.bitrate||8e6)*rqDur7()/8/1048576; return mb<10?mb.toFixed(1):Math.round(mb); }
function rqLeft7(j){ return j.status==="Rendering"?(j.dur||rqDur7())*(1-(j.progress||0)):j.status==="Queued"?rqDur7():0; }
function rqLine7(j){
  if(j.status==="Queued") return "Waiting · about "+rqEta7(rqLeft7(j))+" · file ≈ "+rqMb7(j)+" MB";
  if(j.status==="Rendering") return Math.round((j.progress||0)*100)+"% · about "+rqEta7(rqLeft7(j))+" left";
  if(j.status==="Done") return "Done · saved to your downloads as .webm";
  if(j.status==="Cancelled") return "Cancelled · nothing was saved";
  return "Failed: "+(j.err||"unknown problem");
}
function rqSumText7(){
  const w=renderQueue7.filter(j=>j.status==="Queued").length, run=renderQueue7.find(j=>j.status==="Rendering");
  const left=renderQueue7.reduce((a,j)=>a+rqLeft7(j),0);
  if(!w&&!run) return renderQueue7.length?"No jobs waiting.":"";
  return (run?"1 rendering":"")+(run&&w?", ":"")+(w?w+" waiting":"")+" · about "+rqEta7(left)+" left in total. Each export plays in real time, so keep this screen on.";
}
function rqRowsHtml7(){
  return renderQueue7.length?renderQueue7.map(j=>{
    const bad=j.status==="Error", act=j.status==="Rendering"?"cancel":(bad||j.status==="Cancelled")?"retry":"";
    return `<div class="panel-card" style="margin-bottom:6px">
      <div style="display:flex;justify-content:space-between;gap:6px;font-size:11px"><b style="min-width:0;overflow-wrap:anywhere">${escapeHtml(j.name)}</b><span>${j.status}</span></div>
      <div style="height:5px;background:#30231c;border-radius:3px;margin-top:6px;overflow:hidden"><div data-p="${j.id}" style="height:100%;width:${Math.round((j.progress||0)*100)}%;background:${bad?"#ff506b":"#ff8a4f"}"></div></div>
      <div data-e="${j.id}" style="font-size:10.5px;margin-top:4px;color:${bad?"#ff91a0":"var(--muted)"}">${escapeHtml(rqLine7(j))}</div>
      <div class="mini-row" style="margin-top:6px">${act?`<button type="button" class="chip" data-rq="${act}" data-id="${j.id}" style="min-height:38px">${act==="cancel"?"Cancel":"Retry"}</button>`:""}${j.status!=="Rendering"?`<button type="button" class="chip" data-rq="remove" data-id="${j.id}" style="min-height:38px">Remove</button>`:""}</div>
    </div>`; }).join(""):`<div style="font-size:11px;color:var(--muted)">Queue is empty. Pick a preset above and tap Add.</div>`;
}
function refreshRQ7(force){
  const list=$("rqList"); if(!list) return;
  const sig=renderQueue7.map(j=>j.id+":"+j.status+":"+(j.err||"")).join("|")+"|"+rqRunning7, now=performance.now();
  if(force||sig!==rqSig7){ rqSig7=sig; list.innerHTML=rqRowsHtml7();
    const st=$("rqStartBtn"), sp=$("rqStopBtn"), cl=$("rqClearBtn");
    if(st) st.disabled=rqRunning7; if(sp) sp.style.display=rqRunning7?"":"none"; if(cl) cl.disabled=!renderQueue7.some(j=>j.status==="Done"||j.status==="Cancelled"||j.status==="Error"); }
  else if(now-rqLast7<250) return;
  rqLast7=now;
  renderQueue7.forEach(j=>{ const p=list.querySelector('[data-p="'+j.id+'"]'), e=list.querySelector('[data-e="'+j.id+'"]'); if(p) p.style.width=Math.round((j.progress||0)*100)+"%"; if(e) e.textContent=rqLine7(j); });
  const sm=$("rqSum"); if(sm) sm.textContent=rqSumText7();
}
function openRenderQueue7(){
  openModal("Render Queue",`<div style="min-width:340px">
    <div class="mini-row" style="margin-bottom:6px">
      <select id="rqPreset" class="search">${renderQueuePresets7.map(p=>`<option value="${p.id}">${p.label}</option>`).join("")}</select>
      <button class="chip" id="rqAddBtn">+ Add to Queue</button>
    </div>
    <div id="rqSum" role="status" aria-live="polite" style="font-size:11px;line-height:1.5;margin-bottom:8px"></div>
    <div id="rqList"></div>
    <div class="mini-row" style="margin-top:8px"><button class="chip" id="rqStartBtn" style="min-height:44px">▶ Start Queue</button><button class="chip" id="rqStopBtn" style="min-height:44px;display:none">■ Stop queue</button><button class="chip" id="rqClearBtn" style="min-height:44px">Clear finished</button></div>
  </div>`);
  $("rqAddBtn").onclick=()=>{
    const preset=renderQueuePresets7.find(p=>p.id===$("rqPreset").value);
    renderQueue7.push({id:uid("job"),name:(project.metadata.name||"amiyo-edit")+" — "+preset.label,preset,status:"Queued",progress:0});
    refreshRQ7(true);
  };
  $("rqStartBtn").onclick=()=>runRenderQueue7();
  $("rqStopBtn").onclick=()=>{ window.__rqStop=true; notify("Stopping after the current frame…"); };
  $("rqClearBtn").onclick=()=>{ renderQueue7=renderQueue7.filter(j=>j.status==="Queued"||j.status==="Rendering"); refreshRQ7(true); };
  $("rqList").onclick=e=>{
    const b=e.target.closest&&e.target.closest("[data-rq]"); if(!b) return;
    const j=renderQueue7.find(x=>x.id===b.dataset.id); if(!j) return;
    if(b.dataset.rq==="remove"&&j.status!=="Rendering") renderQueue7=renderQueue7.filter(x=>x!==j);
    else if(b.dataset.rq==="cancel") j.cancel=true;
    else if(b.dataset.rq==="retry"){ j.status="Queued"; j.progress=0; j.err=""; j.cancelled=false; j.cancel=false; if(!rqRunning7) notify("Back in the queue. Tap Start Queue."); }
    refreshRQ7(true);
  };
  rqSig7=""; refreshRQ7(true);
}
async function renderJob7(job){
  const w=job.preset.w||project.settings.width, h=job.preset.h||project.settings.height;
  const off=document.createElement("canvas"); off.width=w; off.height=h;
  const octx=off.getContext("2d");
  const stream=off.captureStream(project.settings.fps||30);
  try{
    await getAudioContext();
    if(audioDestination){
      for(const tr of project.tracks) if(tr.kind==="audio") for(const c of tr.clips) await ensureAudioElement(c);
      for(const tr of project.tracks) if(tr.kind==="audio") for(const c of tr.clips){const el=audioEls.get(c.id);if(el){el.pause();el.volume=clamp(c.volume??1,0,1);el.currentTime=Math.max(0,c.inPoint||0);}}
      for(const at of audioDestination.stream.getAudioTracks()) stream.addTrack(at);
    }
  }catch{}
  const preferred=["video/webm;codecs=vp9","video/webm;codecs=vp8","video/webm"];
  const supported=preferred.find(x=>MediaRecorder.isTypeSupported?.(x))||"";
  let recorder;
  try{recorder=supported?new MediaRecorder(stream,{mimeType:supported,videoBitsPerSecond:job.preset.bitrate}):new MediaRecorder(stream);}
  catch(e){throw e;}
  const chunks=[]; recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);
  const old=currentTime; currentTime=0; await renderPreviewFrame();
  return new Promise((resolve,reject)=>{
    function drawScaled(){
      octx.fillStyle="#000"; octx.fillRect(0,0,w,h);
      const scale=Math.min(w/canvas.width,h/canvas.height);
      const dw=canvas.width*scale, dh=canvas.height*scale;
      octx.drawImage(canvas,(w-dw)/2,(h-dh)/2,dw,dh);
    }
    recorder.onstop=()=>{window.__amiyoExporting=false;isPlaying=false;pause();currentTime=old;renderAll();resolve(new Blob(chunks,{type:recorder.mimeType||"video/webm"}));};
    recorder.onerror=err=>reject(err);
    recorder.start(250);
    const start=performance.now(), dur=Math.max(.1,window.amiyoContentEnd?window.amiyoContentEnd():getProjectDuration());
    window.__amiyoExporting=true; isPlaying=true;
    const loop0=async now=>{
      if(job.cancel||window.__rqStop){ job.cancelled=true; recorder.stop(); return; }
      currentTime=(now-start)/1000;
      if(currentTime>=dur){currentTime=Math.max(0,dur-.02);await renderPreviewFrame();drawScaled();recorder.stop();return;}
      await renderPreviewFrame(); await updateAudioPlayback(); drawScaled();
      job.progress=clamp(currentTime/dur,0,1); refreshRQ7();
      requestAnimationFrame(loop);
    };
    /* Step 8: a failed frame ends this job with an error instead of hanging the whole queue */
    const loop=now=>{ loop0(now).catch(err=>{
      window.__amiyoExporting=false; isPlaying=false; try{ pause(); }catch(e){window.__swl&&window.__swl(e)}
      reject(err); try{ if(recorder.state!=="inactive") recorder.stop(); }catch(e){window.__swl&&window.__swl(e)}
    }); };
    requestAnimationFrame(loop);
  });
}
async function runRenderQueue7(){
  if(rqRunning7) return;
  if(!renderQueue7.some(j=>j.status==="Queued")) return notify(renderQueue7.length?"Nothing is waiting. Add a job or retry one.":"Queue is empty");
  if(!("MediaRecorder" in window)||!viewCanvas.captureStream){notify("This browser can't render exports");return;}
  pause(); rqRunning7=true; window.__rqStop=false;
  let wl=null, ok=0, bad=0, stopped=false;
  try{ if(navigator.wakeLock) wl=await navigator.wakeLock.request("screen"); }catch(e){window.__swl&&window.__swl(e)}
  refreshRQ7(true);
  for(const job of renderQueue7.slice()){
    if(window.__rqStop){ stopped=true; break; }
    if(renderQueue7.indexOf(job)<0||job.status!=="Queued") continue;
    job.status="Rendering"; job.cancel=false; job.cancelled=false; job.err=""; job.progress=0; job.dur=rqDur7(); refreshRQ7(true);
    try{
      const blob=await renderJob7(job);
      if(job.cancelled){ job.status="Cancelled"; stopped=stopped||!!window.__rqStop; }
      else{
        job.status="Done"; job.progress=1; ok++;
        const url=URL.createObjectURL(blob); const a=document.createElement("a");
        a.href=url; a.download=job.name.replace(/[^a-z0-9\-_. ]/gi,"_")+".webm"; a.click(); setTimeout(()=>URL.revokeObjectURL(url),4000);
      }
    }catch(e){ job.status="Error"; job.err=String((e&&e.message)||e||"the recorder stopped").slice(0,140); bad++; try{ window.amiyoReportError&&window.amiyoReportError("A queued export failed",e,{quiet:true}); }catch(x){window.__swl&&window.__swl(x)} }
    refreshRQ7(true);
  }
  rqRunning7=false; window.__rqStop=false; try{ wl&&wl.release(); }catch(e){window.__swl&&window.__swl(e)}
  refreshRQ7(true);
  notify(stopped?"Queue stopped":ok+" export"+(ok===1?"":"s")+" finished"+(bad?", "+bad+" failed":""),4500);
}
$("renderQueueBtn")&&($("renderQueueBtn").onclick=openRenderQueue7);

})();

