/* ==================== Script 103 ==================== */
/* ---------------- 34) Welcome / drop-to-start overlay ----------------
   Makes the "bring your own video" workflow obvious the moment the app
   opens: a centered call-to-action sits over the empty canvas, accepts
   a click-to-browse or a direct drag-and-drop, and quietly disappears
   once real media is on the project. */
(function(){
  const stage=document.querySelector(".preview-stage");
  if(!stage) return;
  const overlay=document.createElement("div");
  overlay.className="welcome-overlay";
  overlay.id="welcomeOverlay";
  overlay.innerHTML=`
    <div class="welcome-dropzone" id="welcomeDropzone">
      <div class="welcome-icon">🎬</div>
      <h2>Bring in your video to start editing</h2>
      <p>Drop a video, audio, or image file anywhere on this window, or click below to browse your files. Amiyo keeps everything on this device.</p>
      <div class="welcome-cta" id="welcomeImportBtn">＋ Import media</div>
    </div>
    <div class="welcome-hint">
      <span>MP4 · MOV · WEBM · MP3 · WAV · JPG · PNG</span>
      <span>Or press "Load demo" in the Media panel to explore first</span>
    </div>`;
  stage.appendChild(overlay);

  function hasMedia(){ return !!(project && project.assets && Object.keys(project.assets).length); }
  function refreshWelcomeOverlay(){
    if(!overlay) return;
    overlay.classList.toggle("hide", hasMedia());
  }
  window.refreshWelcomeOverlay=refreshWelcomeOverlay;

  $("welcomeImportBtn")?.addEventListener("click",()=>$("fileInput")?.click());
  ["dragenter","dragover"].forEach(ev=>overlay.addEventListener(ev,e=>{e.preventDefault();overlay.classList.add("drag-over");}));
  ["dragleave","dragend"].forEach(ev=>overlay.addEventListener(ev,e=>{e.preventDefault();overlay.classList.remove("drag-over");}));
  overlay.addEventListener("drop",e=>{
    e.preventDefault(); e.stopPropagation();
    overlay.classList.remove("drag-over");
    if(e.dataTransfer?.files?.length) importFiles(e.dataTransfer.files);
  });

  const baseRenderAll34=window.renderAll;
  window.renderAll=function(){ baseRenderAll34(); refreshWelcomeOverlay(); };
  refreshWelcomeOverlay();
})();

