/* ---- zoom buttons (no pinch on a timeline) ---- */
(function(){
  const tb=document.querySelector(".timeline-toolbar"); if(!tb) return;
  const mk=(id,label,fn)=>{ const b=document.createElement("button"); b.className="toolbtn"; b.id=id; b.type="button"; b.textContent=label; b.onclick=fn; return b; };
  const setZ=z=>{ timelineZoom=Math.round(Math.min(AZ_MAX,Math.max(AZ_MIN,z))); const s=$("timelineZoom"); if(s) s.value=timelineZoom; renderTimeline(); };
  const box=document.createElement("span"); box.className="zoom-box";
  box.append(mk("zoomOutBtn","－",()=>setZ(timelineZoom/1.4)), mk("zoomInBtn","＋",()=>setZ(timelineZoom*1.4)), mk("zoomFitBtn","Fit",()=>$("fitTimelineBtn").click()));
  tb.prepend(box);
})();


/* =================== Amiyo Editor features =================== */
function edit(label,fn){ const before=deepClone(serializableProject()); fn(); recordHistory(label,before,serializableProject()); renderAll(); }
function selClip(){ const f=getClip(); if(!f){ toast("Select a clip on the timeline first"); return null; } return f; }

/* ---- quick tools on the timeline bar ---- */
(function(){
  const tb=document.querySelector(".timeline-toolbar"); if(!tb) return;
  const box=document.createElement("span"); box.className="zoom-box quick-box";
  const mk=(id,label,title,fn)=>{ const b=document.createElement("button"); b.className="toolbtn"; b.id=id; b.type="button"; b.textContent=label; b.title=title; b.onclick=fn; return b; };
  const inside=c=>currentTime>c.start+.05&&currentTime<c.start+c.duration-.05;
  box.append(
    mk("qTrimStart","◂✂ Trim start","Remove everything before the playhead, from the selected clip",()=>{ const f=selClip(); if(!f) return; const c=f.clip; if(!inside(c)){ toast("Move the playhead inside the clip"); return; }
      edit("Trim start",()=>{ const d=currentTime-c.start, src=c.outPoint-c.inPoint; c.inPoint+=src*(d/c.duration); c.start=currentTime; c.duration-=d; }); }),
    mk("qTrimEnd","✂▸ Trim end","Remove everything after the playhead, from the selected clip",()=>{ const f=selClip(); if(!f) return; const c=f.clip; if(!inside(c)){ toast("Move the playhead inside the clip"); return; }
      edit("Trim end",()=>{ const e=currentTime-c.start, src=c.outPoint-c.inPoint; c.outPoint=c.inPoint+src*(e/c.duration); c.duration=e; }); }),
    mk("qGaps","Close gaps","Slide the clips on the selected track together (other tracks stay put)",()=>{ const f=selClip(); if(!f) return; const tr=f.track;
      if(tr.locked){ toast("That track is locked"); return; }
      edit("Close gaps",()=>{ const cs=tr.clips.slice().sort((a,b)=>a.start-b.start); let t=cs.length?cs[0].start:0; cs.forEach(c=>{ c.start=t; t+=c.duration; }); }); toast("Gaps closed on “"+tr.name+"”"); }),
    mk("qSpeed","Speed ⟳","Cycle the selected clip through 0.5× 1× 1.5× 2×",()=>{ const f=selClip(); if(!f) return; const c=f.clip, a=getAsset(c.assetId); if(!a||a.type==="image"){ toast("Speed applies to video and audio clips"); return; }
      const steps=[.5,1,1.5,2], cur=c.speed||1, nx=steps[(steps.findIndex(v=>Math.abs(v-cur)<.01)+1)%steps.length]||1;
      edit("Change speed",()=>{ const nd=(c.outPoint-c.inPoint)/nx, delta=nd-c.duration; f.track.clips.forEach(o=>{ if(o!==c&&o.start>=c.start+c.duration-.001) o.start+=delta; }); c.speed=nx; c.duration=nd; }); toast("Speed "+nx+"×"); }),
    mk("qFadeIn","Fade in ◐","Cycle the fade-in of the selected clip: off, 0.5 s, 1 s, 2 s",()=>{ const f=selClip(); if(!f) return; const c=f.clip, S=[0,.5,1,2], nx=S[(S.findIndex(v=>Math.abs(v-(c.fadeIn||0))<.01)+1)%S.length]||0; edit("Fade in",()=>{ c.fadeIn=nx; }); toast(nx?"Fade in "+nx+" s":"Fade in off"); }),
    mk("qFadeOut","Fade out ◑","Cycle the fade-out of the selected clip: off, 0.5 s, 1 s, 2 s",()=>{ const f=selClip(); if(!f) return; const c=f.clip, S=[0,.5,1,2], nx=S[(S.findIndex(v=>Math.abs(v-(c.fadeOut||0))<.01)+1)%S.length]||0; edit("Fade out",()=>{ c.fadeOut=nx; }); toast(nx?"Fade out "+nx+" s":"Fade out off"); }),
    mk("qDuck","Duck music ⇊","Turn the music on the selected audio track down while other audio is speaking",()=>{ const f=selClip(); if(!f) return; if(f.track.kind!=="audio"){ toast("Select a clip on the music track"); return; } edit("Duck music",()=>{ f.track.duck=!f.track.duck; }); toast(f.track.duck?"“"+f.track.name+"” now dips under voices":"Ducking off"); }),
    mk("qMute","Mute ⇄","Mute or unmute the selected clip",()=>{ const f=selClip(); if(!f) return; const c=f.clip; edit("Mute clip",()=>{ c.volume=(c.volume==null?1:c.volume)>0?0:1; }); toast(c.volume>0?"Sound on":"Muted"); })
  );
  const z=tb.querySelector(".zoom-box"); if(z) z.after(box); else tb.prepend(box);
})();


/* ---- fades and "duck the music under the voice" ---- */
window.amiyoFade=function(c,local){ const d=c.duration||0; let f=1; if(c.fadeIn>0) f*=(window.amiyoFS||function(c,x){return x;})(c,clamp(local/c.fadeIn,0,1)); if(c.fadeOut>0) f*=(window.amiyoFS||function(c,x){return x;})(c,clamp((d-local)/c.fadeOut,0,1)); return f; };
const duckLvl=new Map(), _uap3=window.updateAudioPlayback;
window.updateAudioPlayback=async function(){
  await _uap3.apply(this,arguments);
  const voiceOn=ex=>{ for(const t of project.tracks){ if(t.kind!=="audio"||t.muted||t.hidden||t.duck||t===ex) continue; for(const c of t.clips){ if(!c.off&&(c.volume==null?1:c.volume)>0&&currentTime>=c.start&&currentTime<c.start+c.duration) return true; } } return false; };
  for(const t of project.tracks){
    if(t.kind!=="audio"&&t.kind!=="video") continue;
    let lvl=1;
    if(t.kind==="audio"&&t.duck){ const target=(isPlaying&&voiceOn(t))?(window.amiyoDuckLevel?window.amiyoDuckLevel():.3):1, cur=duckLvl.has(t.id)?duckLvl.get(t.id):1; lvl=cur+(target-cur)*(window.amiyoDuckSpeed?window.amiyoDuckSpeed():.2); duckLvl.set(t.id,lvl); }
    for(const c of t.clips){
      const el=t.kind==="audio"?audioEls.get(c.id):vAudio.get(c.id); if(!el||el.paused) continue;
      const local=currentTime-c.start; if(local<0||local>c.duration) continue;
      el.volume=Math.min(1,Math.max(0,el.volume*window.amiyoFade(c,local)*lvl*(window.amiyoMaster?window.amiyoMaster():1)));
    }
  }
};


/* Q / W trim to the playhead */
document.addEventListener("keydown",e=>{
  if(e.ctrlKey||e.metaKey||e.altKey) return; const t=e.target;
  if(t&&(/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)||t.isContentEditable)) return;
  const k=(e.key||"").toLowerCase(); if(k==="q"){ e.preventDefault(); $("qTrimStart").click(); } else if(k==="w"){ e.preventDefault(); $("qTrimEnd").click(); }
});

/* ---- picture shape: 16:9 · 9:16 · 1:1 · 4:5 ---- */
const SHAPES={"16:9":[1280,720],"9:16":[720,1280],"1:1":[1080,1080],"4:5":[864,1080]};
(function(){
  const nm=$("projectName"); if(!nm) return;
  const sel=document.createElement("select"); sel.id="aspectSel"; sel.title="Picture shape"; sel.className="aspect-sel";
  Object.keys(SHAPES).forEach(k=>{ const o=document.createElement("option"); o.value=k; o.textContent=k; sel.appendChild(o); });
  const cu=document.createElement("option"); cu.value="custom"; cu.textContent="Custom"; cu.hidden=true; sel.appendChild(cu);
  sel.onchange=()=>{ const v=SHAPES[sel.value]; if(!v) return; edit("Picture shape "+sel.value,()=>{ project.settings.width=v[0]; project.settings.height=v[1]; project.settings.aspect=sel.value; }); toast("Picture shape "+sel.value); };
  nm.after(sel);
})();
function syncShape(){
  const sel=$("aspectSel"); if(!sel) return; const r=project.settings.width/project.settings.height; let v="custom";
  for(const [k,[w,h]] of Object.entries(SHAPES)) if(Math.abs(r-w/h)<.02) v=k;
  if(sel.value!==v) sel.value=v;
}
const _ra2=window.renderAll; window.renderAll=function(){ _ra2.apply(this,arguments); syncShape(); };

/* ---- export: choose the size, watch the progress, cancel ---- */
const bar=document.createElement("div"); bar.id="expBar"; bar.className="exp-bar"; bar.hidden=true;
bar.innerHTML='<div class="exp-fill" id="expFill"></div><span id="expTxt">Exporting…</span><button type="button" id="expPause">Pause</button><button type="button" id="expCancel">Cancel</button>';
document.body.appendChild(bar);
$("expCancel").onclick=()=>{ window.__amiyoCancel=true; window.__amiyoExportPaused=false; $("expTxt").textContent="Stopping…"; };
$("expPause").onclick=()=>{ window.__amiyoExportPaused=!window.__amiyoExportPaused; $("expPause").textContent=window.__amiyoExportPaused?"Resume":"Pause"; };
window.amiyoExportProgress=function(p,left){
  bar.hidden=false;
  const R=window.__amiyoExportRange, S=window.__amiyoExportSpan, tot=Math.max(.1,window.amiyoContentEnd());
  const a=S?S.a:0, b=S?S.b:tot, pp=Math.max(0,Math.min(1,p));
  const cur=R?R.t0+pp*(R.t1-R.t0):pp*tot;
  const pc=Math.max(0,Math.min(100,Math.round((cur-a)/Math.max(1,b-a)*100)));
  $("expFill").style.width=pc+"%";
  const info=window.__amiyoExportPart, paused=!!window.__amiyoExportPaused;
  let t=paused?"Paused · ":"Exporting ";
  if(info&&info.n>1) t+="part "+info.i+" of "+info.n+" ("+Math.round(pp*100)+"%) · ";
  t+=pc+"% total · about "+amiyoHumanDur(Math.max(1,b-cur))+" left";
  const fps=window.__amiyoExportFps, want=window.__amiyoXFps||(project.settings&&project.settings.fps)||30;
  if(fps&&!paused&&fps<want*0.6) t+=" · this device is struggling and dropping frames: try Draft size";
  $("expTxt").textContent=t;
  bar.classList.toggle("warn",!paused&&!!fps&&fps<want*0.6);
};
window.amiyoExportDone=function(){ window.__amiyoExportOpts=null; window.__amiyoExportPaused=false; $("expPause").textContent="Pause"; bar.hidden=true; $("expFill").style.width="0%"; try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)} };
function amiyoHumanDur(s){ s=Math.max(1,Math.round(s)); const h=Math.floor(s/3600), m=Math.floor(s%3600/60), x=s%60; return h?(h+" h "+m+" min"):(m?(m+" min "+(x?x+" s":"")).trim():(x+" s")); }
function askExport(){
  return new Promise(res=>{
    if(!window.amiyoContentEnd()){ toast("Nothing to export yet — add a clip to the timeline"); res(null); return; }
    let end=Math.max(.1,window.amiyoContentEnd()); const H0=project.settings.height, W0=project.settings.width; window.__amiyoXEnd=function(v){ end=Math.max(1,v); };
    const opts=[[360,"Tiny"],[480,"Draft"],[720,"Standard"],[1080,"Full HD"]];
    const shortSide=Math.min(W0,H0);
    openModal("Export video",
      '<p style="margin:0 0 10px">Runs in real time — this edit takes about <b>'+amiyoHumanDur(end)+'</b>. Keep this screen on and the app open until it finishes.</p>'+
      '<label class="field" for="expName">File name</label><input id="expName" type="text" value="'+String(project.metadata.name||"amiyo-edit").replace(/"/g,"&quot;")+'">'+
      '<label class="field" style="margin-top:10px">Size (short side)</label><div class="mini-row" id="expSizes" role="group" aria-label="Size (short side)">'+
        '<button class="chip" data-h="0">Project size · '+W0+'×'+H0+'</button>'+
        opts.map(([h,t])=>'<button class="chip" data-h="'+h+'">'+t+' · '+h+'p</button>').join("")+'</div>'+
      '<label class="field" style="margin-top:10px">Split into parts (best for long videos)</label><div class="mini-row" id="expParts" role="group" aria-label="Split into parts">'+[[0,"One file"],[600,"10 min"],[1200,"20 min"],[1800,"30 min"]].map(([s,t])=>'<button class="chip" data-s="'+s+'">'+t+'</button>').join("")+'</div>'+
      '<div id="expPartInfo" style="font-size:11px;color:var(--muted);margin-top:6px;line-height:1.45"></div>'+
      '<div id="expFromRow" style="margin-top:8px;font-size:12px" hidden>Start at part <input id="expFrom" type="number" min="1" value="1" style="width:64px"></div>'+
      '<div class="mini-row" style="margin-top:14px"><button class="chip" id="expGo" style="background:var(--accent);color:#1a0c03;font-weight:700">Start export</button></div>');
    let h=0, started=false, ps=end>900?600:0;
    const pchips=[...document.querySelectorAll("#expParts .chip")];
    const pmark=()=>{ pchips.forEach(c=>{ const on=Number(c.dataset.s)===ps; c.style.outline=on?"2px solid var(--accent)":"none"; c.setAttribute("aria-pressed",on?"true":"false"); });
      const n=ps?Math.max(1,Math.ceil((end-0.5)/ps)):1; $("expFromRow").hidden=!ps||n<2; $("expFrom").max=n; $("expFrom").min=1; { const fv=parseInt($("expFrom").value,10); if(!(fv>=1)) $("expFrom").value=1; else if(fv>n){ $("expFrom").value=n; } }
      $("expPartInfo").textContent=ps?(n+" files, each up to "+(ps/60)+" min. If one fails or you leave the app, restart from that part and nothing else is lost."):(end>900?"One big file: if it fails near the end you lose everything. Parts are safer.":""); };
    pchips.forEach(c=>c.onclick=()=>{ ps=Number(c.dataset.s); pmark(); }); pmark();
    $("expFrom").addEventListener("change",()=>{ const n=ps?Math.max(1,Math.ceil((end-0.5)/ps)):1, v=parseInt($("expFrom").value,10); const k=!(v>=1)?1:Math.min(n,v); if(k!==v){ $("expFrom").value=k; toast(v>n?("There are only "+n+" parts, so it starts at part "+n):"Parts start at 1",3200); } });
    const chips=[...document.querySelectorAll("#expSizes .chip")];
    const mark=()=>chips.forEach(c=>{ const on=Number(c.dataset.h)===h; c.style.outline=on?"2px solid var(--accent)":"none"; c.setAttribute("aria-pressed",on?"true":"false"); });
    chips.forEach(c=>c.onclick=()=>{ h=Number(c.dataset.h); mark(); }); mark();
    $("expGo").onclick=()=>{ started=true; const nm=$("expName").value.trim()||project.metadata.name||"amiyo-edit"; closeModal();
      const ratio=(project.settings.height||H0)/(project.settings.width||W0), tall=ratio>1; /* "short side" → pixel height of the picture (step 10: read at start time, a preset may have changed the canvas) */
      res({h:h?(tall?Math.round(h*ratio):h):0,bps:window.__amiyoPresetBps||0,name:nm,partSecs:ps,from:Math.max(1,parseInt($("expFrom").value,10)||1)}); };
    const iv=setInterval(()=>{ if($("modalBackdrop").style.display==="none"){ clearInterval(iv); if(!started) res(null); } },250);
  });
}
const _exp=window.exportProject;
$("expCancel").addEventListener("click",()=>{ window.__amiyoUserStop=true; });
window.exportProject=async function(){
  if(window.__amiyoExporting){ toast("An export is already running"); return; }
  const o=await askExport(); if(!o) return;
  window.__amiyoExportOpts=o; window.__amiyoCancel=false; window.__amiyoUserStop=false;
  const R=window.__amiyoXRange||null, base0=R?R.t0:0, end=R?R.t1:Math.max(.1,window.amiyoContentEnd()), ps=o.partSecs||0, n=ps?Math.max(1,Math.ceil((end-base0-0.5)/ps)):1;
  const first=ps?Math.min(n,o.from||1)-1:0; window.__amiyoExportSpan=(ps||R)?{a:base0+first*ps,b:end}:null;
  let lock=null; try{ if(navigator.wakeLock) lock=await navigator.wakeLock.request("screen"); }catch(e){window.__swl&&window.__swl(e)}   /* keep the screen on */
  try{
    for(let i=ps?Math.min(n,o.from||1)-1:0;i<n;i++){
      window.__amiyoExportOpts=o; window.__amiyoExportRange=ps?{t0:base0+i*ps,t1:(i>=n-1?end:Math.min(end,base0+(i+1)*ps))}:(R?{t0:R.t0,t1:R.t1}:null);
      window.__amiyoExportName=o.name+(ps&&n>1?"-part"+(i+1)+"of"+n:"");
      window.__amiyoExportHidden=false; window.__amiyoCancel=false; window.__amiyoExportPart={i:i+1,n:n};
      if(ps&&n>1) toast("Exporting part "+(i+1)+" of "+n,3000);
      try{ await _exp.apply(this,arguments); }catch(e){ break; }
      if(!window.__amiyoExporting) break;            /* did not start (pre-export check, or an error) */
      await new Promise(function(r){ const iv=setInterval(function(){ if(!window.__amiyoExporting){ clearInterval(iv); r(); } },300); });
      if(window.__amiyoUserStop) break;
      if(i<n-1) await new Promise(function(r){ setTimeout(r,2500); });   /* let this part's download start */
    }
    if(ps&&n>1&&!window.__amiyoUserStop) toast("All "+n+" parts exported",5000);
  } finally {
    window.__amiyoExportRange=null; window.__amiyoExportSpan=null; window.__amiyoExportPart=null; try{ if(lock) lock.release(); }catch(e){window.__swl&&window.__swl(e)}
    if(!window.__amiyoExporting) window.amiyoExportDone();
  }
};

/* =================== Import hub: videos · images · audio · effects · others =================== */
const KINDS={video:"mp4 m4v mov webm mkv avi ogv 3gp 3g2 ts mts m2ts mpg mpeg wmv flv",audio:"mp3 mp2 wav wave ogg oga m4a m4b aac flac opus wma aif aiff aifc amr caf weba mka ac3",image:"png jpg jpeg gif webp avif bmp svg ico tif tiff heic heif"};
const extOf=f=>((f.name||"").split(".").pop()||"").toLowerCase();
const inList=(f,l)=>l.split(" ").includes(extOf(f));
function classify(f){
  const t=f.type||"", e=extOf(f);
  if(t.startsWith("video/")||inList(f,KINDS.video)) return "video";
  if(t.startsWith("audio/")||inList(f,KINDS.audio)) return "audio";
  if(t.startsWith("image/")||inList(f,KINDS.image)) return "image";
  if(e==="srt"||e==="vtt") return "captions";
  if(e==="cube") return "lut";
  if(["ttf","otf","woff","woff2"].includes(e)) return "font";
  if(e==="amiyovideo") return "project";
  if(e==="json") return "json";
  if(e==="txt"||e==="md"||t==="text/plain") return "script";
  return "unknown";
}
const isMedia=k=>k==="video"||k==="audio"||k==="image";
const stem=f=>String(f.name||"file").replace(/\.[^.]+$/,"");

/* -- helpers: which clips does a look / LUT go to -- */
function lookTargets(){
  const f=getClip(); if(f) return [f.clip];
  const all=[]; for(const t of project.tracks) if(t.kind==="video") for(const c of t.clips) if(c.assetId) all.push(c);
  return all;
}
function tooMany(n){ if(n>24){ toast("That is "+n+" clips — select one clip first, or a smaller group",4200); return true; } return false; }

/* -- effects: overlay footage on its own track, blended over the picture -- */
function overlayTrack(){
  let t=project.tracks.find(x=>x.kind==="video"&&x.name==="Overlay");
  if(!t){ t={id:uid("track"),name:"Overlay",kind:"video",locked:false,hidden:false,muted:false,clips:[]}; const last=project.tracks.map(x=>x.kind).lastIndexOf("video"); project.tracks.splice(last+1,0,t); }
  return t;
}
function placeOverlay(id){
  const a=getAsset(id); if(!a||a.type==="audio") return;
  const end=Math.max(5,window.amiyoContentEnd()||0), start=currentTime||0;
  const dur=a.type==="image"?Math.max(3,end-start):Math.max(.5,a.duration||5);
  const mk=(s,d)=>({id:uid("clip"),assetId:id,start:s,duration:d,inPoint:0,outPoint:d,volume:0,opacity:.85,speed:1,rotation:0,scale:1,x:.5,y:.5,trimL:0,trimR:0,fit:"cover",blendMode:"screen",effects:[],keyframes:[],transitionIn:null,transitionOut:null});
  edit("Import overlay",()=>{ const t=overlayTrack(); let s=start, n=0; const stop=Math.max(end,start+dur);
    do{ const d=Math.min(dur,stop-s); t.clips.push(mk(s,d)); s+=d; n++; }while(a.type!=="image"&&s<stop-.05&&n<40); });
}

/* -- effects: .cube colour LUT -- */
function parseCube(text){
  let size=0; const table=[];
  for(const raw of text.split(/\r?\n/)){
    const line=raw.trim(); if(!line||line[0]==="#") continue;
    if(line.startsWith("LUT_3D_SIZE")){ size=parseInt(line.split(/\s+/)[1],10); continue; }
    if(/^(TITLE|DOMAIN_|LUT_1D_SIZE)/.test(line)) continue;
    const p=line.split(/\s+/).map(Number); if(p.length===3&&p.every(Number.isFinite)) table.push(p);
  }
  return (!size||table.length<size*size*size)?null:{size,table};
}
async function applyLut(file){
  const parsed=parseCube(await file.text());
  if(!parsed){ toast("Couldn't read that .cube file"); return; }
  const ts=lookTargets().filter(c=>{ const a=getAsset(c.assetId); return a&&a.type!=="audio"; });
  if(!ts.length){ toast("Add a video or picture to the timeline first"); return; }
  if(tooMany(ts.length)) return;
  edit("Apply LUT",()=>{ ts.forEach(c=>{ c.lut={enabled:true,size:parsed.size,table:parsed.table,intensity:1,name:file.name}; }); });
  toast("LUT “"+file.name+"” applied to "+(ts.length===1?"the clip":ts.length+" clips"));
}
/* -- effects: look presets (.json) -- */
const LOOK_KEYS=["filter","look","effects","blendMode","opacity","lut"];
function applyPreset(o){
  const ts=lookTargets(); if(!ts.length){ toast("Add a clip to the timeline first"); return; } if(tooMany(ts.length)) return;
  edit("Apply look",()=>{ ts.forEach(c=>{ LOOK_KEYS.forEach(k=>{ if(o[k]!==undefined) c[k]=JSON.parse(JSON.stringify(o[k])); }); }); });
  toast("Look “"+(o.name||"preset")+"” applied to "+(ts.length===1?"the clip":ts.length+" clips"));
}
function saveLook(){
  const f=getClip(); if(!f){ toast("Select a clip first"); return; }
  const o={amiyoPreset:1,name:(project.metadata&&project.metadata.name||"look")+" look"}; LOOK_KEYS.forEach(k=>{ if(f.clip[k]!==undefined) o[k]=f.clip[k]; });
  const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([JSON.stringify(o)],{type:"application/json"})); a.download="look.amiyo-look.json"; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),4000);
  toast("Look saved");
}

/* -- others: fonts (kept on this device, listed in the text inspector) -- */
const FONT_KEY="amiyo_fonts";
const fontList=()=>{ try{ return JSON.parse(localStorage.getItem(FONT_KEY)||"[]"); }catch(e){ return []; } };
async function registerFont(file,keep){
  const family=stem(file).replace(/[^\w \-]/g,"").trim()||"Font";
  const buf=await file.arrayBuffer(); const ff=new FontFace(family,buf); await ff.load(); document.fonts.add(ff);
  if(keep){ try{ await window.amiyoPutBlob("font:"+family,new Blob([buf],{type:"font/"+extOf(file)})); const l=fontList().filter(x=>x.family!==family); l.push({family,key:"font:"+family}); localStorage.setItem(FONT_KEY,JSON.stringify(l)); }catch(e){window.__swl&&window.__swl(e)} }
  return family;
}
async function loadSavedFonts(){ for(const x of fontList()){ try{ const b=await window.amiyoGetBlob(x.key); if(b){ const ff=new FontFace(x.family,await b.arrayBuffer()); await ff.load(); document.fonts.add(ff); } }catch(e){window.__swl&&window.__swl(e)} } }
window.addEventListener("amiyo-booted",()=>{ loadSavedFonts().then(()=>{ try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }); },{once:true});
if(window.__amiyoBooted) loadSavedFonts();
const BASE_FONTS=[["system-ui","System"],["Arial, Helvetica, sans-serif","Arial"],["Georgia, serif","Georgia"],["'Courier New', monospace","Courier"],["Impact, sans-serif","Impact"],["'Trebuchet MS', sans-serif","Trebuchet"],["Verdana, Geneva, sans-serif","Verdana"],["Tahoma, Geneva, sans-serif","Tahoma"],["'Arial Narrow','Roboto Condensed','Franklin Gothic Medium',sans-serif","Narrow condensed"],["'Gill Sans','Gill Sans MT',Calibri,sans-serif","Gill Sans"],["'Palatino Linotype','Book Antiqua',Palatino,serif","Palatino"],["'Times New Roman',Times,serif","Times"],["Garamond,'EB Garamond','Times New Roman',serif","Garamond"],["Baskerville,'Baskerville Old Face','Hoefler Text',Georgia,serif","Baskerville"],["Didot,'Bodoni MT','Bodoni 72',Georgia,serif","Didot / Bodoni"],["Rockwell,'Roboto Slab','Courier New',serif","Rockwell slab"],["'Lucida Console',Monaco,'Courier New',monospace","Lucida mono"],["'Brush Script MT','Segoe Script','Snell Roundhand',cursive","Brush script"],["'Comic Sans MS','Chalkboard SE','Comic Neue',sans-serif","Comic"],["Papyrus,Copperplate,fantasy","Fantasy"],["'Arial Rounded MT Bold',Nunito,'Varela Round',sans-serif","Rounded"],["Optima,Candara,'Segoe UI',sans-serif","Optima"]];
const _ri=window.renderInspector;
window.renderInspector=function(){
  _ri.apply(this,arguments);
  try{
    const f=getClip(); if(!f||!f.clip.textStyle&&f.clip.kind!=="text") return;
    const inp=$("iFont"); if(!inp||$("iFontFam")) return; const c=f.clip, cur=(c.textStyle&&c.textStyle.fontFamily)||"system-ui";
    const opts=BASE_FONTS.concat(fontList().map(x=>["'"+x.family+"'",x.family]));
    const lab=document.createElement("label"); lab.className="field"; lab.textContent="Font"; lab.htmlFor="iFontFam";
    const sel=document.createElement("select"); sel.id="iFontFam";
    opts.forEach(([v,l])=>{ const o=document.createElement("option"); o.value=v; o.textContent=l; if(v===cur) o.selected=true; sel.appendChild(o); });
    if(!opts.some(([v])=>v===cur)){ const o=document.createElement("option"); o.value=cur; o.textContent=cur.replace(/['"]/g,""); o.selected=true; sel.appendChild(o); }
    sel.onchange=()=>{ edit("Change font",()=>{ c.textStyle=Object.assign({},c.textStyle,{fontFamily:sel.value}); }); };
    const before=inp.previousElementSibling&&inp.previousElementSibling.tagName==="LABEL"?inp.previousElementSibling:inp;
    before.before(lab,sel);
  }catch(e){window.__swl&&window.__swl(e)}
};

/* -- everything that is not video / image / audio -- */
async function importOther(kind,file,mode){
  try{
    if(kind==="captions"){ window.importCaptionFile(file); }
    else if(kind==="lut"){ await applyLut(file); }
    else if(kind==="font"){ const fam=await registerFont(file,true); const f=getClip(); if(f&&(f.clip.kind==="text"||f.clip.kind==="caption"||f.clip.textStyle)){ edit("Change font",()=>{ f.clip.textStyle=Object.assign({},f.clip.textStyle,{fontFamily:"'"+fam+"'"}); }); toast("Font “"+fam+"” applied"); } else toast("Font “"+fam+"” ready — pick it under Font on a text clip",4000); }
    else if(kind==="project"){ if(projectClips()>0&&!await amiyoOk("Open “"+file.name+"”? It replaces the project you have open.",{okLabel:"Open"})) return; loadProjectFile(file); }
    else if(kind==="json"){
      let o=null; try{ o=JSON.parse(await file.text()); }catch(e){window.__swl&&window.__swl(e)}
      if(o&&Array.isArray(o.tracks)){ if(projectClips()>0&&!await amiyoOk("Open “"+file.name+"”? It replaces the project you have open.",{okLabel:"Open"})) return; loadProjectFile(file); }
      else if(o&&(o.amiyoPreset||LOOK_KEYS.some(k=>o[k]!==undefined))) applyPreset(o);
      else toast("“"+file.name+"” isn't a project or a look preset");
    }
    else if(kind==="script"){
      const paras=(await file.text()).split(/\n\s*\n|\r\n\s*\r\n/).map(s=>s.replace(/\s+/g," ").trim()).filter(Boolean).slice(0,60);
      if(!paras.length){ toast("That text file is empty"); return; }
      const keep=currentTime; let t=keep; paras.forEach(p=>{ currentTime=t; addTextClip(p.slice(0,240)); t+=5; }); currentTime=keep; renderAll();
      toast(paras.length+" title"+(paras.length===1?"":"s")+" added from “"+file.name+"”");
    }
    else toast("Can't import “"+file.name+"” — try a video, picture, sound, subtitles, LUT, font or project file",4500);
  }catch(e){ toast("Couldn't import “"+file.name+"”: "+(e&&e.message||e),4500); }
}
const _imp=window.importFiles;
window.importFiles=async function(files){
  const mode=window.__amiyoImportMode||{}; window.__amiyoImportMode=null;
  const list=[...files], media=list.filter(f=>isMedia(classify(f)));
  const before=new Set(Object.keys(project.assets)); let added=[];
  if(media.length){ await _imp.call(this,media); added=Object.keys(project.assets).filter(id=>!before.has(id)); }
  if(mode.overlay) added.forEach(placeOverlay); else if(mode.toTimeline) added.forEach(id=>addAssetToTimeline(id));
  for(const f of list) if(!isMedia(classify(f))) await importOther(classify(f),f,mode);
  return added;
};

