(function(){ const dz=document.querySelector(".welcome-dropzone"); if(!dz) return; const b=document.createElement("div"); b.className="welcome-cta alt"; b.id="welcomeHubBtn"; b.textContent="More import options"; b.onclick=e=>{ e.stopPropagation(); openHub(); }; dz.appendChild(b); })();


/* ---- bridge to the AMIYO Director (only when embedded) ---- */
function post(msg){ if(!EMBED) return; try{ window.parent.postMessage(Object.assign({amiyo:1},msg),"*"); }catch(e){window.__swl&&window.__swl(e)} }
window.amiyoOnExport=function(blob,name){ post({type:"exported",name:name,blob:blob}); };
function projectClips(){ let n=0; for(const t of project.tracks) n+=t.clips.length; return n; }
window.addEventListener("message",async ev=>{
  if(!EMBED||ev.source!==window.parent) return;
  const d=ev.data; if(!d||d.amiyo!==1) return;
  try{
    if(d.type==="pause"){ if(!window.__amiyoExporting&&typeof pause==="function") pause(); }
    else if(d.type==="query"){ post({type:"state",id:d.id,clips:projectClips(),name:(project.metadata&&project.metadata.name)||""}); }
    else if(d.type==="import"){
      const files=(d.files||[]).filter(f=>f&&f.blob).map(f=>new File([f.blob],f.name||"media",{type:f.blob.type||f.type||""}));
      const before=new Set(Object.keys(project.assets));
      window.__amiyoImportMode={};
      await importFiles(files);
      if(d.toTimeline!==false) for(const id of Object.keys(project.assets)) if(!before.has(id)) addAssetToTimeline(id);
      post({type:"done",id:d.id});
    }
    else if(d.type==="project"){
      const p=V.normalizeProject(d.project);
      await window.amiyoAdoptAssets(p);
      restoreSerializable(p); currentTime=0; scheduleAutosave(); renderAll();
      const f=$("fitTimelineBtn"); if(f) f.click();
      toast("Loaded “"+((p.metadata&&p.metadata.name)||"project")+"”",3200);
      post({type:"done",id:d.id});
    }
  }catch(err){ toast("Could not load that: "+(err&&err.message||err),5000); post({type:"error",id:d.id,message:String(err&&err.message||err)}); }
});

