  for(const a of Object.values(project.assets)){ if((a.type!=="video"&&a.type!=="image")||a.libId||(pipMainSel()&&pipMainSel().a.id===a.id)) continue; rows.push({k:"a:"+a.id,name:a.name||(a.type==="image"?"Image":"Video"),img:a.type==="image",dur:+a.duration||0,th:null,sub:"this project"}); }
