let pipBusy=false;
async function pipApply(){
  if(pipBusy) return; pipBusy=true; try{ await pipApplyRun(); } finally{ pipBusy=false; }
}
async function pipApplyRun(){
  const m=pipMainSel(); if(!m){ toast("Choose a main video"); return; }
  if(!PIP.items.length){ toast("Add at least one video"); return; }
  const before=deepClone(serializableProject());
  let last=project.tracks.map(t=>t.kind).lastIndexOf("video"), made=0, miss=0, first=null; const batchTracks=[];
  for(const o of PIP.items){
    let aid=o.asset;
    if(o.lib){ const it=byId(o.lib); if(!it){ miss++; continue; } aid=await ensureInProject(it); if(!aid){ miss++; continue; } touch(it); }
    const a=project.assets[aid]; if(!a){ miss++; continue; }
    const def=pipDef(o.shape), ar=(a.width&&a.height)?a.width/a.height:(o.ar||16/9), sq=!!def[3];
    const mw=sq?(ar>=1?1/ar:1):1, mh=sq?(ar>=1?1:ar):1;
    const off=pnum(o.start,0,Math.max(0,m.c.duration-.5)), dur=Math.max(Math.min(.5,m.c.duration),Math.min(o.dur,o.dur0,m.c.duration-off));
    /* reuse a PiP track made in this batch when the new overlay does not overlap anything on it (and has the same sound setting), so many overlays do not make many tracks */
    const cs=m.c.start+off, ce=cs+dur;
    let tr=made?batchTracks.find(x=>!!x.muted===!o.sound&&x.clips.every(k=>ce<=k.start+1e-6||cs>=k.start+k.duration-1e-6)):null;
    if(!tr){ tr={id:uid("track"),name:"PiP "+(batchTracks.length+1),kind:"video",locked:false,hidden:false,muted:!o.sound,clips:[]};
      project.tracks.splice(last+1,0,tr); last++; batchTracks.push(tr); }
    made++;
    const c={id:uid("clip"),assetId:aid,start:m.c.start+off,duration:dur,inPoint:o.inP||0,outPoint:(o.inP||0)+dur,volume:o.sound?1:0,opacity:o.opacity==null?1:o.opacity,speed:1,rotation:+o.rot||0,scale:Math.min(4,o.size/mw),x:o.x,y:o.y,trimL:0,trimR:0,fit:"contain",effects:[],keyframes:[],transitionIn:null,transitionOut:null,
      mask:{enabled:true,shape:def[2],x:.5,y:.5,w:mw,h:mh,feather:0,invert:false},pip:{shape:o.shape,size:o.size,border:o.border,color:o.color,shadow:!!o.shadow,opacity:o.opacity==null?1:o.opacity,rot:+o.rot||0,main:m.c.id}};
    tr.clips.push(c); if(!first){ first={c,tr}; }
  }
  if(!made){ toast("Those videos are no longer stored on this device",4200); return; }
  selectedClipId=first.c.id; selectedTrackId=first.tr.id;
  try{ currentTime=first.c.start; }catch(_){}
  recordHistory("Add picture-in-picture",before,serializableProject());
  scheduleAutosave(); closeModal(); renderAll(); try{ renderPreviewFrame(); }catch(_){}
  toast(made+(made===1?" overlay":" overlays")+" attached to the main video"+(miss?" · "+miss+" skipped":""),3600);
}
