  activePanel="media";
  document.querySelectorAll("#nav .navbtn").forEach(x=>x.classList.toggle("active",x.dataset.panel==="media"));
  renderLeftPanel();
  if(isPhone()){ const app=document.querySelector(".app"); app.classList.remove("sheet-insp"); app.classList.add("sheet-lib"); const b=q("mbLib"); if(b) b.classList.add("on"); }
