window.amiyoOpenLibrary=openLibrary;
window.amiyoMediaLib={register:registerAsset,byId:byId,items:function(){ return LIB.items; },use:useItems,persist:persist,render:function(){ renderBody(); try{ updateSegCounts(); }catch(e){} },state:LIB,getBlob:getBlob,detail:openDetail,saveBins:saveBins,remove:removeItems};
