/* ==================== Script 107 ==================== */
(()=>{
/* Navigation and save shortcuts */
document.addEventListener("keydown",e=>{
  const mod=e.ctrlKey||e.metaKey;
  if(mod&&!e.altKey&&e.key.toLowerCase()==="s"){e.preventDefault();Promise.resolve(window.saveProjectFile()).then(ok=>{if(ok)toast("Project file downloaded")});return;}
  const t=document.activeElement, inField=t&&["INPUT","TEXTAREA","SELECT"].includes(t.tagName);
  const modal=document.getElementById("modalBackdrop");
  if(e.key==="Escape"&&modal&&modal.style.display==="grid"){e.preventDefault();closeModal();return;}
  if(inField||mod||e.altKey||(modal&&modal.style.display==="grid"))return;
  const fps=project.settings.fps||30;
  if(e.key==="ArrowLeft"){e.preventDefault();setCurrentTime(currentTime-(e.shiftKey?1:1/fps));}
  else if(e.key==="ArrowRight"){e.preventDefault();setCurrentTime(currentTime+(e.shiftKey?1:1/fps));}
  else if(e.key==="Home"){e.preventDefault();setCurrentTime(0);}
  else if(e.key==="End"){e.preventDefault();setCurrentTime(window.amiyoContentEnd?window.amiyoContentEnd():getProjectDuration());}
});
})();

