/* ==================== Script 108 ==================== */
(()=>{
/* Timeline ergonomics: follow playhead, show multi-selection, select-all, Ctrl+wheel zoom */
const $$=id=>document.getElementById(id);
const _utu=window.updateTimeUI;
window.updateTimeUI=function(){
  _utu.apply(this,arguments);
  if(!isPlaying)return;
  var nowF=performance.now(); if(nowF-(window.__tlFollowAt||0)<100) return; window.__tlFollowAt=nowF;   /* step 60: follow-check 10x/s, not every frame */
  const sc=$$("timelineScroll"); if(!sc||!sc.clientWidth)return;
  const x=timeToPx(currentTime)+labelW(), l=sc.scrollLeft, r=l+sc.clientWidth;
  if(!(window.__tlPanUntil>Date.now())&&(x>r-40||x<l+labelW())) sc.scrollLeft=Math.max(0,x-sc.clientWidth*0.3);
};
const _rt=window.renderTracks;
window.renderTracks=function(){
  _rt.apply(this,arguments);
  document.querySelectorAll("#tracks .clip").forEach(el=>{
    const f=getClipByIds(el.dataset.clip,el.dataset.track);
    if(f&&f.clip.selected) el.classList.add("selected");
  });
};
function clearSel(){for(const t of project.tracks)for(const c of t.clips)c.selected=false;}
document.addEventListener("keydown",e=>{
  const t=document.activeElement, inField=t&&["INPUT","TEXTAREA","SELECT"].includes(t.tagName);
  if(inField||e.defaultPrevented)return;
  if((e.ctrlKey||e.metaKey)&&!e.altKey&&e.key.toLowerCase()==="a"){
    e.preventDefault(); let first=null;
    for(const tr of project.tracks){ if(tr.locked)continue; for(const c of tr.clips){ c.selected=true; if(!first)first={c,tr}; } }
    if(!first){toast("No clips to select");return;}
    selectedClipId=first.c.id; selectedTrackId=first.tr.id; renderTracks(); renderInspector();
    toast("All clips selected");
  } else if(e.key==="Escape"){
    clearSel(); selectedClipId=null; renderTracks(); renderInspector();
  }
});
const ts=$$("timelineScroll");
if(ts) ts.addEventListener("wheel",e=>{
  if(!(e.ctrlKey||e.metaKey))return;
  e.preventDefault();
  const f=Math.pow(1.0022,-Math.max(-120,Math.min(120,e.deltaY)));   /* smooth for trackpads, steady for wheels */
  window.amiyoZoomBy(f,e.clientX-ts.getBoundingClientRect().left,true);
},{passive:false});
})();

