/* ==================== Script 109 ==================== */
(()=>{
/* Saving a project embeds every media file as base64; guard against huge projects and surface failures instead of failing silently */
const _spf=window.saveProjectFile;
window.saveProjectFile=async function(){
  try{
    const total=Object.values(project.assets||{}).reduce((n,a)=>n+(a.size||0),0);
    if(total>400*1048576&&!await amiyoOk("This project holds about "+Math.round(total/1048576)+" MB of media. Saving it as one file may fail or freeze the browser. Continue?",{okLabel:"Save anyway"})) return false;
    toast("Preparing project file\u2026",8000);
    await _spf.apply(this,arguments);
    return true;
  }catch(e){
    toast("Could not save the project file ("+((e&&e.message)||"out of memory")+"). Try removing large media first.",7000);
    return false;
  }
};
})();

