/* ==================== Script 110 ==================== */
(()=>{
/* Loop toggle button (the loop setting existed but had no control) */
const bar=document.querySelector(".preview-toolbar"), grid=document.getElementById("gridBtn");
if(bar&&grid&&!document.getElementById("loopBtn")){
  const b=document.createElement("button"); b.className="toolbtn"; b.id="loopBtn"; b.title="Loop playback"; b.textContent="\u21bb Loop";
  grid.after(b);
  const sync=()=>b.classList.toggle("tool-active",!!(project.settings&&project.settings.loop));
  b.onclick=()=>{project.settings.loop=!project.settings.loop;scheduleAutosave();sync();toast(project.settings.loop?"Loop on":"Loop off");};
  window.addEventListener("amiyo-booted",sync); sync();
}
})();

