/* ==================== Script 111 ==================== */
/* Editor step 1: the welcome buttons were plain <div>s — make them real keyboard/screen-reader buttons */
(function(){
  function fix(){
    document.querySelectorAll(".welcome-cta").forEach(function(b){
      if(b.dataset.a11y) return; b.dataset.a11y = "1";
      b.setAttribute("role","button"); b.tabIndex = 0;
      b.addEventListener("keydown", function(e){ if(e.key === "Enter" || e.key === " "){ e.preventDefault(); b.click(); } });
    });
  }
  fix(); window.addEventListener("amiyo-booted", fix); setTimeout(fix, 1500);
})();

