/* ==================== Script 112 ==================== */
/* Editor step 3: accessibility layer (labels, live toasts, dialog focus, keyboard clips) */
(function(){
  var $=function(id){return document.getElementById(id)};
  var live=$("a11yLive"), alertEl=$("a11yAlert");
  function say(msg,assertive){var el=assertive?alertEl:live; if(!el)return; el.textContent=""; setTimeout(function(){el.textContent=String(msg||"")},40);}
  window.a11ySay=say;
  /* toasts are announced through a persistent live region (the visible toast toggles display:none, which screen readers miss) */
  var _toast=window.toast;
  if(typeof _toast==="function"){ window.toast=function(m,ms){ try{ var bad=/fail|error|couldn.t|cannot|can.t|unable/i.test(m); say(m,bad); }catch(e){window.__swl&&window.__swl(e)} return _toast.apply(this,arguments); }; }
  /* dialogs: focus in, trap Tab, Esc closes, focus returns to the opener */
  var lastFocus=null, FOC='a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
  function dlg(){var b=$("modalBackdrop");return b&&b.querySelector(".modal")}
  function isOpen(){var b=$("modalBackdrop");return !!b&&b.style.display!=="none"&&b.style.display!==""}
  function bg(on){["header.topbar","main.workspace"].forEach(function(q){var e=document.querySelector(q); if(!e)return; if(on){e.setAttribute("inert","");e.setAttribute("aria-hidden","true")}else{e.removeAttribute("inert");e.removeAttribute("aria-hidden")}})}
  var _open=window.openModal, _close=window.closeModal;
  if(typeof _open==="function") window.openModal=function(){
    if(!isOpen()) lastFocus=document.activeElement;
    var r=_open.apply(this,arguments); bg(true);
    setTimeout(function(){var d=dlg(); if(!d)return; var body=$("modalBody"); var t=body&&body.querySelector(FOC); (t||$("modalClose")||d).focus();},30);
    return r;
  };
  if(typeof _close==="function") window.closeModal=function(){
    var was=isOpen(); var r=_close.apply(this,arguments); bg(false);
    if(was&&lastFocus&&document.contains(lastFocus)){ try{lastFocus.focus()}catch(e){window.__swl&&window.__swl(e)} } lastFocus=null; return r;
  };
  /* the base handlers captured the original closeModal; route Close/backdrop/Esc through the wrapped one */
  var mc=$("modalClose"); if(mc) mc.onclick=function(){window.closeModal()};
  document.addEventListener("keydown",function(e){
    if(!isOpen()) return;
    if(e.key==="Escape"){ e.preventDefault(); e.stopPropagation(); window.closeModal(); return; }
    if(e.key==="Tab"){ var d=dlg(); if(!d)return; var f=[].slice.call(d.querySelectorAll(FOC)).filter(function(x){return x.offsetParent!==null});
      if(!f.length){e.preventDefault();d.focus();return;}
      var first=f[0], last=f[f.length-1], a=document.activeElement;
      if(e.shiftKey&&(a===first||!d.contains(a))){e.preventDefault();last.focus();} else if(!e.shiftKey&&(a===last||!d.contains(a))){e.preventDefault();first.focus();} }
  },true);
  var bd=$("modalBackdrop"); if(bd) bd.addEventListener("click",function(e){ if(e.target===bd && isOpen()) window.closeModal(); });
  /* labels and states, re-applied when the UI re-renders */
  function nm(el){return (el.getAttribute("aria-label")||el.getAttribute("title")||el.textContent||"").replace(/\s+/g," ").trim()}
  function pass(){
    document.querySelectorAll("button:not([aria-label])").forEach(function(b){
      var t=(b.textContent||"").replace(/[\s\u200b]+/g,""); var ti=b.getAttribute("title");
      if(ti && (t.length<=3 || /^[^A-Za-z0-9]+/.test(b.textContent.trim()))) b.setAttribute("aria-label",ti.replace(/\s*—.*$/,""));
      else if(!t && ti) b.setAttribute("aria-label",ti);
    });
    var __lf=new Set(); document.querySelectorAll("label[for]").forEach(function(l){ __lf.add(l.getAttribute("for")); });
    document.querySelectorAll("input:not([type=hidden]):not([aria-label]),select:not([aria-label]),textarea:not([aria-label])").forEach(function(i){
      if(i.id && __lf.has(i.id)) return;
      if(i.closest("label")) return;
      var prev=i.previousElementSibling; if(prev&&prev.tagName==="LABEL"&&prev.textContent.trim()){ i.setAttribute("aria-label",prev.textContent.replace(/\s+/g," ").trim()); return; }
      var l=i.getAttribute("title")||i.getAttribute("placeholder")||i.getAttribute("name")||i.id; if(l) i.setAttribute("aria-label",String(l).replace(/([a-z])([A-Z])/g,"$1 $2"));
    });
    document.querySelectorAll("#tracks .track-row").forEach(function(row,ri){
      var lab=row.querySelector(".track-label"); var nameEl=lab&&lab.querySelector("span:not(.type)"); var tn=nameEl?nameEl.textContent.trim():"Track "+(ri+1);
      if(lab){ lab.setAttribute("role","group"); lab.setAttribute("aria-label","Track "+tn); }
      [["mute","Mute"],["solo","Solo"],["lock","Lock"],["hide","Hide"]].forEach(function(p){
        var b=row.querySelector(".thtn."+p[0]); if(!b)return; var on=b.classList.contains("on");
        b.setAttribute("aria-label",p[1]+" "+tn); b.setAttribute("aria-pressed",on?"true":"false"); b.setAttribute("title",p[1]+" "+tn);
      });
      row.querySelectorAll(".clip").forEach(function(c){
        var mini=c.querySelector(".mini"); var type=(c.className.match(/\b(video|audio|image|text|adjustment|caption)\b/)||[])[1]||"clip";
        c.setAttribute("role","button"); c.setAttribute("tabindex","0");
        c.setAttribute("aria-label",type+" clip "+(mini?mini.textContent.trim():"")+" on "+tn);
        c.setAttribute("aria-pressed",c.classList.contains("selected")?"true":"false");
        c.querySelectorAll(".handle").forEach(function(h){h.setAttribute("aria-hidden","true")});
      });
    });
    var ts=$("timelineScroll"); if(ts){ts.setAttribute("role","region");ts.setAttribute("aria-label","Timeline");ts.setAttribute("tabindex","0");}
    var pv=$("preview")||document.querySelector("canvas#previewCanvas,#previewCanvas"); if(pv&&!pv.getAttribute("aria-label")){pv.setAttribute("role","img");pv.setAttribute("aria-label","Video preview")}
    var sb=document.querySelector("aside.sidebar"); if(sb&&!sb.getAttribute("aria-label")) sb.setAttribute("aria-label","Media and tools");
    var ins=$("inspector"); if(ins&&!ins.getAttribute("aria-label")) ins.setAttribute("aria-label","Inspector");
    var st=$("status"); if(st&&!st.getAttribute("aria-live")){st.setAttribute("aria-live","polite");st.setAttribute("role","status");}
    document.querySelectorAll(".toolbtn.tool-active").forEach(function(b){b.setAttribute("aria-pressed","true")});
    document.querySelectorAll('.toolbtn[id^="tool"]:not(.tool-active)').forEach(function(b){b.setAttribute("aria-pressed","false")});
  }
  /* keyboard: Enter/Space on a focused clip selects it */
  document.addEventListener("keydown",function(e){
    var c=e.target&&e.target.classList&&e.target.classList.contains("clip")?e.target:null; if(!c)return;
    if(e.key==="Enter"||e.key===" "){ e.preventDefault(); c.click(); setTimeout(function(){ var again=document.querySelector('#tracks .clip.selected'); if(again) say("Selected "+(again.getAttribute("aria-label")||"clip")); },60); }
  });
  var t=null; function sched(){clearTimeout(t); t=setTimeout(function(){ (window.requestIdleCallback||function(f){setTimeout(f,0)})(pass,{timeout:1500}); },400);}
  new MutationObserver(function(ms){ for(var i=0;i<ms.length;i++){ var a=ms[i].addedNodes; for(var j=0;j<a.length;j++){ if(a[j].nodeType===1){ sched(); return; } } } }).observe(document.body,{childList:true,subtree:true});
  pass();
})();

