/* ==================== Script 114 ==================== */
/* Editor step 6: on phones, secondary top-bar controls move into a "More" menu instead of being clipped */
(function(){
  var bar=document.querySelector("header.topbar"); if(!bar) return;
  var mq=window.matchMedia("(max-width:1024px)"), collapsed=false;
  var KEEP={projectName:1,saveStatus:1,saveDot:1,undoBtn:1,redoBtn:1,exportBtn:1,topMoreBtn:1,vsThemeBtn:1,vsColorBtn:1,pwaInstallBtn:1,wsBtn:1};
  var more=document.createElement("button"); more.type="button"; more.id="topMoreBtn"; more.className="topbtn"; more.textContent="⋯"; more.setAttribute("aria-label","More actions"); more.setAttribute("aria-haspopup","true"); more.setAttribute("aria-expanded","false");
  var menu=document.createElement("div"); menu.className="top-more"; menu.id="topMore"; menu.setAttribute("role","group"); menu.setAttribute("aria-label","More actions");
  var scrim=document.createElement("div"); scrim.className="top-more-scrim";
  var exp=document.getElementById("exportBtn"); bar.insertBefore(more,exp||null);
  document.body.appendChild(scrim); document.body.appendChild(menu);
  var homes=new Map();   /* element -> placeholder comment marking where it lives on desktop */
  function movable(el){ return el.nodeType===1 && !KEEP[el.id] && !el.classList.contains("brand") && !el.classList.contains("top-spacer") && el!==more; }
  function toMenu(el){ if(homes.has(el)) return; var ph=document.createComment("topbar-home"); el.parentNode.insertBefore(ph,el); homes.set(el,ph); menu.appendChild(el); }
  function toBar(){ homes.forEach(function(ph,el){ if(ph.parentNode) ph.parentNode.insertBefore(el,ph), ph.remove(); else bar.insertBefore(el,more); }); homes.clear(); }
  function sweep(){ if(!collapsed) return; [].slice.call(bar.children).forEach(function(el){ if(movable(el)) toMenu(el); }); more.style.display=menu.children.length?"":"none"; }
  function close(ret){ menu.classList.remove("open"); scrim.classList.remove("open"); more.setAttribute("aria-expanded","false"); if(ret) try{more.focus()}catch(e){window.__swl&&window.__swl(e)} }
  function open(){ menu.classList.add("open"); scrim.classList.add("open"); more.setAttribute("aria-expanded","true"); var f=menu.querySelector("button,select,input"); if(f) try{f.focus()}catch(e){window.__swl&&window.__swl(e)} }
  more.addEventListener("click",function(e){ e.stopPropagation(); menu.classList.contains("open")?close(true):open(); });
  scrim.addEventListener("click",function(){close(true)});
  /* choosing an action closes the menu (selects and inputs keep it open) */
  menu.addEventListener("click",function(e){ if(e.target.closest("button")) setTimeout(function(){ if(!document.getElementById("modalBackdrop")||true) close(false); },0); });
  document.addEventListener("keydown",function(e){ if(e.key==="Escape"&&menu.classList.contains("open")){ e.stopPropagation(); close(true); } },true);
  function fits(){ toBar(); document.body.classList.remove("topbar-collapsed"); return bar.scrollWidth<=bar.clientWidth+2; }
  function apply(){
    var want=mq.matches || !fits();
    if(want){ collapsed=true; document.body.classList.add("topbar-collapsed"); sweep(); }
    else { collapsed=false; close(false); toBar(); document.body.classList.remove("topbar-collapsed"); more.style.display="none"; }
  }
  (mq.addEventListener?mq.addEventListener("change",apply):mq.addListener(apply));
  var rt=null; window.addEventListener("resize",function(){ clearTimeout(rt); rt=setTimeout(apply,150); });
  var t=null; new MutationObserver(function(){ clearTimeout(t); t=setTimeout(function(){ if(collapsed) sweep(); else apply(); },80); }).observe(bar,{childList:true});
  setTimeout(apply,600);
  apply();
})();

