/* ==================== Script 120 id="amiyo-editor-s13" ==================== */
/* Editor step 13 (list step 1): audit fix - picking files from the phone's file picker did nothing.
   The picker empties its live file list right after handing it over, and the storage check added in an
   earlier round read that list afterwards. The list is now copied first (fixed in place above), and this layer
   tells you plainly when a file could not be imported instead of staying silent. */
(function(){
  window.AMIYO_EDITOR_BUILD = "step13";
  var inner = window.importFiles; if(typeof inner !== "function") return;
  function say(m){ try{ window.toast(m, 5200); }catch(e){window.__swl&&window.__swl(e)} }
  function kind(f){ try{ return typeof classify === "function" ? classify(f) : "unknown"; }catch(e){ return "unknown"; } }
  window.importFiles = async function(files){
    var list = [].slice.call(files || []);
    if(!list.length) return [];
    var added = [], failed = false;
    try{ added = await inner.call(this, list); }catch(e){ failed = true; console.error("importFiles", e); }
    var mediaCount = list.filter(function(f){ var k = kind(f); return k==="video"||k==="audio"||k==="image"; }).length;
    if(failed) say("Couldn't import " + (list.length===1 ? "\u201c"+list[0].name+"\u201d" : "those files") + ". Try a different file or format.");
    else if(mediaCount && Array.isArray(added) && added.length === 0 && !(window.__amiyoImportMode)) say("Nothing was imported. The file may be empty or damaged.");
    return added;
  };
})();

