/* ==================== Script 121 id="amiyo-editor-s14" ==================== */
/* Editor step 14: on a touch screen the "( , )" / "( . )" keyboard hints in button labels are just noise */
(function(){
  if(!window.matchMedia || !matchMedia("(pointer:coarse)").matches) return;
  function clean(){
    document.querySelectorAll("button.chip,button.toolbtn").forEach(function(b){
      if(b.children.length||b.id==="impStore") return;
      var t=b.textContent; if(/\s\((?:[^)\s]{1,3})\)\s*$/.test(t)) b.textContent=t.replace(/\s\((?:[^)\s]{1,3})\)\s*$/,"");
    });
  }
  var tm=null; new MutationObserver(function(){ clearTimeout(tm); tm=setTimeout(clean,150); }).observe(document.body,{childList:true,subtree:true});
  clean();
})();

