/* ==================== Script 122 id="amiyo-editor-s15" ==================== */
/* Editor step 15: the Library and Inspector bottom sheets behave like real dialogs for screen readers and keyboards:
   named, background inert, focus moves in, Esc closes, focus returns to the button that opened them. */
(function(){
  var app=document.querySelector(".app"); if(!app) return;
  var $=function(id){return document.getElementById(id)};
  var opener=null, current=null;
  var BG=["header.topbar",".center"];
  function setBg(on){ BG.forEach(function(q){ var e=document.querySelector(q); if(!e) return; if(on){ e.setAttribute("inert",""); } else e.removeAttribute("inert"); }); }
  function sheetFor(){ if(app.classList.contains("sheet-lib")) return {el:document.querySelector(".sidebar"),name:"Library and tools",btn:$("mbLib")};
    if(app.classList.contains("sheet-insp")) return {el:document.querySelector(".inspector-col"),name:"Inspector",btn:$("mbInsp")}; return null; }
  function sync(){
    var s=sheetFor();
    var lib=$("mbLib"), insp=$("mbInsp");
    if(lib) lib.setAttribute("aria-expanded", app.classList.contains("sheet-lib")?"true":"false");
    if(insp) insp.setAttribute("aria-expanded", app.classList.contains("sheet-insp")?"true":"false");
    if(current && (!s || s.el!==current.el)){ current.el.removeAttribute("role"); current.el.removeAttribute("aria-modal"); current=null; }
    if(s && s.el && (!current || current.el!==s.el)){
      if(!opener) opener=s.btn;
      s.el.setAttribute("role","dialog"); s.el.setAttribute("aria-modal","true"); s.el.setAttribute("aria-label",s.name);
      current=s; setBg(true);
      setTimeout(function(){ var c=s.el.querySelector(".sheet-close"); if(c) c.focus(); },60);
      try{ window.a11ySay&&window.a11ySay(s.name+" opened"); }catch(e){window.__swl&&window.__swl(e)}
    }
    if(!s){ setBg(false); if(opener&&document.contains(opener)){ try{opener.focus()}catch(e){window.__swl&&window.__swl(e)} } opener=null; }
  }
  new MutationObserver(sync).observe(app,{attributes:true,attributeFilter:["class"]});
  document.addEventListener("keydown",function(e){
    if(e.key!=="Escape"||!current) return;
    var bd=$("modalBackdrop"); if(bd && bd.style.display && bd.style.display!=="none") return; /* a dialog on top closes first */
    var c=current.el.querySelector(".sheet-close"); if(c){ e.preventDefault(); c.click(); }
  });
  /* keep Tab inside the open sheet and the bottom bar */
  document.addEventListener("keydown",function(e){
    if(e.key!=="Tab"||!current) return;
    var f=[].slice.call(current.el.querySelectorAll('button,a[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')).filter(function(x){return x.offsetParent!==null&&!x.disabled});
    if(!f.length) return; var a=document.activeElement;
    if(!current.el.contains(a)) return;
    if(!e.shiftKey&&a===f[f.length-1]){ e.preventDefault(); f[0].focus(); } else if(e.shiftKey&&a===f[0]){ e.preventDefault(); f[f.length-1].focus(); }
  });
  sync();
})();

