/* ==================== Script 123 id="amiyo-editor-s16" ==================== */
/* Editor step 16 (list step 4): timeline gesture polish - double-tap empty timeline space to fit the whole project,
   and a short vibration on split / delete so a touch edit feels confirmed. */
(function(){
  var ts=document.getElementById("timelineScroll"); if(!ts) return;
  var last=0, lx=0, ly=0, downAt=0, moved=false, sx=0, sy=0;
  ts.addEventListener("pointerdown",function(e){ if(e.pointerType==="mouse") return; downAt=Date.now(); sx=e.clientX; sy=e.clientY; moved=false; },true);
  ts.addEventListener("pointermove",function(e){ if(Math.hypot(e.clientX-sx,e.clientY-sy)>10) moved=true; },true);
  ts.addEventListener("pointerup",function(e){
    if(e.pointerType==="mouse"||moved||Date.now()-downAt>350) return;
    if(e.target.closest&&(e.target.closest(".clip")||e.target.closest("#ruler")||e.target.closest(".track-label"))){ last=0; return; }
    var now=Date.now();
    if(now-last<320 && Math.hypot(e.clientX-lx,e.clientY-ly)<30){
      last=0; var f=document.getElementById("fitBtn"); if(f){ f.click(); try{ window.toast("Fitted to the whole project",1400); }catch(x){window.__swl&&window.__swl(x)} }
    } else { last=now; lx=e.clientX; ly=e.clientY; }
  },true);
  function buzz(ms){ try{ if(navigator.vibrate) navigator.vibrate(ms); }catch(e){window.__swl&&window.__swl(e)} }
  ["splitBtn","mbSplit"].forEach(function(id){ var b=document.getElementById(id); if(b) b.addEventListener("click",function(){ buzz(15); },true); });
  var d=document.getElementById("mbDelete")||document.getElementById("deleteBtn"); if(d) d.addEventListener("click",function(){ buzz([10,40,10]); },true);
})();

