/* ==================== Script 124 id="amiyo-editor-s17" ==================== */
/* Editor step 17: edge fades on the horizontally scrolling toolbars, so cut-off buttons ("Fi…", "Trim end") read as "more this way" */
(function(){
  var SEL=".preview-toolbar,.timeline-toolbar,.sidebar .nav,.mchips";
  function upd(el){ var max=el.scrollWidth-el.clientWidth; el.classList.toggle("fl",el.scrollLeft>4); el.classList.toggle("fr",max>4&&el.scrollLeft<max-4); }
  function wire(el){ if(el.__fade) return; el.__fade=1; el.classList.add("hscroll-fade"); el.addEventListener("scroll",function(){upd(el)},{passive:true}); upd(el); }
  function all(){ document.querySelectorAll(SEL).forEach(function(el){ wire(el); upd(el); }); }
  var t=null; new MutationObserver(function(){ clearTimeout(t); t=setTimeout(all,120); }).observe(document.body,{childList:true,subtree:true});
  window.addEventListener("resize",all); window.addEventListener("orientationchange",all);
  all(); setTimeout(all,800);
})();

