/* ==================== Script 125 id="amiyo-editor-s18" ==================== */
/* Editor step 18: the save status text is hidden on narrow phones, so a coloured dot beside the project name shows it
   (green saved, amber saving, red not saved). Tap it to open Storage & recovery. */
(function(){
  var st=document.getElementById("saveStatus"), pn=document.getElementById("projectName"); if(!st||!pn) return;
  var d=document.createElement("button"); d.type="button"; d.className="save-dot idle"; d.id="saveDot"; d.innerHTML="<i></i><b></b>";
  pn.insertAdjacentElement("afterend",d);
  function upd(){
    var t=(st.textContent||"").trim(), c="idle";
    if(/not saved|unavailable|full|fail/i.test(t)) c="bad"; else if(/saving/i.test(t)) c="saving"; else if(/saved|restored/i.test(t)) c="";
    d.className="save-dot "+c; d.querySelector("b").textContent=t;
    d.setAttribute("aria-label","Project status: "+(t||"unknown")+". Open storage and recovery");
    d.title=t;
  }
  new MutationObserver(upd).observe(st,{childList:true,characterData:true,subtree:true}); upd();
  d.addEventListener("click",function(){ if(window.amiyoStorageDialog) window.amiyoStorageDialog(); });
  /* on a failed save, say so loudly once, with the way out */
  var warned=0;
  new MutationObserver(function(){ var t=st.textContent||""; if(/not saved/i.test(t) && Date.now()-warned>60000){ warned=Date.now(); try{ window.toast("Couldn't save. Browser storage is full or blocked. Export your project to keep it safe.",6000); }catch(e){window.__swl&&window.__swl(e)} } }).observe(st,{childList:true,characterData:true,subtree:true});
})();

