/* ==================== Script 126 id="amiyo-editor-s19" ==================== */
/* Editor step 19 (list step 7): a clear "your video is ready" step. On a phone the automatic download can be missed or blocked,
   so when an export finishes you get the file size, a Save button (re-download) and, where the phone supports it, Share.
   The progress text no longer sits on "about 1 s left" after the export is done. */
(function(){
  var $=function(id){return document.getElementById(id)};
  function esc(x){return String(x==null?"":x).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
  function mb(n){return (n/1048576).toFixed(n<10485760?2:1)+" MB"}
  var prev=window.amiyoOnExport;
  window.amiyoOnExport=function(blob,fname){
    try{ if(typeof prev==="function") prev.apply(this,arguments); }catch(e){window.__swl&&window.__swl(e)}
    var t=$("expTxt"); if(t) t.textContent="Export finished";
    setTimeout(function(){ ready(blob,fname); },700);
  };
  function ready(blob,fname){
    if(!blob) return;
    var file=null, canShare=false;
    try{ file=new File([blob],fname,{type:blob.type||"video/webm"}); canShare=!!(navigator.canShare&&navigator.canShare({files:[file]})); }catch(e){window.__swl&&window.__swl(e)}
    window.openModal("Your video is ready",
      '<p style="margin:0 0 4px"><b>'+esc((window.__amiyoWhere&&window.__amiyoSavedAs)||fname)+'</b></p><p style="margin:0 0 12px;font-size:12px;color:var(--muted)">'+mb(blob.size)+' · '+(window.__amiyoWhere?("saved to the folder \u201c"+esc(window.__amiyoWhere)+"\u201d."):"saved to your Downloads folder.")+' If you can\u2019t find it, save it again here.</p>'+
      '<div class="mini-row"><button class="chip" id="rdSave" style="background:var(--accent);color:#1a0c03;font-weight:700">Save again</button>'+
      (canShare?'<button class="chip" id="rdShare">Share…</button>':'')+
      '<button class="chip" id="rdClose">Done</button></div>');
    try{ window.a11ySay&&window.a11ySay("Export finished. "+fname+", "+mb(blob.size),true); }catch(e){window.__swl&&window.__swl(e)}
    var s=$("rdSave"); if(s) s.onclick=function(){ var u=URL.createObjectURL(blob), a=document.createElement("a"); a.href=u; a.download=fname; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){URL.revokeObjectURL(u)},8000); };
    var sh=$("rdShare"); if(sh) sh.onclick=function(){ navigator.share({files:[file],title:fname}).catch(function(){}); };
    var c=$("rdClose"); if(c) c.onclick=function(){ window.closeModal(); };
  }
})();

