/* ==================== Script 127 id="amiyo-editor-s20" ==================== */
/* Editor step 20 (list step 8): preview performance, phone tuning.
   The editor already coalesces renders, caches thumbnails/waveforms and has Auto draft quality, which kicks in when frames
   average over 45 ms. A phone should back off sooner, so on a touch screen Auto now switches to the lighter preview at 30 ms
   and returns once frames settle under 20 ms. Exports and Full/Draft choices are never changed.
   Also: no preview drawing while the tab is hidden (except exporting). */
(function(){
  var orig=window.__amiyoDraft; if(typeof orig!=="function") return;
  var coarse=window.matchMedia&&matchMedia("(pointer:coarse)").matches, on=false, since=0;
  function mode(){ try{ return localStorage.getItem("amiyo_editor_preview_quality")||"auto"; }catch(e){ return "auto"; } }
  window.__amiyoDraft=function(){
    var base=orig.apply(this,arguments);
    if(base||!coarse||window.__amiyoExporting||mode()!=="auto") return base;
    if(typeof isPlaying==="undefined"||!isPlaying){ on=false; return false; }
    var a=(window.__amiyoPerf&&window.__amiyoPerf.avg)||0, now=performance.now();
    if(!on&&a>30){ on=true; since=now; } else if(on&&a<20&&now-since>2500) on=false;
    return on;
  };
  var r=window.renderPreviewFrame;
  if(typeof r==="function") window.renderPreviewFrame=function(){
    if(document.visibilityState==="hidden"&&!window.__amiyoExporting) return Promise.resolve();
    return r.apply(this,arguments);
  };
  document.addEventListener("visibilitychange",function(){ if(document.visibilityState==="visible"){ try{ window.renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} } });
})();

