/* ==================== Script 132 id="amiyo-editor-step24-improve2" ==================== */
/* ===== Editor step 24 (improve step 2): real dialogs instead of the browser's pop-ups =====
   The editor used the browser's prompt() and confirm() in 11 places (rename, delete, freeze frame, open a
   project, agent actions...). On phones those are small, can be blocked inside an installed app or a
   frame, and freeze the whole page. They are now one in-app dialog: big buttons, Enter to confirm,
   Esc to cancel, focus kept inside, and focus returned to where you were.
   window.amiyoAsk(message, default, {number,min,step}) -> text or null.  window.amiyoOk(message, {okLabel, danger}) -> true/false. */
(function(){
  "use strict";
  var st=document.createElement("style");
  st.textContent=
  ".adlg-back{position:fixed;inset:0;z-index:400;display:grid;place-items:center;padding:16px;background:rgba(6,5,4,.72)}"+
  ".adlg{width:min(420px,100%);background:var(--panel2,#191815);color:var(--text,#f1ece2);border:1px solid var(--line,#302c26);border-radius:14px;box-shadow:0 20px 60px rgba(0,0,0,.6);padding:18px}"+
  ".adlg-msg{font-size:14px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere;margin:0 0 12px}"+
  ".adlg-in{width:100%;box-sizing:border-box;margin:0 0 14px;font-size:16px;min-height:44px}"+
  ".adlg-row{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap}"+
  ".adlg-row button{min-height:44px;min-width:96px;padding:8px 16px;border-radius:9px;border:1px solid var(--line,#302c26);background:var(--panel3,#211f1b);color:inherit;font-size:14px;cursor:pointer}"+
  ".adlg-row button.adlg-ok{background:linear-gradient(155deg,var(--accent,#ff7a3d),#e8622a);color:#1a0c03;border-color:transparent;font-weight:700}"+
  ".adlg-row button.adlg-bad{background:#c0364a;color:#fff;border-color:transparent;font-weight:700}"+
  "@media (max-width:480px){.adlg-row button{flex:1 1 40%}}";
  document.head.appendChild(st);
  var chain=Promise.resolve(), seq=0;
  function open(kind,msg,def,o){
    o=o||{};
    return new Promise(function(resolve){
      var prevFocus=document.activeElement, mid="adlgMsg"+(++seq);
      var back=document.createElement("div"); back.className="adlg-back";
      var box=document.createElement("div"); box.className="adlg";
      box.setAttribute("role",kind==="ok"?"alertdialog":"dialog"); box.setAttribute("aria-modal","true"); box.setAttribute("aria-labelledby",mid);
      var p=document.createElement("div"); p.className="adlg-msg"; p.id=mid; p.textContent=String(msg==null?"":msg); box.appendChild(p);
      var inp=null;
      if(kind==="ask"){
        inp=document.createElement("input"); inp.type=o.number?"number":"text"; inp.className="adlg-in";
        inp.value=def==null?"":String(def); inp.setAttribute("aria-label",String(msg));
        if(o.number){ inp.step=o.step||"any"; inp.inputMode="decimal"; if(o.min!=null) inp.min=o.min; }
        box.appendChild(inp);
      }
      var row=document.createElement("div"); row.className="adlg-row";
      var no=document.createElement("button"); no.type="button"; no.textContent=o.cancelLabel||"Cancel";
      var yes=document.createElement("button"); yes.type="button"; yes.textContent=o.okLabel||"OK"; yes.className=o.danger?"adlg-bad":"adlg-ok";
      row.appendChild(no); row.appendChild(yes); box.appendChild(row); back.appendChild(box); document.body.appendChild(back);
      var finished=false;
      function done(v){
        if(finished) return; finished=true;
        document.removeEventListener("keydown",key,true);
        if(back.parentNode) back.parentNode.removeChild(back);
        try{ if(prevFocus&&prevFocus.focus&&document.contains(prevFocus)) prevFocus.focus({preventScroll:true}); }catch(e){window.__swl&&window.__swl(e)}
        resolve(v);
      }
      var cancelVal=kind==="ask"?null:false;
      function accept(){ done(kind==="ask"?inp.value:true); }
      function key(e){
        e.stopPropagation();
        if(e.key==="Escape"){ e.preventDefault(); done(cancelVal); }
        else if(e.key==="Enter"&&e.target!==no){ e.preventDefault(); accept(); }
        else if(e.key==="Tab"){
          var f=[].slice.call(box.querySelectorAll("input,button")), i=f.indexOf(document.activeElement);
          if(i<0){ e.preventDefault(); f[0].focus(); }
          else if(e.shiftKey&&i===0){ e.preventDefault(); f[f.length-1].focus(); }
          else if(!e.shiftKey&&i===f.length-1){ e.preventDefault(); f[0].focus(); }
        }
      }
      document.addEventListener("keydown",key,true);
      no.onclick=function(){ done(cancelVal); };
      yes.onclick=accept;
      back.addEventListener("pointerdown",function(e){ if(e.target===back) done(cancelVal); });
      setTimeout(function(){ try{ if(inp){ inp.focus({preventScroll:true}); inp.select(); } else (o.danger?no:yes).focus({preventScroll:true}); }catch(e){window.__swl&&window.__swl(e)} },0);
    });
  }
  function queued(kind,msg,def,o){ var r=chain.then(function(){ return open(kind,msg,def,o); }); chain=r.catch(function(){}); return r; }
  window.amiyoAsk=function(msg,def,o){ return queued("ask",msg,def,o); };
  window.amiyoOk=function(msg,o){ return queued("ok",msg,null,o); };
})();

