/* ==================== Script 134 id="amiyo-editor-step25-improve3" ==================== */
/* ===== Editor step 25 (improve step 3): safe commands, and errors you can see =====
   1) The command palette ran its commands by building code from text (new Function). It now only calls a
      known editor function by name (window.amiyoRunCmd), and the palette runs the command you clicked
      even after you type in the search box (it used to run the wrong one) - Enter runs the first match.
   2) Errors that nothing caught used to vanish silently. They are now kept (last 40) and shown once in a
      while as a short message, and listed with a Copy button in Diagnostics > Editor health. */
(function(){
  "use strict";
  window.amiyoRunCmd=function(s){
    var m=/^\s*([A-Za-z_$][\w$]*)\(\s*(?:'([^']*)'|"([^"]*)")?\s*\)\s*;?\s*$/.exec(String(s));
    if(!m) throw new Error("Unknown command");
    var ok=false;
    try{ ok=commandList().some(function(c){ return String(c[1]).indexOf(m[1]+"(")===0; }); }catch(e){window.__swl&&window.__swl(e)}
    if(!ok) throw new Error("Command not available: "+m[1]);
    var fn=window[m[1]]; if(typeof fn!=="function") throw new Error("Command not available: "+m[1]);
    var arg=m[2]!==undefined?m[2]:m[3];
    return arg!==undefined?fn(arg):fn();
  };
  var LOG=window.__amiyoErrors=window.__amiyoErrors||[], last=0, MAX=40;
  function text(x){ try{ if(x==null) return ""; if(typeof x==="string") return x; return x.message||String(x); }catch(e){ return ""; } }
  function record(kind,e,where){
    var m=text(e).replace(/\s+/g," ").trim();
    if(!m||m==="Script error."||/ResizeObserver loop|Cache storage is disabled|sandboxed/i.test(m)) return;
    if(window.amiyoReportError){ window.amiyoReportError(kind==="promise"?"A background task failed":"Something went wrong",m,{where:where,kind:kind,fromGlobal:true}); return; }
    LOG.push({t:Date.now(),kind:kind,msg:m.slice(0,300),where:where||""}); if(LOG.length>MAX) LOG.shift();
    if(window.__amiyoExporting) return;
    var now=Date.now(); if(now-last<6000) return; last=now;
    try{ window.toast("Something went wrong: "+m.slice(0,90)+". Your project is autosaved. Details: Diagnostics > Editor health.",6500); }catch(e2){window.__swl&&window.__swl(e2)}
  }
  window.addEventListener("error",function(e){ record("error",e.error||e.message,e.lineno?("line "+e.lineno):""); });
  window.addEventListener("unhandledrejection",function(e){ record("promise",e.reason,""); });
  window.amiyoErrorLog=function(){ return LOG.slice(); };
  var om=window.openModal;
  if(typeof om==="function") window.openModal=function(title){
    var r=om.apply(this,arguments);
    if(title==="Editor health"){
      try{
        var b=document.getElementById("modalBody"); if(b&&!document.getElementById("ehErrors")){
          var g=document.createElement("div"); g.id="ehErrors"; g.className="group"; g.style.padding="10px 0 0";
          var h=document.createElement("h3"); h.textContent="Recent errors ("+LOG.length+")"; g.appendChild(h);
          if(!LOG.length){ var n=document.createElement("div"); n.style.cssText="color:var(--muted);font-size:12px"; n.textContent="None since this page opened."; g.appendChild(n); }
          else{
            LOG.slice(-8).reverse().forEach(function(x){ var d=document.createElement("div"); d.className="rc-row"; d.style.fontSize="11px";
              var a=document.createElement("div"); a.textContent=new Date(x.t).toLocaleTimeString()+" · "+x.kind+(x.where?" · "+x.where:""); var c=document.createElement("div"); c.style.cssText="text-align:right;color:var(--muted);max-width:62%;overflow-wrap:anywhere"; c.textContent=x.msg; d.appendChild(a); d.appendChild(c); g.appendChild(d); });
            var cp=document.createElement("button"); cp.type="button"; cp.className="chip"; cp.style.marginTop="8px"; cp.textContent="Copy errors";
            cp.onclick=function(){ var t=LOG.map(function(x){ return new Date(x.t).toISOString()+" "+x.kind+" "+x.where+" "+x.msg; }).join("\n"); try{ navigator.clipboard.writeText(t).then(function(){ window.toast("Errors copied"); },function(){ window.toast("Could not copy"); }); }catch(e){ window.toast("Could not copy"); } };
            g.appendChild(cp);
          }
          b.appendChild(g);
        }
      }catch(e){window.__swl&&window.__swl(e)}
    }
    return r;
  };
})();

