/* Step 3: re-render the visible part of a big timeline as you scroll */
(function(){
  const sc=document.getElementById("timelineScroll"); if(!sc) return;
  let key=null, raf=0;
  sc.addEventListener("scroll",function(){
    if(raf) return;
    raf=requestAnimationFrame(function(){
      raf=0;
      const k=Math.floor(sc.scrollLeft/Math.max(1,sc.clientWidth*.85)); if(k===key) return; key=k;
      try{
        const wide=document.getElementById("tracks").offsetWidth>20000;
        if(wide) renderRuler();
        if(amiyoClipCount()>12||wide) window.renderTracks();
      }catch(e){window.__swl&&window.__swl(e)}
    });
  },{passive:true});
})();

