/* ==================== Script 138 id="amiyo-editor-step32-audit" ==================== */
/* Step 1 (long-video plan): audit. Adds "Long-video audit" under Diagnostics: measures what a big project costs today
   (project size, undo memory, media size, timeline width, export route) so step 10 can compare before and after. */
(function(){
  var $=function(id){return document.getElementById(id)};
  function esc(x){return String(x==null?"":x).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
  function mb(n){return n>=1073741824?(n/1073741824).toFixed(2)+" GB":(n/1048576).toFixed(n<10485760?1:0)+" MB"}
  function hms(s){s=Math.max(0,Math.round(s));var h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return (h?h+"h ":"")+m+"m "+x+"s"}
  async function measure(){
    var p=window.project, r=[], clips=0, long=0, big=0, bytes=0, vids=0;
    if(p){
      p.tracks.forEach(function(t){clips+=t.clips.length});
      Object.values(p.assets||{}).forEach(function(a){ bytes+=a.size||0; if(a.type==="video")vids++; if((a.duration||0)>1800)long++; if((a.size||0)>500*1048576)big++; });
    }
    var dur=p&&window.getProjectDuration?window.getProjectDuration():0;
    var t0=performance.now(), json=""; try{ json=JSON.stringify(window.serializableProject()); }catch(e){window.__swl&&window.__swl(e)}
    var saveMs=performance.now()-t0;
    var H=window.amiyoHistoryStats?window.amiyoHistoryStats():null;
    var tr=$("tracks");
    r.push(["Project length",hms(dur)]);
    r.push(["Clips / media",clips+" clips, "+Object.keys(p?p.assets||{}:{}).length+" media ("+vids+" video)"]);
    r.push(["Total media size",mb(bytes)+(big?", "+big+" file(s) over 500 MB":"")]);
    r.push(["Sources over 30 min",String(long)]);
    r.push(["Project data",mb(json.length)+", built in "+saveMs.toFixed(0)+" ms (this runs on every autosave)"]);
    if(H) r.push(["Undo history",H.steps+" steps, "+mb(H.bytes)]);
    r.push(["Timeline width",tr?Math.round(tr.offsetWidth)+" px":"n/a"]);
    r.push(["Preview speed",(window.__amiyoPerf&&window.__amiyoPerf.frames)?window.__amiyoPerf.avg.toFixed(1)+" ms/frame":"press Play to measure"]);
    r.push(["Export route",(window.amiyoFastAvailable&&window.amiyoFastAvailable())?"Fast export (frames drawn as fast as the device can; real-time recording is the backup)":"Real-time recording (a 1 hour film takes 1 hour)"]);
    r.push(["Fast export possible","VideoEncoder "+(window.VideoEncoder?"yes":"no")+", VideoDecoder "+(window.VideoDecoder?"yes":"no")]);
    r.push(["Low-res preview","not built yet (step 2)"]);
    if(performance.memory) r.push(["JS memory",mb(performance.memory.usedJSHeapSize)+" of "+mb(performance.memory.jsHeapSizeLimit)]);
    try{ var e=await navigator.storage.estimate(); if(!e.quota) throw 0; r.push(["Device storage",mb(e.usage)+" of "+mb(e.quota)]); }catch(x){window.__swl&&window.__swl(x)}
    return r;
  }
  async function open(){
    var rows=await measure();
    var html='<div class="group" style="padding:0 0 10px"><h3>Long-video audit</h3>'+rows.map(function(x){return '<div class="rc-row"><div>'+esc(x[0])+'</div><div style="text-align:right;color:var(--muted);max-width:62%">'+esc(x[1])+'</div></div>'}).join("")+
      '<div class="mini-row" style="margin-top:8px"><button class="chip" id="laCopy">Copy report</button></div></div>';
    window.openModal("Long-video audit",html);
    var b=$("laCopy"); if(b) b.onclick=function(){ var t="Amiyo Editor long-video audit\n"+rows.map(function(x){return x[0]+": "+x[1]}).join("\n"); try{ navigator.clipboard.writeText(t).then(function(){window.toast("Report copied")},function(){window.toast("Couldn't copy")}); }catch(e){ window.toast("Couldn't copy"); } };
  }
  window.amiyoAudit=open;
  var sd=window.showDiagnostics;
  if(typeof sd==="function") window.showDiagnostics=function(){
    var r=sd.apply(this,arguments);
    setTimeout(function(){ var b=$("modalBody"); if(!b||$("laOpen")) return; var btn=document.createElement("button"); btn.className="chip"; btn.id="laOpen"; btn.style.cssText="margin:12px 0 0 8px"; btn.textContent="Long-video audit"; btn.onclick=open; b.appendChild(btn); },60);
    return r;
  };
})();
