/* ==================== Script 139 id="amiyo-editor-s15-b" ==================== */
/* Editor step 15: imported video/audio/images now land on the timeline automatically (the preview used to say
   "Nothing at the playhead" because files only went into the Media library and needed a tap on the small + button).
   Skipped when the Import window's "put on timeline" box is off, or when the Director manages the timeline itself. */
(function(){
  window.AMIYO_EDITOR_BUILD = "step15";
  var inner = window.importFiles; if(typeof inner !== "function") return;
  function say(m){ try{ window.toast(m, 4200); }catch(e){window.__swl&&window.__swl(e)} }
  window.importFiles = async function(files){
    var list = [].slice.call(files || []);
    var hadMode = !!window.__amiyoImportMode;          /* set by the Import window / Director */
    var before = new Set(Object.keys(project.assets || {}));
    var added = await inner.call(this, list);
    if(hadMode) return added;
    try{
      var ids = Object.keys(project.assets || {}).filter(function(id){ return !before.has(id); });
      ids = ids.filter(function(id){ var a = project.assets[id]; return a && (a.type==="video"||a.type==="audio"||a.type==="image"); });
      if(ids.length){
        /* place them one after another starting at the playhead */
        ids.forEach(function(id){
          addAssetToTimeline(id);
          var a = project.assets[id], d = Math.max(.5, (a && a.duration) || 5);
          if(a && a.type !== "audio") window.currentTime = (window.currentTime||0);   /* keep playhead */
        });
        /* show the first frame: jump to where the first new clip starts and fit the timeline */
        var first = null;
        for(var t=0;t<project.tracks.length && !first;t++){
          var cl = project.tracks[t].clips.filter(function(c){ return ids.indexOf(c.assetId)>=0; });
          if(cl.length) first = cl.sort(function(x,y){return x.start-y.start;})[0];
        }
        if(first){ try{ setCurrentTime(first.start + 0.01); }catch(e){window.__swl&&window.__swl(e)} }
        var fit = document.getElementById("fitTimelineBtn"); if(fit) setTimeout(function(){ try{ fit.click(); }catch(e){window.__swl&&window.__swl(e)} }, 60);
        say(ids.length===1 ? "Added to the timeline - tap Play" : ids.length+" files added to the timeline - tap Play");
      }
    }catch(e){ console.warn("auto-add", e); }
    return added;
  };
  /* Tapping a media card (not just its small + button) also adds it, so nothing looks "stuck in the library" */
  document.addEventListener("click", function(e){
    var card = e.target.closest && e.target.closest("#leftPanel .asset");
    if(!card || e.target.closest(".asset-add")) return;
    /* the library already treats a click as "load as source"; adding on tap is the phone-friendly behaviour */
    if(window.matchMedia && matchMedia("(pointer:coarse)").matches && card.dataset.asset){
      try{ addAssetToTimeline(card.dataset.asset); }catch(err){window.__swl&&window.__swl(err)}
    }
  }, true);
})();

