  $("trCats").addEventListener("click",e=>{ const b=e.target.closest("[data-cat]"); if(b){ UI_CAT=b.dataset.cat; renderPanel(); } });
  $("trDur").addEventListener("input",e=>{ UI_DUR=Number(e.target.value); $("trDurOut").textContent=UI_DUR.toFixed(2)+" s"; });
