  const before=deepClone(serializableProject()), n0=f.clip.filter, a0=f.clip.filterAmt==null?1:f.clip.filterAmt; let n=0;
  project.tracks.forEach(t=>{ if(t.kind!=="video"||t.locked) return; t.clips.forEach(c=>{ if(c.kind==="adjustment") return; c.filter=n0; c.filterAmt=a0; n++; }); });
