/* ===== Editor step 2 (of 10): Templates gallery that actually loads =====
   Before: the top-bar "Templates" button opened an old five-button list instead of the gallery, and if the
   gallery could not start it silently left a stub. Now every entry opens the real gallery, a failure shows a
   message with a Retry button and a basic fallback, and the gallery has search and six more templates. */
(function(){
"use strict";
function openGallery(){
  try{ const m=document.getElementById("modalBackdrop"); if(m) m.style.display="none"; }catch(e){window.__swl&&window.__swl(e)}
  try{ const tm=document.querySelector(".top-more.open"); if(tm){ tm.classList.remove("open"); const sc=document.querySelector(".top-more-scrim"); if(sc) sc.classList.remove("open"); } }catch(e){window.__swl&&window.__swl(e)}
  activePanel="templates";
  document.querySelectorAll("#nav .navbtn").forEach(b=>b.classList.toggle("active",b.dataset.panel==="templates"));
  try{ if(window.matchMedia("(max-width:1024px)").matches){ const a=document.querySelector(".app"); if(a){ a.classList.remove("sheet-insp"); a.classList.add("sheet-lib"); } } }catch(e){window.__swl&&window.__swl(e)}
  renderLeftPanel();
}
window.openTemplatesGallery=openGallery;
document.addEventListener("click",e=>{
  const b=e.target.closest&&e.target.closest("#amiyoTemplates"); if(!b) return;
  e.preventDefault(); e.stopImmediatePropagation(); openGallery();
},true);
function failPanel(lp,err){
  const msg=String((err&&err.message)||err||"unknown problem");
  try{ console.error("Templates gallery failed:",err); }catch(e){window.__swl&&window.__swl(e)}
  const basic=(typeof window.applyTemplate==="function")?
    '<div style="font-size:11px;color:var(--muted);margin:10px 0 6px">Basic starters still work:</div><div class="mini-row">'+
    ["YouTube Intro","Shorts Hook","Educational","Product Promo","Podcast Clip"].map((n,i)=>'<button type="button" class="chip" data-basic="'+i+'">'+n+'</button>').join("")+'</div>':"";
  lp.innerHTML='<div class="panel-card" role="alert"><h3 style="margin:0 0 6px;font-size:12px;color:var(--danger)">Templates could not load</h3>'+
    '<div style="font-size:11px;line-height:1.5;color:var(--muted)">'+escapeHtml(msg)+'</div>'+
    '<div class="mini-row" style="margin-top:10px"><button type="button" class="chip" id="tpRetry">Try again</button></div>'+basic+'</div>';
  const r=lp.querySelector("#tpRetry"); if(r) r.onclick=()=>renderLeftPanel();
  lp.querySelectorAll("[data-basic]").forEach(x=>x.onclick=()=>{ window.applyTemplate(+x.dataset.basic); });
  try{ if(window.notify) window.notify("Templates could not load — see the panel for details",4000); }catch(e){window.__swl&&window.__swl(e)}
}
const prev=window.renderLeftPanel;
window.renderLeftPanel=function(){
  if(activePanel!=="templates") return prev.apply(this,arguments);
  const lp=document.getElementById("leftPanel"); let err=null;
  try{ prev.apply(this,arguments); }catch(e){ err=e; }
  if(lp && !err && lp.querySelector("#tpGrid")) return;
  if(lp) failPanel(lp, err||new Error(window.AMIYO_TEMPLATES?"The gallery did not draw.":"The template engine did not start (the Elements step failed to load first)."));
};
try{ if(activePanel==="templates") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
})();

