/* ==================== Script 153 ==================== */
/* =========================================================================
   Editor step 6 (of 10): Brand Kit
   Before: the Brand Kit tab was a one-line stub and its only button set two
   colours nobody could see. Now: a kit name, up to 12 brand colours (tap one
   to paint the selected title, caption or shape), a heading font and a body
   font (including fonts you uploaded), a logo that can sit on the video as a
   watermark (corner, size, opacity), one-tap "apply fonts" / "apply colour",
   a branded title, intro and outro cards, and save / load / export / import
   of the kit. Every change is one undo step and is saved with the project.
   ========================================================================= */
(function(){
"use strict";
const KEY="amiyo_brandkit", FONT_KEY="amiyo_fonts", MAXC=12;
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const HEX=/^#[0-9a-f]{6}$/i;
const FONTS=[["system-ui","System"],["Arial, Helvetica, sans-serif","Arial"],["Georgia, serif","Georgia"],["'Courier New', monospace","Courier"],["Impact, sans-serif","Impact"],["'Trebuchet MS', sans-serif","Trebuchet"],["'Space Grotesk', system-ui, sans-serif","Space Grotesk"],["'IBM Plex Sans', system-ui, sans-serif","IBM Plex Sans"],["'IBM Plex Mono', monospace","IBM Plex Mono"],["Verdana, Geneva, sans-serif","Verdana"],["Tahoma, Geneva, sans-serif","Tahoma"],["'Arial Narrow','Roboto Condensed','Franklin Gothic Medium',sans-serif","Narrow condensed"],["'Gill Sans','Gill Sans MT',Calibri,sans-serif","Gill Sans"],["'Palatino Linotype','Book Antiqua',Palatino,serif","Palatino"],["'Times New Roman',Times,serif","Times"],["Garamond,'EB Garamond','Times New Roman',serif","Garamond"],["Baskerville,'Baskerville Old Face','Hoefler Text',Georgia,serif","Baskerville"],["Didot,'Bodoni MT','Bodoni 72',Georgia,serif","Didot / Bodoni"],["Rockwell,'Roboto Slab','Courier New',serif","Rockwell slab"],["'Lucida Console',Monaco,'Courier New',monospace","Lucida mono"],["'Brush Script MT','Segoe Script','Snell Roundhand',cursive","Brush script"],["'Comic Sans MS','Chalkboard SE','Comic Neue',sans-serif","Comic"],["Papyrus,Copperplate,fantasy","Fantasy"],["'Arial Rounded MT Bold',Nunito,'Varela Round',sans-serif","Rounded"],["Optima,Candara,'Segoe UI',sans-serif","Optima"]];
const KITS=[
 {n:"Sunset studio",c:["#ff7a3d","#ffb454","#1a0c03","#fff4e6","#e53935"],h:"Impact, sans-serif",b:"system-ui"},
 {n:"Ocean tech",c:["#ff7835","#5b260b","#ffb48f","#20110a","#ffffff"],h:"'Trebuchet MS', sans-serif",b:"system-ui"},
 {n:"Forest calm",c:["#5fd88a","#1f5d3a","#f3ead3","#0e1a13","#c6ff3d"],h:"Georgia, serif",b:"system-ui"},
 {n:"Royal gold",c:["#ffd76a","#4b1d7a","#16091f","#f6ecff","#c04bff"],h:"Georgia, serif",b:"Georgia, serif"},
 {n:"Candy pop",c:["#ff4fd8","#ffd60a","#ff6518","#2b0f3a","#ffffff"],h:"Impact, sans-serif",b:"system-ui"},
 {n:"Mono minimal",c:["#111111","#f4f1ea","#8a8a8a","#ffffff","#ff7a3d"],h:"system-ui",b:"system-ui"},
 {n:"Retro terminal",c:["#39ff88","#04100a","#ffb454","#0b0c0e","#e7e8ec"],h:"'Courier New', monospace",b:"'Courier New', monospace"},
 {n:"Clean business",c:["#ed621d","#3a1b0b","#e8f0ff","#ffffff","#f5a524"],h:"system-ui",b:"system-ui"}
];
const POS=[["tl","Top left"],["tr","Top right"],["bl","Bottom left"],["br","Bottom right"],["c","Centre"]];

function savedFonts(){ try{ return JSON.parse(localStorage.getItem(FONT_KEY)||"[]"); }catch(e){ return []; } }
function fontOpts(){ return FONTS.concat(savedFonts().map(x=>["'"+x.family+"'",x.family])); }
function kit(){
  const k=project.brandKit=project.brandKit||{};
  if(!Array.isArray(k.colors)) k.colors=[];
  k.colors=k.colors.filter(c=>typeof c==="string"&&HEX.test(c)).slice(0,MAXC);
  if(!k.wm||typeof k.wm!=="object") k.wm={on:false,pos:"br",size:14,opacity:.85};
  if(typeof k.name!=="string") k.name="";
  if(typeof k.heading!=="string"||!k.heading) k.heading=FONTS[0][0];
  if(typeof k.body!=="string"||!k.body) k.body=FONTS[0][0];
  if(typeof k.logo!=="string") k.logo="";
  return k;
}
function say(m,t){ try{ notify(m,t||3000); }catch(e){window.__swl&&window.__swl(e)} }
function lum(h){ const n=parseInt(h.slice(1),16),r=n>>16&255,g=n>>8&255,b=n&255; return (.299*r+.587*g+.114*b)/255; }
function ink(h){ return lum(h)>.6?"#111111":"#ffffff"; }
const hex2=n=>Math.max(0,Math.min(255,Math.round(n))).toString(16).padStart(2,"0");
const toHex=(r,g,b)=>"#"+hex2(r)+hex2(g)+hex2(b);

/* one undo step per change */
function change(label,fn){
  const before=deepClone(serializableProject());
  const r=fn();
  recordHistory(label,before,serializableProject());
  renderAll();
  return r;
}
let pend=null;
function liveEdit(label,fn){ if(!pend) pend={label:label,snap:deepClone(serializableProject())}; fn(); scheduleAutosave(); try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }
function flush(){ if(!pend) return; const p=pend; pend=null; try{ recordHistory(p.label,p.snap,serializableProject()); }catch(e){window.__swl&&window.__swl(e)} try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)} }

/* ---------------- logo + watermark ---------------- */
let logoImg=null, logoSrc="";
function getLogo(){
  const k=project&&project.brandKit; if(!k||!k.logo){ logoImg=null; logoSrc=""; return null; }
  if(logoSrc!==k.logo){ logoSrc=k.logo; const im=new Image(); logoImg=im; im.onload=()=>{ try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }; im.onerror=()=>{ say("The brand logo could not be read — upload it again",4000); }; im.src=k.logo; }
  return (logoImg&&logoImg.complete&&logoImg.naturalWidth)?logoImg:null;
}
let warned=false;
function drawWatermark(){
  const k=project&&project.brandKit; if(!k||!k.wm||!k.wm.on) return;
  const im=getLogo(); if(!im) return;
  const W=canvas.width,H=canvas.height;
  let w=W*Math.min(60,Math.max(3,+k.wm.size||14))/100, h=w*im.naturalHeight/im.naturalWidth;
  if(h>H*.4){ h=H*.4; w=h*im.naturalWidth/im.naturalHeight; }
  const m=W*.03; let x=W-w-m, y=H-h-m;
  const p=k.wm.pos||"br";
  if(p==="tl"){ x=m; y=m; } else if(p==="tr"){ x=W-w-m; y=m; } else if(p==="bl"){ x=m; y=H-h-m; } else if(p==="c"){ x=(W-w)/2; y=(H-h)/2; }
  ctx.save(); ctx.globalAlpha=Math.min(1,Math.max(.05,k.wm.opacity==null?.85:+k.wm.opacity)); ctx.globalCompositeOperation="source-over"; ctx.filter="none"; ctx.shadowColor="transparent"; ctx.shadowBlur=0;
  ctx.drawImage(im,x,y,w,h); ctx.restore();
}
const prevDraw=window.drawOverlays;
window.drawOverlays=function(){
  if(prevDraw) prevDraw.apply(this,arguments);
  try{ drawWatermark(); }catch(e){ if(!warned){ warned=true; console.warn("Watermark draw failed",e); say("The watermark could not be drawn: "+((e&&e.message)||e),4500); } }
};
window.addEventListener("amiyo-booted",()=>{ try{ getLogo(); }catch(e){window.__swl&&window.__swl(e)} },{once:true});

function readImage(file){
  return new Promise((res,rej)=>{
    if(!/^image\//.test(file.type||"")&&!/\.(png|jpe?g|webp|gif|svg)$/i.test(file.name||"")) return rej(new Error("That file is not a picture (use PNG, JPG, WEBP or SVG)."));
    if(file.size>10*1024*1024) return rej(new Error("That picture is over 10 MB — pick a smaller logo."));
    const fr=new FileReader();
    fr.onerror=()=>rej(new Error("The file could not be read."));
    fr.onload=()=>{
      const im=new Image();
      im.onerror=()=>rej(new Error("The picture could not be opened."));
      im.onload=()=>{
        try{
          let w=im.naturalWidth||512,h=im.naturalHeight||512; const s=Math.min(1,384/Math.max(w,h)); w=Math.max(1,Math.round(w*s)); h=Math.max(1,Math.round(h*s));
          const c=document.createElement("canvas"); c.width=w; c.height=h; c.getContext("2d").drawImage(im,0,0,w,h);
          res(c.toDataURL("image/png"));
        }catch(e){ rej(e); }
      };
      im.src=fr.result;
    };
    fr.readAsDataURL(file);
  });
}
function paletteFrom(img){
  const c=document.createElement("canvas"); c.width=c.height=48; const g=c.getContext("2d"); g.drawImage(img,0,0,48,48);
  const d=g.getImageData(0,0,48,48).data, m=new Map();
  for(let i=0;i<d.length;i+=4){
    if(d[i+3]<128) continue;
    const r=d[i],gr=d[i+1],b=d[i+2], mx=Math.max(r,gr,b), mn=Math.min(r,gr,b);
    if(mx-mn<24&&(mx>235||mx<25)) continue;                /* skip plain white / black */
    const key=((r>>4)<<8)|((gr>>4)<<4)|(b>>4);
    const e=m.get(key)||{n:0,r:0,g:0,b:0}; e.n++; e.r+=r; e.g+=gr; e.b+=b; m.set(key,e);
  }
  const arr=[...m.values()].sort((a,b)=>b.n-a.n), out=[];
  for(const e of arr){ const r=e.r/e.n,gr=e.g/e.n,b=e.b/e.n; if(out.every(o=>Math.hypot(o[0]-r,o[1]-gr,o[2]-b)>60)) out.push([r,gr,b]); if(out.length>=5) break; }
  return out.map(o=>toHex(o[0],o[1],o[2]));
}

/* ---------------- applying the kit ---------------- */
function allTextClips(){
  const r=[]; for(const t of project.tracks) for(const c of t.clips){ if(c.kind==="graphic"||c.kind==="caption"||t.kind==="caption"||c.kind==="text"||t.kind==="text"){ if(c.kind==="graphic") continue; r.push({t:t,c:c,cap:(c.kind==="caption"||t.kind==="caption")}); } }
  return r;
}
async function loadFont(fam){ try{ if(document.fonts&&document.fonts.load){ await document.fonts.load("700 32px "+fam); } }catch(e){window.__swl&&window.__swl(e)} try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }
function paintClip(c,color){
  if(c.kind==="graphic"){ c.graphicStyle=Object.assign({},c.graphicStyle,{fill:color,grad:false}); return true; }
  if(c.kind==="text"||c.kind==="caption"||c.textStyle){ c.textStyle=Object.assign({},c.textStyle,{color:color}); return true; }
  return false;
}
function useColor(color){
  const f=getClip(); if(!f){ say("Select a title, caption or shape first — or use “Primary colour on all titles”",3800); return; }
  if(f.track.locked){ say("This track is locked"); return; }
  const ok=change("Brand colour",()=>paintClip(f.clip,color));
  if(!ok) say("That clip has no colour to change — pick a title, caption or shape",3600); else say("Colour applied");
}
function applyFonts(){
  const k=kit(), list=allTextClips().filter(x=>!x.t.locked);
  if(!list.length){ say("There are no titles or captions yet — add one first",3600); return; }
  change("Apply brand fonts",()=>{ list.forEach(x=>{ x.c.textStyle=Object.assign({},x.c.textStyle,{fontFamily:x.cap?k.body:k.heading}); }); });
  loadFont(k.heading); loadFont(k.body);
  say("Fonts applied to "+list.length+" title"+(list.length===1?"":"s")+" and caption"+(list.length===1?"":"s"));
}
function applyPrimary(){
  const k=kit(); if(!k.colors.length){ say("Add a brand colour first",3200); return; }
  const list=allTextClips().filter(x=>!x.cap&&!x.t.locked);
  if(!list.length){ say("There are no titles yet — add one first",3600); return; }
  change("Primary colour on titles",()=>{ list.forEach(x=>{ x.c.textStyle=Object.assign({},x.c.textStyle,{color:k.colors[0]}); }); });
  say("Primary colour applied to "+list.length+" title"+(list.length===1?"":"s"));
}
function textTrack(){
  let t=project.tracks.find(x=>x.kind==="text"&&!x.locked); if(t) return t;
  t={id:uid("track"),name:"Text",kind:"text",locked:false,hidden:false,muted:false,clips:[]}; project.tracks.push(t); return t;
}
function addBrandTitle(){
  const k=kit(), t=textTrack(), col=k.colors[0]||"#ffffff";
  change("Add brand title",()=>{
    const c={id:uid("clip"),kind:"text",name:k.name||"Brand title",start:currentTime,duration:5,text:k.name||"Your title",textStyle:{fontFamily:k.heading,fontSize:64,weight:800,color:col,align:"center",shadow:true},x:.5,y:.5,opacity:1,rotation:0,scale:1,keyframes:[]};
    t.clips.push(c); selectedClipId=c.id; selectedTrackId=t.id;
  });
  loadFont(k.heading);
}
function graphicsTrackFor(start,dur){
  const free=t=>!t.clips.some(c=>start<c.start+c.duration-.001&&start+dur>c.start+.001);
  const hit=project.tracks.find(t=>t.kind==="graphics"&&!t.locked&&free(t)); if(hit) return hit;
  const n=project.tracks.filter(t=>t.kind==="graphics").length+1;
  const t={id:uid("track"),name:"Graphics "+n,kind:"graphics",locked:false,hidden:false,muted:false,clips:[]};
  const i=project.tracks.findIndex(x=>x.kind==="text"||x.kind==="caption");
  if(i<0) project.tracks.push(t); else project.tracks.splice(i,0,t);
  return t;
}
function projectEnd(){ let e=0; for(const t of project.tracks) for(const c of t.clips) e=Math.max(e,c.start+c.duration); return e; }
function addCard(where){
  const k=kit(); if(!k.colors.length){ say("Add a brand colour first — the card uses it as its background",3800); return; }
  const dur=3, start=where==="intro"?0:projectEnd(), col=k.colors[0], col2=k.colors[1]||col;
  change(where==="intro"?"Add brand intro":"Add brand outro",()=>{
    const t=graphicsTrackFor(start,dur);
    const c={id:uid("clip"),kind:"graphic",shape:"rect",name:where==="intro"?"Brand intro":"Brand outro",start:start,duration:dur,x:.5,y:.5,scale:1,opacity:1,rotation:0,gw:1,gh:1,flipX:false,gAnim:"fade",
      label:k.name||"",labelSize:9,labelColor:ink(col),graphicStyle:{fill:col,fill2:col2,grad:col2!==col,stroke:"#ffffff",strokeW:0,shadow:false,radius:0},keyframes:[]};
    t.clips.push(c); t.clips.sort((a,b)=>a.start-b.start); selectedClipId=c.id; selectedTrackId=t.id;
  });
  say((where==="intro"?"Intro card placed over the first 3 seconds":"Outro card added after the last clip"),3600);
}

/* ---------------- save / load / export / import ---------------- */
function cleanKit(o){
  if(!o||typeof o!=="object") throw new Error("That file is not a brand kit.");
  const k={name:String(o.name||"").slice(0,80),colors:(Array.isArray(o.colors)?o.colors:[]).filter(c=>typeof c==="string"&&HEX.test(c)).slice(0,MAXC),
    heading:typeof o.heading==="string"&&o.heading?o.heading.slice(0,160):FONTS[0][0],body:typeof o.body==="string"&&o.body?o.body.slice(0,160):FONTS[0][0],
    logo:typeof o.logo==="string"&&/^data:image\/(png|jpeg|webp|gif);base64,/.test(o.logo)&&o.logo.length<3e6?o.logo:"",
    wm:{on:!!(o.wm&&o.wm.on),pos:POS.some(p=>p[0]===(o.wm&&o.wm.pos))?o.wm.pos:"br",size:Math.min(60,Math.max(3,+(o.wm&&o.wm.size)||14)),opacity:Math.min(1,Math.max(.05,o.wm&&o.wm.opacity!=null?+o.wm.opacity:.85))}};
  return k;
}
function adopt(o,label){
  const c=cleanKit(o);
  change(label,()=>{ const k=kit(); Object.assign(k,c); });
  loadFont(c.heading); loadFont(c.body);
}
function saveDevice(){
  try{ localStorage.setItem(KEY,JSON.stringify(cleanKit(kit()))); say("Saved as your kit on this device"); }
  catch(e){ say("Could not save on this device: "+((e&&e.message)||"storage is full or blocked"),4500); }
}
function loadDevice(){
  let raw=null; try{ raw=localStorage.getItem(KEY); }catch(e){window.__swl&&window.__swl(e)}
  if(!raw){ say("No kit saved on this device yet — use “Save as my kit” first",3800); return; }
  try{ adopt(JSON.parse(raw),"Load brand kit"); say("Your saved kit is loaded"); }catch(e){ say("The saved kit is damaged: "+((e&&e.message)||e),4500); }
}
function exportKit(){
  try{
    const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([JSON.stringify(Object.assign({amiyoBrandKit:1},cleanKit(kit())))],{type:"application/json"}));
    a.download=((kit().name||"brand").replace(/[^\w\-]+/g,"_")||"brand")+".amiyo-brand.json"; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(a.href),4000); say("Brand kit exported");
  }catch(e){ say("Export failed: "+((e&&e.message)||e),4500); }
}
async function importKit(file){
  try{ const o=JSON.parse(await file.text()); adopt(o,"Import brand kit"); say("Brand kit imported"); }
  catch(e){ say("Could not import that file: "+((e&&e.message)||e),4500); }
}
async function addFont(file){
  try{
    const ext=((file.name.match(/\.(\w+)$/)||[])[1]||"").toLowerCase();
    if(!/^(ttf|otf|woff2?)$/.test(ext)) throw new Error("Use a .ttf, .otf, .woff or .woff2 font file.");
    const family=file.name.replace(/\.\w+$/,"").replace(/[^\w \-]/g,"").trim()||"Brand font";
    const buf=await file.arrayBuffer(); const ff=new FontFace(family,buf); await ff.load(); document.fonts.add(ff);
    try{ if(window.amiyoPutBlob) await window.amiyoPutBlob("font:"+family,new Blob([buf],{type:"font/"+ext})); const l=savedFonts().filter(x=>x.family!==family); l.push({family:family,key:"font:"+family}); localStorage.setItem(FONT_KEY,JSON.stringify(l)); }catch(e){ say("Font loaded, but it could not be kept for next time",4000); }
    change("Add brand font",()=>{ const k=kit(); k.heading="'"+family+"'"; });
    say("Font “"+family+"” added and set as the heading font");
  }catch(e){ say("Could not add that font: "+((e&&e.message)||e),4500); }
}

/* ---------------- panel ---------------- */
function injectCss(){
  if(document.getElementById("bk-css")) return;
  const s=document.createElement("style"); s.id="bk-css";
  s.textContent=".bk-lab{display:block;font-size:10px;color:var(--muted);margin:10px 0 4px;letter-spacing:.02em}.bk-sw{position:relative;display:inline-block}"+
  ".bk-sw>button.sw{width:36px;height:36px;border-radius:8px;border:1px solid var(--line);cursor:pointer;padding:0}.bk-sw>button.x{position:absolute;top:-6px;right:-6px;width:18px;height:18px;border-radius:9px;border:1px solid var(--line);background:var(--panel3);color:var(--text);font-size:11px;line-height:1;cursor:pointer;padding:0}"+
  ".bk-logo{display:flex;align-items:center;gap:10px}.bk-logo .pv{width:64px;height:64px;border-radius:8px;border:1px dashed var(--line);display:flex;align-items:center;justify-content:center;background:repeating-conic-gradient(#2a2722 0 25%,#1b1915 0 50%) 0 0/12px 12px;overflow:hidden}.bk-logo .pv img{max-width:100%;max-height:100%}"+
  ".bk-card select,.bk-card input[type=text]{width:100%}.bk-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:6px}.bk-row label{font-size:10px;color:var(--muted);flex:0 0 64px}.bk-row input[type=range]{flex:1;min-width:90px}";
  document.head.appendChild(s);
}
function selHtml(id,cur){
  const fo=fontOpts(); let h='<select id="'+id+'" class="search" aria-label="'+(id==="bkHead"?"Heading font":"Body font")+'">';
  fo.forEach(o=>{ h+='<option value="'+esc(o[0])+'"'+(o[0]===cur?" selected":"")+'>'+esc(o[1])+'</option>'; });
  if(!fo.some(o=>o[0]===cur)) h+='<option value="'+esc(cur)+'" selected>'+esc(cur.replace(/['"]/g,""))+'</option>';
  return h+'</select>';
}
function render(){
  const lp=document.getElementById("leftPanel"); if(!lp) return;
  injectCss(); const k=kit(), wm=k.wm;
  const sw=k.colors.map((c,i)=>'<span class="bk-sw"><button type="button" class="sw" data-act="use" data-i="'+i+'" style="background:'+c+'" title="'+c+(i===0?" (primary)":"")+' — tap to paint the selected clip" aria-label="Use '+c+' on the selected clip"></button><button type="button" class="x" data-act="rm" data-i="'+i+'" aria-label="Remove '+c+'">×</button></span>').join("");
  lp.innerHTML=
  '<div class="panel-card bk-card" id="bkRoot"><h3 style="margin:0 0 8px;font-size:12px">Brand Kit</h3>'+
  '<label class="bk-lab" for="bkName">Brand name (used on titles and cards)</label><input type="text" id="bkName" class="search" maxlength="80" placeholder="e.g. Amiyo Studio" value="'+esc(k.name)+'">'+
  '<span class="bk-lab">Ready-made kits — tap to start from one</span><div class="mini-row" style="flex-wrap:wrap">'+KITS.map((x,i)=>'<button type="button" class="chip" data-act="preset" data-i="'+i+'">'+esc(x.n)+'</button>').join("")+'</div>'+
  '<span class="bk-lab">Colours — the first one is your primary colour</span><div class="mini-row" style="gap:10px;flex-wrap:wrap">'+(sw||'<span style="font-size:11px;color:var(--muted)">No colours yet.</span>')+'</div>'+
  '<div class="bk-row"><input type="color" id="bkPick" value="'+(k.colors[k.colors.length-1]||"#ff7a3d")+'" aria-label="Pick a colour" style="width:44px;height:34px;padding:0;border:1px solid var(--line);border-radius:8px;background:none"><button type="button" class="chip" data-act="addc">Add colour</button>'+(k.logo?'<button type="button" class="chip" data-act="fromlogo">Colours from logo</button>':'')+'</div>'+
  '<span class="bk-lab">Fonts</span><label class="bk-lab" for="bkHead" style="margin-top:0">Heading font (titles)</label>'+selHtml("bkHead",k.heading)+
  '<label class="bk-lab" for="bkBody">Body font (captions)</label>'+selHtml("bkBody",k.body)+
  '<div class="bk-row"><button type="button" class="chip" data-act="font">Upload a font</button></div>'+
  '<span class="bk-lab">Logo</span><div class="bk-logo"><div class="pv">'+(k.logo?'<img alt="Brand logo" src="'+esc(k.logo)+'">':'<span style="font-size:10px;color:var(--muted)">none</span>')+'</div><div class="mini-row"><button type="button" class="chip" data-act="logo">'+(k.logo?"Replace logo":"Upload logo")+'</button>'+(k.logo?'<button type="button" class="chip" data-act="rmlogo">Remove</button>':'')+'</div></div>'+
  (k.logo?'<div class="bk-row"><label for="bkWmOn">Watermark</label><input type="checkbox" id="bkWmOn"'+(wm.on?" checked":"")+' style="width:20px;height:20px"><span style="font-size:10px;color:var(--muted)">show the logo on the whole video</span></div>'+
    '<div class="bk-row"><label for="bkWmPos">Position</label><select id="bkWmPos" class="search" style="flex:1">'+POS.map(p=>'<option value="'+p[0]+'"'+(wm.pos===p[0]?" selected":"")+'>'+p[1]+'</option>').join("")+'</select></div>'+
    '<div class="bk-row"><label for="bkWmSize">Size '+Math.round(wm.size)+'%</label><input type="range" id="bkWmSize" min="4" max="40" step="1" value="'+wm.size+'"></div>'+
    '<div class="bk-row"><label for="bkWmOp">Opacity '+Math.round(wm.opacity*100)+'%</label><input type="range" id="bkWmOp" min="10" max="100" step="5" value="'+Math.round(wm.opacity*100)+'"></div>':'')+
  '<span class="bk-lab">Apply the kit</span><div class="mini-row" style="flex-wrap:wrap"><button type="button" class="chip" data-act="fonts">Apply fonts to all text</button><button type="button" class="chip" data-act="primary">Primary colour on all titles</button><button type="button" class="chip" data-act="title">Add brand title</button><button type="button" class="chip" data-act="intro">Intro card</button><button type="button" class="chip" data-act="outro">Outro card</button></div>'+
  '<span class="bk-lab">Keep your kit</span><div class="mini-row" style="flex-wrap:wrap"><button type="button" class="chip" data-act="save">Save as my kit</button><button type="button" class="chip" data-act="load">Load my kit</button><button type="button" class="chip" data-act="export">Export file</button><button type="button" class="chip" data-act="import">Import file</button></div>'+
  '<div style="margin-top:10px;font-size:10px;line-height:1.5;color:var(--muted)">The kit is saved inside this project. “Save as my kit” also keeps a copy on this device so you can load it into other projects.</div>'+
  '<input type="file" id="bkFile" hidden></div>';
  bind(lp);
}
function pickFile(accept,fn){
  const inp=document.getElementById("bkFile"); if(!inp) return;
  inp.accept=accept; inp.value=""; inp.onchange=()=>{ const f=inp.files&&inp.files[0]; if(f) fn(f); }; inp.click();
}
function bind(lp){
  if(lp.__bkBound) return; lp.__bkBound=true;
  lp.addEventListener("click",e=>{
    if(activePanel!=="brand") return;
    const b=e.target.closest&&e.target.closest("[data-act]"); if(!b||!lp.contains(b)) return;
    const act=b.dataset.act, k=kit(), i=+b.dataset.i;
    try{
      if(act==="preset"){ const x=KITS[i]; if(x) change("Brand kit: "+x.n,()=>{ k.colors=x.c.slice(); k.heading=x.h; k.body=x.b; if(!k.name) k.name=x.n; }); }
      else if(act==="use"){ if(k.colors[i]) useColor(k.colors[i]); }
      else if(act==="rm"){ change("Remove brand colour",()=>{ k.colors.splice(i,1); }); }
      else if(act==="addc"){
        const v=(document.getElementById("bkPick")||{}).value||"";
        if(!HEX.test(v)){ say("That is not a valid colour"); return; }
        if(k.colors.some(c=>c.toLowerCase()===v.toLowerCase())){ say("That colour is already in your kit"); return; }
        if(k.colors.length>=MAXC){ say("A kit holds up to "+MAXC+" colours — remove one first",3600); return; }
        change("Add brand colour",()=>{ k.colors.push(v.toLowerCase()); });
      }
      else if(act==="fromlogo"){
        const im=getLogo(); if(!im){ say("The logo is still loading — try again in a moment"); return; }
        const p=paletteFrom(im); if(!p.length){ say("No clear colours found in that logo",3600); return; }
        let n=0; change("Colours from logo",()=>{ p.forEach(c=>{ if(k.colors.length<MAXC&&!k.colors.includes(c)){ k.colors.push(c); n++; } }); });
        say(n?n+" colour"+(n===1?"":"s")+" added from the logo":"Those colours are already in your kit");
      }
      else if(act==="font") pickFile(".ttf,.otf,.woff,.woff2",addFont);
      else if(act==="logo") pickFile("image/*",async f=>{ try{ const url=await readImage(f); change("Set brand logo",()=>{ k.logo=url; k.wm.on=true; }); say("Logo added — the watermark is on; change it below"); }catch(err){ say("Could not use that logo: "+((err&&err.message)||err),4500); } });
      else if(act==="rmlogo"){ change("Remove brand logo",()=>{ k.logo=""; k.wm.on=false; }); }
      else if(act==="fonts") applyFonts();
      else if(act==="primary") applyPrimary();
      else if(act==="title") addBrandTitle();
      else if(act==="intro") addCard("intro");
      else if(act==="outro") addCard("outro");
      else if(act==="save") saveDevice();
      else if(act==="load") loadDevice();
      else if(act==="export") exportKit();
      else if(act==="import") pickFile(".json,application/json",importKit);
    }catch(err){ console.error(err); say("That did not work: "+((err&&err.message)||err),4500); }
  });
  lp.addEventListener("change",e=>{
    if(activePanel!=="brand") return; const t=e.target, k=kit();
    try{
      if(t.id==="bkName"){ const v=t.value.trim().slice(0,80); if(v!==k.name) change("Brand name",()=>{ k.name=v; }); }
      else if(t.id==="bkHead"){ change("Heading font",()=>{ k.heading=t.value; }); loadFont(t.value); }
      else if(t.id==="bkBody"){ change("Body font",()=>{ k.body=t.value; }); loadFont(t.value); }
      else if(t.id==="bkWmOn"){ change("Watermark",()=>{ k.wm.on=t.checked; }); }
      else if(t.id==="bkWmPos"){ change("Watermark position",()=>{ k.wm.pos=t.value; }); }
      else if(t.id==="bkWmSize"||t.id==="bkWmOp"){ flush(); renderAll(); }
    }catch(err){ console.error(err); say("That did not work: "+((err&&err.message)||err),4500); }
  });
  lp.addEventListener("input",e=>{
    if(activePanel!=="brand") return; const t=e.target, k=kit();
    if(t.id==="bkWmSize"){ liveEdit("Watermark size",()=>{ k.wm.size=+t.value; }); const l=lp.querySelector('label[for="bkWmSize"]'); if(l) l.textContent="Size "+Math.round(+t.value)+"%"; }
    else if(t.id==="bkWmOp"){ liveEdit("Watermark opacity",()=>{ k.wm.opacity=(+t.value)/100; }); const l=lp.querySelector('label[for="bkWmOp"]'); if(l) l.textContent="Opacity "+Math.round(+t.value)+"%"; }
  });
}
function failPanel(lp,err){
  const msg=String((err&&err.message)||err||"unknown problem");
  try{ console.error("Brand Kit failed:",err); }catch(e){window.__swl&&window.__swl(e)}
  lp.innerHTML='<div class="panel-card" role="alert"><h3 style="margin:0 0 6px;font-size:12px;color:var(--danger)">Brand Kit could not load</h3><div style="font-size:11px;line-height:1.5;color:var(--muted)">'+esc(msg)+'</div><div class="mini-row" style="margin-top:10px"><button type="button" class="chip" id="bkRetry">Try again</button></div></div>';
  const r=lp.querySelector("#bkRetry"); if(r) r.onclick=()=>renderLeftPanel();
  say("Brand Kit could not load — see the panel for details",4000);
}
const prevLP=window.renderLeftPanel;
window.renderLeftPanel=function(){
  if(activePanel!=="brand") return prevLP.apply(this,arguments);
  const lp=document.getElementById("leftPanel"); if(!lp) return;
  try{ render(); }catch(e){ failPanel(lp,e); }
};
window.AMIYO_BRAND={kit:kit,fonts:fontOpts,primary:()=>kit().colors[0]||null,applyFonts:applyFonts};
try{ if(activePanel==="brand") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
})();

