    '<div style="font-size:11px;color:var(--text,inherit);margin-bottom:6px" id="anSum">'+summary(a)+'</div>'+
    '<div style="font-size:11px;font-weight:700;margin:6px 0 4px">One-click looks</div><div class="mini-row" style="flex-wrap:wrap">'+LOOKS.map(function(x,i){ return '<button type="button" class="chip" data-look="'+i+'">'+esc(x[0])+'</button>'; }).join("")+'</div>'+
    '<div style="font-size:11px;font-weight:700;margin:10px 0 4px">Comes in</div><div class="mini-row" style="flex-wrap:wrap">'+chips(INS,"in",a.in,text)+'<button type="button" class="chip" data-k="in" data-v="">None</button></div>'+
    '<div style="font-size:11px;font-weight:700;margin:10px 0 4px">Goes out</div><div class="mini-row" style="flex-wrap:wrap">'+chips(OUTS,"out",a.out,text)+'<button type="button" class="chip" data-k="out" data-v="">None</button></div>'+
    '<div style="font-size:11px;font-weight:700;margin:10px 0 4px">While it is on screen</div><div class="mini-row" style="flex-wrap:wrap">'+chips(LOOPS.filter(function(x){ return !(text&&ROT[x[0]]); }),"loop",a.loop,text)+'<button type="button" class="chip" data-k="loop" data-v="">None</button></div>'+
    '<label class="field" style="margin-top:10px">Entrance length <span id="anDv" style="float:right">'+(a.d||.6)+' s</span></label><input type="range" id="anDur" min="0.2" max="2" step="0.1" value="'+(a.d||.6)+'" aria-label="Entrance length">'+
    '<label class="field" style="margin-top:6px">Exit length <span id="anDov" style="float:right">'+(a.dout||a.d||.6)+' s</span></label><input type="range" id="anDurO" min="0.2" max="2" step="0.1" value="'+(a.dout||a.d||.6)+'" aria-label="Exit length">'+
    '<label style="font-size:11px;display:flex;gap:6px;align-items:center;margin-top:8px"><input type="checkbox" id="anSmooth"'+(a.lin?"":" checked")+'> Smooth easing (starts fast, settles gently)</label>'+
    (userKeys(c)?'<label style="font-size:11px;display:flex;gap:6px;align-items:center;margin-top:8px"><input type="checkbox" id="anRep"'+(st.replace?" checked":"")+'> Replace my keyframes</label><div style="font-size:10.5px;color:var(--muted)">This clip has keyframes you made by hand.</div>':'')+
    '<div class="mini-row" style="margin-top:10px"><button type="button" class="chip" id="anPrev">▶ Preview</button><button type="button" class="chip" id="anClear">Clear animation</button><button type="button" class="chip" id="anKey">＋ Keyframe at playhead</button></div>'+
    (text?'<div style="font-size:10.5px;color:var(--muted);margin-top:6px">Titles also have a Typewriter reveal in the Inspector.</div>':'')+'</div>';
