/* ==================== Script 168 id="amiyo-step59-diagnostics" ==================== */
/* =========================================================================
   AMIYO Editor — Step 6: DIAGNOSTICS — PANELS, RECORDING, STORAGE
   System diagnostics (Help menu, command palette, project settings) gets
   three new sections: a one-tap "Check all panels" run, a recording and
   audio check for the voice-over recorder (mic permission, format,
   audio engine), and storage (used / available, plus a button that asks
   the browser to keep your projects). "Copy report" puts it all on the
   clipboard so a problem can be sent along.
   ========================================================================= */
(function(){
"use strict";
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
function mb(n){ return n>=1024*1024*1024?(n/1073741824).toFixed(1)+" GB":Math.round(n/1048576)+" MB"; }
function row(k,v,bad){ return '<div class="kpi"><span>'+esc(k)+'</span><b'+(bad?' style="color:#ff91a0"':'')+'>'+esc(v)+'</b></div>'; }
function mimeUsed(){ var l=["audio/webm;codecs=opus","audio/webm","audio/mp4","audio/ogg;codecs=opus"]; try{ for(var i=0;i<l.length;i++) if(MediaRecorder.isTypeSupported(l[i])) return l[i]; }catch(e){window.__swl&&window.__swl(e)} return "browser default"; }
async function micState(){
  try{ if(!navigator.permissions||!navigator.permissions.query) return "unknown (asked when you record)"; var r=await navigator.permissions.query({name:"microphone"}); return r.state==="prompt"?"will ask when you record":r.state; }
  catch(e){ return "unknown (asked when you record)"; }
}
async function build(box){
  var recOk=!!(window.MediaRecorder&&navigator.mediaDevices&&navigator.mediaDevices.getUserMedia);
  var ac=(typeof audioContext!=="undefined"&&audioContext)?audioContext.state:"not started yet";
  var mic=await micState(), est=null, persisted=null;
  try{ if(navigator.storage&&navigator.storage.estimate) est=await navigator.storage.estimate(); }catch(e){window.__swl&&window.__swl(e)}
  try{ if(navigator.storage&&navigator.storage.persisted) persisted=await navigator.storage.persisted(); }catch(e){window.__swl&&window.__swl(e)}
  var secure=window.isSecureContext!==false;
  box.innerHTML=
    '<h3 style="margin:14px 0 6px;font-size:13px">Recording and audio</h3><div class="kpi-grid">'+
      row("Voice-over recording",recOk?"Available":"Unavailable",!recOk)+row("Microphone",mic,mic==="denied")+row("Saved format",recOk?mimeUsed():"—")+row("Audio engine",ac)+row("Secure page",secure?"Yes":"No — the microphone needs https or a local file",!secure)+'</div>'+
    '<h3 style="margin:14px 0 6px;font-size:13px">Storage</h3><div class="kpi-grid">'+
      row("Used by projects",est&&est.usage!=null?mb(est.usage):"Unknown")+row("Space available",est&&est.quota!=null?mb(Math.max(0,est.quota-(est.usage||0))):"Unknown")+
      row("Kept by the browser",persisted==null?"Unknown":persisted?"Yes":"Not guaranteed")+'</div>'+
    (persisted===false&&navigator.storage&&navigator.storage.persist?'<button type="button" class="toolbtn" id="dgPersist" style="min-height:44px;margin-top:8px">Ask the browser to keep my projects</button><div id="dgPersistMsg" role="status" style="font-size:11px;color:var(--muted);margin-top:4px"></div>':'')+
    '<h3 style="margin:14px 0 6px;font-size:13px">Panels</h3>'+
    '<button type="button" class="toolbtn" id="dgPanels" style="min-height:44px">Check all panels</button>'+
    '<div id="dgPanelOut" role="status" aria-live="polite" style="font-size:11.5px;line-height:1.7;margin-top:6px"></div>'+
    '<div style="margin-top:12px"><button type="button" class="toolbtn" id="dgCopy" style="min-height:44px">Copy report</button> <span id="dgCopyMsg" role="status" style="font-size:11px;color:var(--muted)"></span></div>';
  var report=[];
  var pb=box.querySelector("#dgPersist"); if(pb) pb.onclick=async function(){ var m=box.querySelector("#dgPersistMsg"); try{ var ok=await navigator.storage.persist(); m.textContent=ok?"Done — the browser will keep your projects.":"The browser did not agree. Installing the editor to your home screen often helps."; }catch(e){ m.textContent="This browser could not do that."; } };
  box.querySelector("#dgPanels").onclick=function(){
    var out=box.querySelector("#dgPanelOut"); out.textContent="Checking…";
    setTimeout(function(){
      var rows; try{ rows=window.amiyoCheckPanels?window.amiyoCheckPanels(true):[]; }catch(e){ out.textContent="The check could not run: "+((e&&e.message)||e); return; }
      var bad=rows.filter(function(r){ return r[1]!=="ok"; }); report=rows;
      out.innerHTML='<b>'+(bad.length?bad.length+" of "+rows.length+" panels have a problem":"All "+rows.length+" panels loaded")+'</b>'+bad.map(function(r){ return '<br>'+esc(r[0])+': <span style="color:#ff91a0">'+esc(r[1])+'</span>'; }).join("");
    },30);
  };
  box.querySelector("#dgCopy").onclick=async function(){
    var body=document.getElementById("modalBody"), lines=["AMIYO Editor report — build "+(window.AMIYO_EDITOR_BUILD||"?"),navigator.userAgent];
    body.querySelectorAll(".kpi").forEach(function(k){ lines.push(k.textContent.replace(/\s+/g," ").trim()); });
    if(report.length) lines.push("Panels: "+report.map(function(r){ return r[0]+"="+r[1]; }).join(", "));
    var m=box.querySelector("#dgCopyMsg");
    try{ await navigator.clipboard.writeText(lines.join("\n")); m.textContent="Copied."; }catch(e){ m.textContent="Copy is blocked here — select the text above instead."; }
  };
}
var prev=window.showDiagnostics;
window.showDiagnostics=function(){
  var r=prev.apply(this,arguments);
  try{
    var body=document.getElementById("modalBody"); if(!body) return r;
    var old=document.getElementById("diagExtra"); if(old) old.remove();
    var box=document.createElement("div"); box.id="diagExtra"; box.innerHTML='<div style="font-size:11px;color:var(--muted);margin-top:12px">Checking recording and storage…</div>'; body.appendChild(box);
    build(box).catch(function(e){ box.innerHTML='<div role="alert" style="font-size:11px;color:#ff91a0;margin-top:12px">The extra checks could not run: '+esc((e&&e.message)||e)+'</div>'; });
  }catch(e){ try{ console.error("Diagnostics extras failed:",e); }catch(x){window.__swl&&window.__swl(x)} }
  return r;
};
})();

