/* ==================== Script 170 id="amiyo-step64-color" ==================== */
/* =========================================================================
   Editor step 64 (round 3, step 4 of 10): Color panel — more sliders, looks, compare, undo
   Before: five sliders, no undo, no looks, and Saturation could not reach true black & white.
   Now: seven sliders (Exposure, Contrast, Saturation, Temperature, Tint, Hue shift, Fade),
   double-click any slider to reset just that one, eight one-click colour looks with a
   Look strength slider, hold-to-compare against the ungraded clip, copy / paste a grade,
   "Apply to every clip on this track", and every drag or click is one undo step.
   Saturation now runs from fully grey (-100) to a strong boost (+100); clips graded earlier
   look exactly the same as before.
   ========================================================================= */
(function(){
"use strict";
var LUM=["lumBrightness","lumContrast","lumSaturation","lumTemp","lumTint","lumHue","lumFade"];
var SL=[
 {k:"exp",label:"Exposure",n:"lumBrightness",min:-100,max:100,d:1,to:function(r){return 1+r/200;},from:function(v){return (v-1)*200;}},
 {k:"con",label:"Contrast",n:"lumContrast",min:-100,max:100,d:1,to:function(r){return 1+r/200;},from:function(v){return (v-1)*200;}},
 {k:"sat",label:"Saturation",n:"lumSaturation",min:-100,max:100,d:1,to:function(r){return r<0?1+r/100:1+r/66.7;},from:function(v){return v<1?(v-1)*100:(v-1)*66.7;}},
 {k:"temp",label:"Temperature",n:"lumTemp",min:-100,max:100,d:0,to:function(r){return r;},from:function(v){return v;}},
 {k:"tint",label:"Tint",n:"lumTint",min:-100,max:100,d:0,to:function(r){return r;},from:function(v){return v;}},
 {k:"hue",label:"Hue shift",n:"lumHue",min:-180,max:180,d:0,to:function(r){return r;},from:function(v){return v;}},
 {k:"fade",label:"Fade (matte)",n:"lumFade",min:0,max:100,d:0,to:function(r){return r/100;},from:function(v){return v*100;}}
];
var LOOKS=[
 {id:"cool",label:"Cool cinema",sw:["#5f341e","#e0a96d"],v:{exp:-5,con:25,sat:5,temp:-30,tint:-6}},
 {id:"golden",label:"Golden hour",sw:["#f6b042","#d9602b"],v:{exp:6,con:10,sat:20,temp:45,tint:6}},
 {id:"moody",label:"Moody blue",sw:["#492a1b","#ec5c14"],v:{exp:-12,con:28,sat:-12,temp:-40}},
 {id:"bw",label:"Black & white",sw:["#111","#eee"],v:{sat:-100,con:25}},
 {id:"faded",label:"Faded film",sw:["#b9a58a","#7e8c8d"],v:{fade:45,sat:-20,temp:18,con:-5}},
 {id:"vivid",label:"Vivid",sw:["#ff3d71","#ff5500"],v:{sat:50,con:20,exp:4}},
 {id:"bleach",label:"Bleach bypass",sw:["#6b6b66","#c9c9c0"],v:{sat:-45,con:45,exp:2}},
 {id:"pastel",label:"Soft pastel",sw:["#f7d6e0","#fad5c3"],v:{exp:12,con:-15,sat:-10,fade:20,tint:10}},
 {id:"tealorange",label:"Teal & orange",sw:["#9d3d0d","#f08a3c"],v:{con:22,sat:18,temp:20,tint:-10}},
 {id:"sunnyday",label:"Sunny day",sw:["#ffe08a","#ffa87c"],v:{exp:10,con:8,sat:28,temp:25}},
 {id:"nightcity",label:"Night city",sw:["#30190e","#ff4fd8"],v:{exp:-15,con:30,sat:20,temp:-25,tint:18}},
 {id:"autumn",label:"Autumn",sw:["#c2561d","#f3b44a"],v:{con:14,sat:25,temp:38,tint:8}},
 {id:"coldblue",label:"Frozen",sw:["#ffd4bf","#a7400d"],v:{exp:6,con:12,sat:-8,temp:-55}},
 {id:"vintagefilm",label:"Vintage film",sw:["#a98b63","#6b7d6a"],v:{fade:55,sat:-25,temp:22,con:-8,tint:6}},
 {id:"punchy",label:"Punchy",sw:["#ff3d3d","#ff732d"],v:{con:38,sat:38,exp:2}},
 {id:"drama",label:"Dark drama",sw:["#0d0d10","#8a2a2a"],v:{exp:-18,con:42,sat:-5,temp:6}},
 {id:"softskin",label:"Soft skin",sw:["#f6d7c3","#ffeedd"],v:{exp:10,con:-12,sat:-6,temp:10,fade:12}},
 {id:"matrix",label:"Green tint",sw:["#0d2b1a","#39ff88"],v:{con:20,sat:-10,temp:-8,tint:-45}},
 {id:"hotpink",label:"Magenta glow",sw:["#7a1f6b","#ff9ad9"],v:{exp:4,sat:22,tint:42,temp:6}},
 {id:"hdr",label:"HDR pop",sw:["#2a9d8f","#e9c46a"],v:{con:30,sat:40,exp:-2}}
];
var grade=null, cmp=null, gest=null, tmr=null, bound=false;
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
function lp(){ return document.getElementById("leftPanel"); }
function selV(){ try{ var f=getClip(); if(f&&f.track.kind==="video") return f; }catch(e){window.__swl&&window.__swl(e)} return null; }
function getRaw(c,s){ var fx=(c.effects||[]).filter(function(x){ return x.name===s.n; })[0]; return fx&&fx.value!=null?Math.round(s.from(fx.value)):0; }
function setLum(c,s,raw){
  c.effects=c.effects||[]; var v=s.to(raw), fx=c.effects.filter(function(x){ return x.name===s.n; })[0];
  if(Math.abs(v-s.d)<.0005){ c.effects=c.effects.filter(function(x){ return x.name!==s.n; }); return; }
  if(!fx){ c.effects.push({id:uid("fx"),name:s.n,value:v,enabled:true}); } else { fx.value=v; fx.enabled=true; }
}
function bySlider(k){ return SL.filter(function(s){ return s.k===k; })[0]; }
function begin(label){ if(!gest) gest={label:label,snap:deepClone(serializableProject())}; }
function commit(){
  clearTimeout(tmr); if(!gest) return; var g=gest; gest=null;
  try{ var after=serializableProject(); if(JSON.stringify(g.snap)!==JSON.stringify(after)) recordHistory(g.label,g.snap,deepClone(after)); }catch(e){window.__swl&&window.__swl(e)}
  try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)}
}
function live(label,fn){
  var f=selV(); if(!f) return; begin(label); fn(f.clip);
  try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)}
  clearTimeout(tmr); tmr=setTimeout(commit,900);
}
function html(f){
  var c=f.clip, cur=c.cgLook||null;
  var rows=SL.map(function(s){ var r=getRaw(c,s);
    return '<div class="color-slider" style="margin-top:6px"><label for="cg_'+s.k+'" style="display:flex;justify-content:space-between;font-size:11px"><span>'+s.label+'</span><output id="cg_'+s.k+'Out">'+r+'</output></label><input type="range" id="cg_'+s.k+'" data-sl="'+s.k+'" min="'+s.min+'" max="'+s.max+'" step="1" value="'+r+'" style="width:100%" title="Double-click to reset"></div>'; }).join("");
  var looks=LOOKS.map(function(l){ return '<button type="button" class="chip" data-cl="'+l.id+'" aria-pressed="'+(cur&&cur.id===l.id)+'" style="display:flex;align-items:center;gap:6px;'+((cur&&cur.id===l.id)?"outline:2px solid var(--accent,#ff7a3d);":"")+'"><span aria-hidden="true" style="width:16px;height:16px;border-radius:50%;flex:none;background:linear-gradient(135deg,'+l.sw[0]+','+l.sw[1]+')"></span>'+esc(l.label)+'</button>'; }).join("");
  return '<div id="cgRoot">'+
    '<div style="font-size:11px;font-weight:700;margin:8px 0 4px">One-click looks</div><div class="mini-row" style="flex-wrap:wrap;gap:6px">'+looks+'</div>'+
    (cur?'<div class="color-slider" style="margin-top:8px"><label for="cgStr" style="display:flex;justify-content:space-between;font-size:11px"><span>Look strength · '+esc((LOOKS.filter(function(l){return l.id===cur.id;})[0]||{}).label||"")+'</span><output id="cgStrOut">'+Math.round(cur.s*100)+'%</output></label><input type="range" id="cgStr" min="0" max="100" step="1" value="'+Math.round(cur.s*100)+'" style="width:100%"></div>':'')+
    '<div style="font-size:11px;font-weight:700;margin:12px 0 0">Adjust</div>'+rows+
    '<div class="mini-row" style="margin-top:10px;flex-wrap:wrap;gap:6px"><button type="button" class="chip" id="cgCmp" title="Press and hold to see the clip without its colour grade">👁 Hold to compare</button><button type="button" class="chip" id="colReset">Reset color</button></div>'+
    '<div class="mini-row" style="margin-top:6px;flex-wrap:wrap;gap:6px"><button type="button" class="chip" id="cgCopy">Copy grade</button><button type="button" class="chip" id="cgPaste"'+(grade?"":" disabled")+'>Paste grade</button><button type="button" class="chip" id="cgAll" title="Copy this grade onto every other video clip on the same track">Apply to track</button></div></div>';
}
function decorate(){
  var el=lp(); if(!el||activePanel!=="color") return;
  var f=selV(); if(!f) return;
  var card=el.querySelector(".panel-card"); if(!card) return;
  card.querySelectorAll(".color-slider").forEach(function(n){ n.remove(); });
  var oldReset=card.querySelector("#colReset"); if(oldReset) oldReset.remove();
  var old=card.querySelector("#cgRoot"); if(old) old.remove();
  card.insertAdjacentHTML("beforeend",html(f));
}
function applyLook(l,s){
  var f=selV(); if(!f) return; var c=f.clip;
  LUM.forEach(function(n){ c.effects=(c.effects||[]).filter(function(x){ return x.name!==n; }); });
  SL.forEach(function(sl){ if(l.v[sl.k]!=null) setLum(c,sl,Math.round(l.v[sl.k]*s)); });
  c.cgLook={id:l.id,s:s};
}
function endCmp(){ if(!cmp) return; var k=cmp; cmp=null; (k.c.effects||[]).forEach(function(x,i){ if(k.m[x.id]!==undefined) x.enabled=k.m[x.id]; }); try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }
function startCmp(){ var f=selV(); if(!f||cmp) return; var m={}; (f.clip.effects||[]).forEach(function(x){ if(LUM.indexOf(x.name)>=0){ m[x.id]=x.enabled; x.enabled=false; } }); cmp={c:f.clip,m:m}; try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }
function bind(){
  var el=lp(); if(!el||bound) return; bound=true;
  el.addEventListener("input",function(e){
    var t=e.target; if(activePanel!=="color"||!t||!t.closest||!t.closest("#cgRoot")) return;
    if(t.dataset.sl){ var s=bySlider(t.dataset.sl); live("Color: "+s.label,function(c){ setLum(c,s,+t.value); c.cgLook=null; }); var o=document.getElementById("cg_"+s.k+"Out"); if(o) o.textContent=t.value; }
    else if(t.id==="cgStr"){ var f=selV(); if(!f||!f.clip.cgLook) return; var l=LOOKS.filter(function(x){ return x.id===f.clip.cgLook.id; })[0]; if(!l) return; live("Look strength",function(c){ applyLook(l,(+t.value)/100); }); var o2=document.getElementById("cgStrOut"); if(o2) o2.textContent=t.value+"%"; }
  });
  el.addEventListener("change",function(e){
    var t=e.target; if(activePanel!=="color"||!t||!t.closest||!t.closest("#cgRoot")) return;
    commit(); if(t.id==="cgStr"||t.dataset.sl){ try{ decorate(); }catch(x){window.__swl&&window.__swl(x)} }
  });
  el.addEventListener("dblclick",function(e){
    var t=e.target; if(activePanel!=="color"||!t||!t.dataset||!t.dataset.sl) return;
    var s=bySlider(t.dataset.sl); live("Reset "+s.label,function(c){ setLum(c,s,0); c.cgLook=null; }); commit(); decorate();
  });
  el.addEventListener("click",function(e){
    if(activePanel!=="color") return; var b=e.target.closest&&e.target.closest("button"); if(!b||!b.closest("#cgRoot")) return;
    try{
      if(b.dataset.cl){ var l=LOOKS.filter(function(x){ return x.id===b.dataset.cl; })[0]; if(l){ commit(); var f=selV(); if(f&&f.clip.cgLook&&f.clip.cgLook.id===l.id){ transact("Remove look",function(){ LUM.forEach(function(n){ f.clip.effects=(f.clip.effects||[]).filter(function(x){ return x.name!==n; }); }); f.clip.cgLook=null; }); } else transact("Colour look: "+l.label,function(){ applyLook(l,1); }); } }
      else if(b.id==="colReset"){ commit(); var f2=selV(); if(f2) transact("Reset color",function(){ LUM.forEach(function(n){ f2.clip.effects=(f2.clip.effects||[]).filter(function(x){ return x.name!==n; }); }); f2.clip.cgLook=null; }); }
      else if(b.id==="cgCopy"){ var f3=selV(); if(f3){ grade=(f3.clip.effects||[]).filter(function(x){ return LUM.indexOf(x.name)>=0; }).map(function(x){ return {name:x.name,value:x.value}; }); try{ notify(grade.length?"Grade copied — select another clip and Paste":"This clip has no colour grade to copy"); }catch(x){window.__swl&&window.__swl(x)} if(!grade.length) grade=null; decorate(); } }
      else if(b.id==="cgPaste"){ var f4=selV(); if(f4&&grade){ commit(); var g=grade; transact("Paste colour grade",function(){ LUM.forEach(function(n){ f4.clip.effects=(f4.clip.effects||[]).filter(function(x){ return x.name!==n; }); }); g.forEach(function(x){ f4.clip.effects.push({id:uid("fx"),name:x.name,value:x.value,enabled:true}); }); f4.clip.cgLook=null; }); } }
      else if(b.id==="cgAll"){ var f5=selV(); if(f5){ commit(); var src=(f5.clip.effects||[]).filter(function(x){ return LUM.indexOf(x.name)>=0; }).map(function(x){ return {name:x.name,value:x.value}; }), look=f5.clip.cgLook?JSON.parse(JSON.stringify(f5.clip.cgLook)):null, n=0;
          transact("Apply grade to track",function(){ f5.track.clips.forEach(function(c){ if(c.id===f5.clip.id||c.kind==="adjustment"||c.kind==="text") return; LUM.forEach(function(nm){ c.effects=(c.effects||[]).filter(function(x){ return x.name!==nm; }); }); src.forEach(function(x){ c.effects.push({id:uid("fx"),name:x.name,value:x.value,enabled:true}); }); c.cgLook=look; n++; }); });
          try{ notify(n?("Grade applied to "+n+" other clip"+(n===1?"":"s")):"No other clips on this track"); }catch(x){window.__swl&&window.__swl(x)} } }
    }catch(err){ if(window.amiyoReportError) window.amiyoReportError("That colour action failed",err,{quiet:true}); }
  });
  el.addEventListener("pointerdown",function(e){ var b=e.target.closest&&e.target.closest("#cgCmp"); if(b) startCmp(); });
  window.addEventListener("pointerup",endCmp); window.addEventListener("pointercancel",endCmp); window.addEventListener("blur",endCmp);
  el.addEventListener("keydown",function(e){ if(e.target&&e.target.id==="cgCmp"&&(e.key===" "||e.key==="Enter")){ e.preventDefault(); startCmp(); } });
  el.addEventListener("keyup",function(e){ if(e.target&&e.target.id==="cgCmp") endCmp(); });
}
var prev=window.renderLeftPanel;
window.renderLeftPanel=function(){
  var r=prev.apply(this,arguments);
  if(activePanel==="color"){ try{ bind(); decorate(); }catch(e){ if(window.amiyoReportError) window.amiyoReportError("The Color panel could not load",e,{quiet:true}); } }
  return r;
};
try{ if(activePanel==="color") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
})();

