/* ==================== Script 171 id="amiyo-step65-mixer2" ==================== */
/* =========================================================================
   Editor step 65 (round 3, step 5 of 10): Audio mixer — master fader, dB readouts, undo, duck speed
   Before: track faders had no undo and no dB readout, Mute / Solo were not undoable, there was no
   master fader (only a master meter), and ducking always reacted at one fixed speed.
   Now: every fader shows % and dB, double-click a fader to reset it to 100% (pan: to centre),
   fader drags, pan, Mute, Solo and the new controls are ONE undo step each, a Master volume
   fader scales everything you hear and everything you export, ducking can be Slow / Normal /
   Fast, and two quick actions: "Reset faders & pans" and "Clear mute / solo".
   ========================================================================= */
(function(){
"use strict";
function lp(){ return document.getElementById("leftPanel"); }
function S(){ return project.settings||(project.settings={}); }
function master(){ var v=S().masterVolume; return (typeof v==="number")?Math.max(0,Math.min(1,v)):1; }
function speed(){ var v=S().duckSpeed; return (typeof v==="number")?Math.max(.03,Math.min(.8,v)):.2; }
window.amiyoMaster=master; window.amiyoDuckSpeed=speed;
function db(v){ return v<=.001?"−∞ dB":(20*Math.log10(v)).toFixed(1).replace("-","−")+" dB"; }
function trackFor(strip){ var id=strip&&strip.dataset.mixtrack; return project.tracks.filter(function(t){ return t.id===id; })[0]||null; }

var gest=null;
function begin(label){ if(!gest) gest={label:label,snap:deepClone(serializableProject())}; }
function commit(){
  if(!gest) return; var g=gest; gest=null;
  try{ var after=serializableProject(); if(JSON.stringify(g.snap)!==JSON.stringify(after)) recordHistory(g.label,g.snap,deepClone(after)); }catch(e){window.__swl&&window.__swl(e)}
  try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)}
}
function snapRecord(label,fn){
  var snap=deepClone(serializableProject()); fn();
  try{ var after=serializableProject(); if(JSON.stringify(snap)!==JSON.stringify(after)) recordHistory(label,snap,deepClone(after)); }catch(e){window.__swl&&window.__swl(e)}
  try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)}
}
function labels(){
  var el=lp(); if(!el) return;
  el.querySelectorAll(".mixer-strip").forEach(function(s){ var t=trackFor(s), l=s.querySelector(".mix-vol-label"); if(t&&l) l.textContent=Math.round((t.volume==null?1:t.volume)*100)+"% · "+db(t.volume==null?1:t.volume); });
}
function section(){
  var m=master(), sp=speed(), cur=sp<.12?"slow":sp>.3?"fast":"normal";
  var chip=function(k,l){ return '<button type="button" class="chip" data-ds="'+k+'" aria-pressed="'+(cur===k)+'" style="'+(cur===k?"outline:2px solid var(--accent,#ff7a3d)":"")+'">'+l+'</button>'; };
  return '<div id="mx2" style="margin-top:12px;border-top:1px solid var(--line);padding-top:8px">'+
   '<label for="mxMaster" style="display:flex;justify-content:space-between;font-size:11px;font-weight:700"><span>Master volume</span><output id="mxMasterOut">'+Math.round(m*100)+'% · '+db(m)+'</output></label>'+
   '<input type="range" id="mxMaster" min="0" max="100" step="1" value="'+Math.round(m*100)+'" style="width:100%;height:30px" title="Double-click to reset to 100%">'+
   '<div style="font-size:11px;font-weight:700;margin:10px 0 4px">Duck speed</div><div class="mini-row" style="gap:6px">'+chip("slow","Slow")+chip("normal","Normal")+chip("fast","Fast")+'</div>'+
   '<div style="font-size:10px;color:var(--muted);margin-top:4px">How quickly ducked tracks dip and recover when someone speaks.</div>'+
   '<div class="mini-row" style="margin-top:10px;gap:6px;flex-wrap:wrap"><button type="button" class="chip" id="mxResetAll">Reset faders &amp; pans</button><button type="button" class="chip" id="mxClearMS">Clear mute / solo</button></div></div>';
}
function decorate(){
  var el=lp(); if(!el||activePanel!=="mixer") return;
  var card=el.querySelector(".panel-card"); if(!card||!el.querySelector(".mixer-strip")) return;
  var old=el.querySelector("#mx2"); if(old) old.remove();
  card.insertAdjacentHTML("beforeend",section()); labels();
}
var bound=false;
function bind(){
  var el=lp(); if(!el||bound) return; bound=true;
  /* capture phase: runs BEFORE the fader's own handler changes the value, so the snapshot is the "before" */
  el.addEventListener("input",function(e){
    var t=e.target; if(activePanel!=="mixer"||!t||!t.classList) return;
    if(t.classList.contains("mix-vol")){ var tr=trackFor(t.closest(".mixer-strip")); begin("Track volume"+(tr?": "+tr.name:"")); }
    else if(t.classList.contains("mix-pan")){ var tp=trackFor(t.closest(".mixer-strip")); begin("Track pan"+(tp?": "+tp.name:"")); }
    else if(t.id==="mxMaster") begin("Master volume");
  },true);
  el.addEventListener("input",function(e){
    var t=e.target; if(activePanel!=="mixer"||!t||!t.classList) return;
    if(t.classList.contains("mix-vol")){ labels(); }
    else if(t.id==="mxMaster"){ var v=(+t.value)/100; S().masterVolume=v; var o=document.getElementById("mxMasterOut"); if(o) o.textContent=Math.round(v*100)+"% · "+db(v); try{ scheduleAutosave(); updateAudioPlayback(); }catch(x){window.__swl&&window.__swl(x)} }
  });
  el.addEventListener("change",function(e){ var t=e.target; if(activePanel==="mixer"&&t&&t.classList&&(t.classList.contains("mix-vol")||t.classList.contains("mix-pan")||t.id==="mxMaster")) commit(); });
  el.addEventListener("click",function(e){
    if(activePanel!=="mixer") return; var b=e.target.closest&&e.target.closest("button"); if(!b) return;
    try{
      if(b.classList.contains("mix-mute")||b.classList.contains("mix-solo")){
        var tr=trackFor(b.closest(".mixer-strip")), kind=b.classList.contains("mix-mute")?"Mute":"Solo", snap=deepClone(serializableProject());
        setTimeout(function(){ try{ var after=serializableProject(); if(JSON.stringify(snap)!==JSON.stringify(after)) recordHistory(kind+(tr?": "+tr.name:""),snap,deepClone(after)); updateUndoRedo(); }catch(x){window.__swl&&window.__swl(x)} },0);
      }else if(b.dataset.ds){ var val={slow:.08,normal:.2,fast:.45}[b.dataset.ds]; snapRecord("Duck speed: "+b.dataset.ds,function(){ S().duckSpeed=val; }); decorate(); }
      else if(b.id==="mxResetAll"){ snapRecord("Reset faders & pans",function(){ project.tracks.forEach(function(t){ if(t.kind==="audio"){ t.volume=1; t.pan=0; } }); }); try{ updateAudioPlayback(); }catch(x){window.__swl&&window.__swl(x)} renderLeftPanel(); }
      else if(b.id==="mxClearMS"){ snapRecord("Clear mute / solo",function(){ project.tracks.forEach(function(t){ if(t.kind==="audio"){ t.muted=false; t.solo=false; } }); }); try{ updateAudioPlayback(); }catch(x){window.__swl&&window.__swl(x)} renderLeftPanel(); }
    }catch(err){ if(window.amiyoReportError) window.amiyoReportError("That mixer action failed",err,{quiet:true}); }
  },true);
  el.addEventListener("dblclick",function(e){
    var t=e.target; if(activePanel!=="mixer"||!t||!t.classList) return;
    try{
      if(t.classList.contains("mix-vol")){ var tr=trackFor(t.closest(".mixer-strip")); if(tr){ snapRecord("Reset volume: "+tr.name,function(){ tr.volume=1; }); updateAudioPlayback(); renderLeftPanel(); } }
      else if(t.classList.contains("mix-pan")){ var tp=trackFor(t.closest(".mixer-strip")); if(tp){ snapRecord("Centre pan: "+tp.name,function(){ tp.pan=0; }); updateAudioPlayback(); renderLeftPanel(); } }
      else if(t.id==="mxMaster"){ snapRecord("Reset master volume",function(){ S().masterVolume=1; }); updateAudioPlayback(); decorate(); }
    }catch(err){window.__swl&&window.__swl(err)}
  });
}
var prev=window.renderLeftPanel;
window.renderLeftPanel=function(){
  var r=prev.apply(this,arguments);
  if(activePanel==="mixer"){ try{ bind(); decorate(); }catch(e){ if(window.amiyoReportError) window.amiyoReportError("The mixer controls could not load",e,{quiet:true}); } }
  return r;
};
try{ if(activePanel==="mixer") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
})();

