/* ==================== Script 172 id="amiyo-step69-trim" ==================== */
(function(){
"use strict";
var bub=null, act=null, raf=0, shown=false, hinted=false, idle=0;
function tc(s){ s=Math.max(0,s||0); var m=Math.floor(s/60), x=s-m*60; return m+":"+(x<10?"0":"")+x.toFixed(2); }
function clipOf(a){ try{ var t=project.tracks.find(function(t){return t.id===a.track;}); return t&&t.clips.find(function(c){return c.id===a.id;}); }catch(e){ return null; } }
function mk(){ if(bub) return bub; bub=document.createElement("div"); bub.id="trimBubble"; bub.setAttribute("aria-hidden","true"); document.body.appendChild(bub); return bub; }
function paint(){
  raf=0; if(!act||!shown) return; var c=clipOf(act); if(!c) return; var b=mk();
  var end=c.start+c.duration, edge=act.side==="left"?"Start "+tc(c.start):"End "+tc(end);
  b.innerHTML=edge+"<small>Length "+c.duration.toFixed(2)+" s</small>";
  var w=b.offsetWidth||120;
  b.style.left=Math.min(Math.max(act.cx,w/2+8),window.innerWidth-w/2-8)+"px";
  b.style.top=Math.max(8,act.cy-(act.touch?84:56))+"px";
}
document.addEventListener("pointerdown",function(e){
  var h=e.target&&e.target.closest?e.target.closest("#tracks .clip .handle[data-resize]"):null; if(!h) return;
  var el=h.closest(".clip");
  act={id:el.dataset.clip,track:el.dataset.track,side:h.dataset.resize,x:e.clientX,cx:e.clientX,cy:e.clientY,touch:e.pointerType==="touch"};
  shown=false;
  if(el.getBoundingClientRect().width<56&&!hinted){ hinted=true; try{ notify("Short clip — zoom the timeline in for easier trimming",3200); }catch(er){window.__swl&&window.__swl(er)} }
},true);
document.addEventListener("pointermove",function(e){
  if(!act) return;
  if(e.pointerType==="mouse"&&e.buttons===0){ end(); return; }   /* the release was never delivered (the clip was redrawn mid-drag) */
  act.cx=e.clientX; act.cy=e.clientY;
  if(!shown){ if(Math.abs(e.clientX-act.x)<4) return; shown=true; document.body.classList.add("trimming"); try{ if(act.touch&&navigator.vibrate) navigator.vibrate(10); }catch(er){window.__swl&&window.__swl(er)} }
  document.body.classList.add("trimming");
  if(e.pointerType==="mouse"){ clearTimeout(idle); idle=setTimeout(function(){ document.body.classList.remove("trimming"); },1500); }   /* safety net: a mouse release that never arrives */
  if(!raf) raf=requestAnimationFrame(paint);
},true);
function end(){ clearTimeout(idle); if(!act) return; act=null; shown=false; document.body.classList.remove("trimming"); }
document.addEventListener("pointerup",end,true);
document.addEventListener("pointercancel",end,true);
window.addEventListener("mouseup",end,true);
window.addEventListener("blur",end);
})();

