/* ==================== Script 173 id="amiyo-editor-s70" ==================== */
/* ===== Editor step 70 (list step 4): long-video preview — lighter, smoother scrubbing =====
   Dragging the ruler (or J/L shuttle) on a long video used to ask for a full-quality, exact frame on every move.
   Now, while scrubbing: preview switches to the light "draft" path, the video jumps with a quick seek (fastSeek where
   the browser has it) and gives up waiting sooner, and one full-quality exact frame is drawn when you let go.
   "Full" quality keeps the old behaviour; exports and saved projects are never affected. */
(function(){
  function qmode(){ try{ return localStorage.getItem("amiyo_editor_preview_quality")||"auto"; }catch(e){ return "auto"; } }
  function scrubbing(){
    if(window.__amiyoExporting||isPlaying) return false;
    var b=document.getElementById("shuttleBadge");
    return !!window.__amiyoScrubbing||!!(b&&b.style.display==="inline-block");
  }
  var origDraft=window.__amiyoDraft;
  if(typeof origDraft==="function") window.__amiyoDraft=function(){
    if(origDraft.apply(this,arguments)) return true;
    return scrubbing()&&qmode()!=="full";
  };
  var origSync=window.amiyoSyncVideo;
  if(typeof origSync==="function") window.amiyoSyncVideo=async function(clip,local,seek){
    if(!scrubbing()||qmode()==="full") return origSync.apply(this,arguments);
    var v=videoEl; if(!v.paused) v.pause();
    var t=clamp(seek,0,v.duration||seek);
    if(Math.abs(v.currentTime-t)<.04) return;
    if(typeof v.fastSeek==="function"){ try{ v.fastSeek(t); }catch(e){ v.currentTime=t; } } else v.currentTime=t;
    await amiyoSeeked(v,120);
  };
  function settle(){ window.__amiyoScrubbing=false; try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }
  var ruler=document.getElementById("ruler");
  if(ruler){
    ruler.addEventListener("pointerdown",function(e){ if(e.button===undefined||e.button===0) window.__amiyoScrubbing=true; },true);
    window.addEventListener("pointerup",function(){ if(window.__amiyoScrubbing) settle(); },true);
    window.addEventListener("pointercancel",function(){ if(window.__amiyoScrubbing) settle(); },true);
  }
  var badge=document.getElementById("shuttleBadge");
  if(badge&&window.MutationObserver) new MutationObserver(function(){ if(badge.style.display==="none"&&!isPlaying) settle(); }).observe(badge,{attributes:true,attributeFilter:["style"]});
})();

;
/* ==================== Script 174 id="amiyo-editor-s71" ==================== */
/* ===== Editor step 71 (list step 7): Media panel — sorting, type filter, tags, search that reads tags =====
   Before: the Media tab had bins and a name search only. Now: Sort (added, newest, name, longest, type), a
   type filter, tags you can add to any item (🏷 button; comma separated), tag chips to filter by, and the
   search box also matches tags. Tags are saved with the project and each change is one undo step. */
(function(){
  "use strict";
  var st={sort:"added",type:"all",tag:"",q:"",fav:false,unused:false,selMode:false,sel:{}};
  /* step 86: remember the sort choice between visits (filters are not remembered, so media never looks missing) */
  try{ var _sv=JSON.parse(localStorage.getItem("amiyo.editor.media.view.v1")||"{}"); if(["added","newest","name","namez","long","type","size","fav","used","unused"].indexOf(_sv.sort)>=0) st.sort=_sv.sort; }catch(e){window.__swl&&window.__swl(e)}
  function saveView(){ try{ localStorage.setItem("amiyo.editor.media.view.v1",JSON.stringify({sort:st.sort})); }catch(e){window.__swl&&window.__swl(e)} }
  var HIDE=["voice-over","background","sfx","music"];   /* tags the editor adds itself stay out of the chip row */
  function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(m){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m];}); }
  function css(){
    if(document.getElementById("md-css")) return;
    var s=document.createElement("style"); s.id="md-css";
    s.textContent=".md-bar{display:flex;flex-direction:column;gap:6px;margin-top:8px}.md-row{display:flex;gap:6px;flex-wrap:wrap;align-items:center}"+
    ".md-bar select{width:auto;min-height:34px;padding:4px 8px;font-size:12px}.md-bar .chip.on{border-color:var(--accent);background:#2a1a10;color:#fff}"+
    ".md-tags{display:block;margin-top:2px;font-size:9.5px;color:#d9a36f;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}"+
    ".md-tagbtn{position:absolute;left:5px;top:5px;width:30px;height:30px;border-radius:99px;border:0;background:rgba(10,9,8,.8);color:#fff;font-size:14px;line-height:1;display:grid;place-items:center;cursor:pointer}"+
    ".md-tagbtn:hover{background:var(--accent);color:#1a0c03}.md-none{grid-column:1/-1;color:var(--muted);font-size:11px;padding:10px}"+
    ".md-used{display:block;font-size:9.5px;margin-top:2px;color:var(--muted)}"+
    "@media (pointer:coarse){.md-tagbtn{width:40px;height:40px;font-size:18px}.md-bar select,.md-bar .chip{min-height:40px}}";
    document.head.appendChild(s);
  }
  function userTags(a){ return (a.tags||[]).filter(function(t){ return HIDE.indexOf(t)<0; }); }
  function allTags(){ var m={}; Object.values(project.assets).forEach(function(a){ userTags(a).forEach(function(t){ m[t]=(m[t]||0)+1; }); }); return Object.keys(m).sort(); }
  function setTags(id,list){
    var a=project.assets[id]; if(!a) return;
    var before=deepClone(serializableProject()), keep=(a.tags||[]).filter(function(t){ return HIDE.indexOf(t)>=0; });
    a.tags=keep.concat(list);
    recordHistory("Edit media tags",before,serializableProject()); scheduleAutosave();
    try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)} renderLeftPanel();
  }
  function ask(id){
    var a=project.assets[id]; if(!a) return;
    Promise.resolve(window.amiyoAsk("Tags for “"+a.name+"” (comma separated, empty clears)"+(allTags().length?"\nYour tags: "+allTags().slice(0,20).join(", "):""),userTags(a).join(", "),{okLabel:"Save"})).then(function(v){
      if(v==null) return;
      var seen={}, list=String(v).split(",").map(function(t){ return t.trim().toLowerCase().replace(/\s+/g," ").slice(0,24); }).filter(function(t){ if(!t||seen[t]) return false; seen[t]=1; return true; }).slice(0,12);
      setTags(id,list);
    });
  }
  function css2(){
    if(document.getElementById("md-css2")) return;
    var s=document.createElement("style"); s.id="md-css2";
    s.textContent=".md-favbtn{top:auto!important;bottom:5px;left:5px}.md-renbtn{top:auto!important;left:auto!important;bottom:5px;right:5px}.md-favbtn[aria-pressed=true]{color:#ffc857}.asset.md-sel{outline:2px solid var(--accent);outline-offset:-2px}.asset.md-sel .thumb::after{content:\"✓\";position:absolute;right:6px;top:6px;width:24px;height:24px;border-radius:99px;background:var(--accent);color:#1a0c03;font-weight:700;display:grid;place-items:center;z-index:3}.md-selbar{align-items:center}.md-selbar span{font-size:11px;color:var(--muted);flex:1 1 100%}";
    document.head.appendChild(s);
  }
  function toggleFav(id){
    var a=project.assets[id]; if(!a) return;
    var before=deepClone(serializableProject()); a.favorite=!a.favorite;
    recordHistory(a.favorite?"Favorite media":"Unfavorite media",before,serializableProject()); scheduleAutosave();
    try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)} renderLeftPanel();
    try{ document.getElementById("a11yLive").textContent=a.name+(a.favorite?" added to favorites":" removed from favorites"); }catch(e){window.__swl&&window.__swl(e)}
  }
  function renameAsset(id){
    var a=project.assets[id]; if(!a) return;
    Promise.resolve(window.amiyoAsk("Rename “"+a.name+"”",a.name,{okLabel:"Rename"})).then(function(v){
      if(v==null) return; v=String(v).trim().slice(0,80); if(!v||v===a.name) return;
      var before=deepClone(serializableProject()); a.name=v;
      recordHistory("Rename media",before,serializableProject()); scheduleAutosave();
      try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)} renderAll();
    });
  }
  function bulk(act,lp,grid,paint){
    var ids=Object.keys(st.sel).filter(function(k){ return project.assets[k]; });
    if(act==="all"){ grid.querySelectorAll(".asset").forEach(function(el){ if(el.style.display!=="none") st.sel[el.dataset.asset]=1; }); paint(); return; }
    if(act==="none"){ st.sel={}; paint(); return; }
    if(!ids.length){ window.notify&&window.notify("Select some media first"); return; }
    if(act==="fav"){
      var allFav=ids.every(function(k){ return project.assets[k].favorite; }), before=deepClone(serializableProject());
      ids.forEach(function(k){ project.assets[k].favorite=!allFav; });
      recordHistory(allFav?"Unfavorite media":"Favorite media",before,serializableProject()); scheduleAutosave(); try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)} renderLeftPanel(); return;
    }
    if(act==="tag"){
      Promise.resolve(window.amiyoAsk("Add tags to "+ids.length+" item"+(ids.length===1?"":"s")+" (comma separated)","",{okLabel:"Add"})).then(function(v){
        if(v==null) return; var add=String(v).split(",").map(function(t){ return t.trim().toLowerCase().replace(/\s+/g," ").slice(0,24); }).filter(Boolean);
        if(!add.length) return; var before=deepClone(serializableProject());
        ids.forEach(function(k){ var a=project.assets[k], cur=a.tags||[]; add.forEach(function(t){ if(cur.indexOf(t)<0) cur.push(t); }); a.tags=cur; });
        recordHistory("Tag media",before,serializableProject()); scheduleAutosave(); try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)} renderLeftPanel();
      });
      return;
    }
    if(act==="del"){
      var used={}; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.assetId) used[c.assetId]=1; }); });
      var del=ids.filter(function(k){ return !used[k]; }), skip=ids.length-del.length;
      if(!del.length){ window.notify&&window.notify("Those items are used on the timeline, so they were kept"); return; }
      Promise.resolve(window.amiyoOk("Remove "+del.length+" unused item"+(del.length===1?"":"s")+" from this project?"+(skip?" ("+skip+" used on the timeline will be kept.)":""),{okLabel:"Remove",danger:true})).then(function(ok){
        if(!ok) return; var before=deepClone(serializableProject());
        del.forEach(function(k){ delete project.assets[k]; delete st.sel[k]; });
        recordHistory("Remove media",before,serializableProject()); scheduleAutosave(); try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)} renderAll();
        window.notify&&window.notify(del.length+" item"+(del.length===1?"":"s")+" removed");
      });
    }
  }
  /* several words must all match; "#tag" matches tags that start with it */
  function matchQ(q,hay,tags){ if(!q) return true; return q.split(/\s+/).every(function(w){ if(!w) return true; if(w.charAt(0)==="#"){ var t=w.slice(1); return !t||tags.some(function(x){ return x.indexOf(t)===0; }); } return hay.indexOf(w)>=0; }); }
  function nameOf(el){ var a=project.assets[el.dataset.asset]; return a||{}; }
  function apply(lp){
    var grid=lp.querySelector(".asset-grid"); if(!grid) return;
    var els=[].slice.call(grid.querySelectorAll(".asset")), q=st.q.trim().toLowerCase();
    var uses={}; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.assetId) uses[c.assetId]=(uses[c.assetId]||0)+1; }); });
    var order=els.map(function(e,i){ return {e:e,i:i,a:nameOf(e)}; });
    order.sort(function(x,y){
      if(st.sort==="newest") return y.i-x.i;
      if(st.sort==="namez") return String(y.a.name||"").localeCompare(String(x.a.name||""),undefined,{numeric:true,sensitivity:"base"})||x.i-y.i;
      if(st.sort==="used") return (uses[y.a.id]||0)-(uses[x.a.id]||0)||x.i-y.i;
      if(st.sort==="unused") return (uses[x.a.id]?1:0)-(uses[y.a.id]?1:0)||x.i-y.i;
      if(st.sort==="name") return String(x.a.name||"").localeCompare(String(y.a.name||""),undefined,{numeric:true,sensitivity:"base"})||x.i-y.i;
      if(st.sort==="long") return (y.a.duration||0)-(x.a.duration||0)||x.i-y.i;
      if(st.sort==="type") return String(x.a.type||"").localeCompare(String(y.a.type||""))||x.i-y.i;
      if(st.sort==="size") return (y.a.size||0)-(x.a.size||0)||x.i-y.i;
      if(st.sort==="fav") return (y.a.favorite?1:0)-(x.a.favorite?1:0)||x.i-y.i;
      return x.i-y.i;
    });
    var shown=0;
    order.forEach(function(o){
      grid.appendChild(o.e);
      var a=o.a, tags=userTags(a), hay=((a.name||"")+" "+a.type+" "+(a.tags||[]).join(" ")).toLowerCase();
      var ok=(st.type==="all"||a.type===st.type)&&(!st.fav||a.favorite)&&(!st.tag||tags.indexOf(st.tag)>=0)&&(!st.unused||!uses[a.id])&&matchQ(q,hay,a.tags||[]);
      o.e.style.display=ok?"":"none"; if(ok) shown++;
      var mt=o.e.querySelector(".asset-meta"); if(mt){ var us=mt.querySelector(".md-used"); if(!us){ us=document.createElement("span"); us.className="md-used"; mt.appendChild(us); } us.textContent=uses[a.id]?"used "+uses[a.id]+"x on timeline":"unused"; }
    });
    var cEl=lp.querySelector("#mdCount"); if(cEl) cEl.textContent="Showing "+shown+" of "+els.length;
    var filt=st.type!=="all"||st.fav||st.unused||!!st.tag||!!q, clr=lp.querySelector("#mdClear"); if(clr) clr.classList.toggle("hidden",!filt);
    saveView();
    var none=grid.querySelector(".md-none"); if(none) none.remove();
    if(els.length&&!shown){ var d=document.createElement("div"); d.className="md-none"; d.textContent="No media matches. Clear the search or filters to see everything."; grid.appendChild(d); }
  }
  function inject(){
    if(activePanel!=="media") return;
    var lp=document.getElementById("leftPanel"); if(!lp||lp.querySelector(".md-bar")) return;
    var card=lp.querySelector(".panel-card"), grid=lp.querySelector(".asset-grid"); if(!card||!grid) return;
    css(); css2();
    var tags=allTags(); if(st.tag&&tags.indexOf(st.tag)<0) st.tag="";
    var bar=document.createElement("div"); bar.className="md-bar";
    bar.innerHTML='<div class="md-row"><label class="sr-only" for="mdSort">Sort media</label><select id="mdSort" aria-label="Sort media">'+
      [["added","Sort: Added"],["newest","Sort: Newest first"],["name","Sort: Name A–Z"],["long","Sort: Longest first"],["type","Sort: Type"],["size","Sort: Largest first"],["fav","Sort: Favorites first"],["namez","Sort: Name Z-A"],["used","Sort: Most used"],["unused","Sort: Unused first"]].map(function(o){ return '<option value="'+o[0]+'"'+(st.sort===o[0]?" selected":"")+'>'+o[1]+'</option>'; }).join("")+'</select>'+
      [["all","All"],["video","Video"],["audio","Audio"],["image","Images"],["fav","★ Favorites"],["unused","Unused"]].map(function(o){ var on=o[0]==="fav"?st.fav:o[0]==="unused"?st.unused:st.type===o[0]; return '<button type="button" class="chip'+(on?" on":"")+'" data-mdtype="'+o[0]+'" aria-pressed="'+on+'">'+o[1]+'</button>'; }).join("")+'</div>'+
      (tags.length?'<div class="md-row" role="group" aria-label="Filter by tag">'+tags.map(function(t){ return '<button type="button" class="chip'+(st.tag===t?" on":"")+'" data-mdtag="'+esc(t)+'" aria-pressed="'+(st.tag===t)+'">#'+esc(t)+'</button>'; }).join("")+'</div>':'');
    card.appendChild(bar);
    bar.insertAdjacentHTML("beforeend",'<div class="md-row"><span id="mdCount" role="status" aria-live="polite" style="font-size:10.5px;color:var(--muted)"></span><button type="button" class="chip hidden" id="mdClear">Clear filters</button></div>');
    Object.keys(st.sel).forEach(function(k){ if(!project.assets[k]) delete st.sel[k]; });
    bar.insertAdjacentHTML("beforeend",'<div class="md-row"><button type="button" class="chip'+(st.selMode?" on":"")+'" id="mdSelMode" aria-pressed="'+st.selMode+'">☑ Select several</button></div>'+
      (st.selMode?'<div class="md-row md-selbar" role="group" aria-label="Actions for selected media"><span id="mdSelCount" role="status" aria-live="polite"></span><button type="button" class="chip" data-mdact="all">All shown</button><button type="button" class="chip" data-mdact="none">None</button><button type="button" class="chip" data-mdact="tag">🏷 Add tags</button><button type="button" class="chip" data-mdact="fav">★ Favorite</button><button type="button" class="chip" data-mdact="del" style="color:#ff91a0">Delete</button></div>':''));
    bar.querySelector("#mdSelMode").onclick=function(){ st.selMode=!st.selMode; if(!st.selMode) st.sel={}; renderLeftPanel(); };
    if(st.selMode){
      var paint=function(){ var n=Object.keys(st.sel).length; var c=lp.querySelector("#mdSelCount"); if(c) c.textContent=n+(n===1?" item selected":" items selected")+" — tap items to select";
        grid.querySelectorAll(".asset").forEach(function(el){ el.classList.toggle("md-sel",!!st.sel[el.dataset.asset]); }); };
      paint();
      var swallow=function(e){ if(e.target.closest("button")) return; var el=e.target.closest(".asset"); if(!el) return; e.stopPropagation(); e.preventDefault();
        if(e.type==="click"){ var id=el.dataset.asset; if(st.sel[id]) delete st.sel[id]; else st.sel[id]=1; paint(); } };
      grid.addEventListener("click",swallow,true); grid.addEventListener("dblclick",swallow,true);
      bar.querySelector(".md-selbar").addEventListener("click",function(e){ var b=e.target.closest("[data-mdact]"); if(!b) return; bulk(b.dataset.mdact,lp,grid,paint); });
    }
    var s=lp.querySelector("#mediaSearch");
    if(s){ var n=s.cloneNode(true); n.value=st.q; s.parentNode.replaceChild(n,s); n.placeholder="Search words or #tag…"; n.addEventListener("input",function(){ st.q=n.value; apply(lp); }); }
    bar.querySelector("#mdSort").onchange=function(e){ st.sort=e.target.value; apply(lp); };
    bar.querySelector("#mdClear").onclick=function(){ st.type="all"; st.fav=false; st.unused=false; st.tag=""; st.q=""; renderLeftPanel(); };
    bar.querySelectorAll("[data-mdtype]").forEach(function(b){ b.onclick=function(){ if(b.dataset.mdtype==="fav") st.fav=!st.fav; else if(b.dataset.mdtype==="unused") st.unused=!st.unused; else st.type=b.dataset.mdtype; renderLeftPanel(); }; });
    bar.querySelectorAll("[data-mdtag]").forEach(function(b){ b.onclick=function(){ st.tag=(st.tag===b.dataset.mdtag)?"":b.dataset.mdtag; renderLeftPanel(); }; });
    grid.querySelectorAll(".asset").forEach(function(el){
      var a=project.assets[el.dataset.asset]; if(!a) return;
      var th=el.querySelector(".thumb"), meta=el.querySelector(".asset-meta"), t=userTags(a);
      if(th&&!th.querySelector(".md-tagbtn")){
        var b=document.createElement("button"); b.type="button"; b.className="md-tagbtn"; b.textContent="🏷"; b.title="Edit tags"; b.setAttribute("aria-label","Edit tags for "+a.name);
        b.addEventListener("click",function(ev){ ev.stopPropagation(); ev.preventDefault(); ask(a.id); }); th.appendChild(b);
      }
      if(th&&!th.querySelector(".md-favbtn")){
        var fb=document.createElement("button"); fb.type="button"; fb.className="md-tagbtn md-favbtn"; fb.textContent=a.favorite?"★":"☆"; fb.setAttribute("aria-pressed",!!a.favorite);
        fb.title=a.favorite?"Remove from favorites":"Add to favorites"; fb.setAttribute("aria-label",(a.favorite?"Remove from favorites: ":"Add to favorites: ")+a.name);
        fb.addEventListener("click",function(ev){ ev.stopPropagation(); ev.preventDefault(); toggleFav(a.id); }); th.appendChild(fb);
        var rb=document.createElement("button"); rb.type="button"; rb.className="md-tagbtn md-renbtn"; rb.textContent="✎"; rb.title="Rename"; rb.setAttribute("aria-label","Rename "+a.name);
        rb.addEventListener("click",function(ev){ ev.stopPropagation(); ev.preventDefault(); renameAsset(a.id); }); th.appendChild(rb);
      }
      if(meta&&t.length){ var sp=document.createElement("span"); sp.className="md-tags"; sp.textContent=t.map(function(x){ return "#"+x; }).join(" "); meta.appendChild(sp); }
    });
    apply(lp);
  }
  var prev=window.bindLeftPanel;
  window.bindLeftPanel=function(){ var r=prev.apply(this,arguments); try{ inject(); }catch(e){ try{ console.warn("Media tools",e); }catch(_){window.__swl&&window.__swl(_)} } return r; };
  try{ if(activePanel==="media") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
})();

