/* ==================== Script 175 id="amiyo-editor-s72" ==================== */
/* ===== Editor step 72 (list step 8): Inspector — grouped, collapsible sections =====
   The Inspector grew into one long scroll of 10+ boxes. Now related sections sit next to each other (timing, speed,
   transform, audio, text, then advanced ones), each has a ▾ button to fold it away, advanced sections start folded,
   "Expand all / Collapse all" appears when there are many, and your choices are remembered between clips and visits. */
(function(){
  "use strict";
  var KEY="amiyo_editor_inspector_fold", fold={};
  try{ fold=JSON.parse(localStorage.getItem(KEY)||"{}")||{}; }catch(e){ fold={}; }
  var RANK=[["Timing",1],["Speed / Duration",2],["Transform",3],["Text",3],["Audio",3],["Title Style",4],["Fades",4],["Crop",5],["Keyframes",6],["Blend Mode",7],["Chroma Key",8],["Effects",9],["Quick actions",99]];
  var OPEN={"Timing":1,"Speed / Duration":1,"Transform":1,"Text":1,"Audio":1,"Title Style":1,"Quick actions":1};
  function css(){
    if(document.getElementById("ins-css")) return;
    var s=document.createElement("style"); s.id="ins-css";
    s.textContent=".ins-chev{display:inline-grid;place-items:center;width:22px;height:22px;margin:-3px 4px -3px -4px;border:0;border-radius:6px;background:transparent;color:var(--muted);font-size:12px;cursor:pointer;transition:transform .15s}"+
    ".ins-chev:hover{background:var(--panel3);color:#fff}.group.ins-fold>.ins-chev-h~*{display:none!important}.group.ins-fold>h3{margin-bottom:0}.group.ins-fold .ins-chev{transform:rotate(-90deg)}"+
    ".inspector h3.ins-h{cursor:pointer;user-select:none;-webkit-user-select:none}.ins-all{display:flex;gap:6px;padding:8px 13px;border-bottom:1px solid var(--line)}.ins-all .chip{min-height:30px;padding:4px 10px}"+
    "@media (pointer:coarse){.ins-chev{width:36px;height:36px;margin:-8px 2px -8px -8px;font-size:15px}.ins-all .chip{min-height:40px}}";
    document.head.appendChild(s);
  }
  function titleOf(h){ var t=""; for(var n=h.firstChild;n;n=n.nextSibling){ if(n.nodeType===3) t+=n.nodeValue; else if(n.nodeType===1&&n.tagName==="SPAN"&&!n.classList.contains("badge")) t+=n.textContent; } return t.replace(/\s+/g," ").trim()||h.textContent.replace(/\s+/g," ").trim(); }
  function keyFor(t){ for(var i=0;i<RANK.length;i++) if(t.indexOf(RANK[i][0])===0) return RANK[i][0]; return t.split("—")[0].trim(); }
  function rankFor(t){ for(var i=0;i<RANK.length;i++) if(t.indexOf(RANK[i][0])===0) return RANK[i][1]; return 50; }
  function isFolded(k){ return k in fold?!!fold[k]:!OPEN[k]; }
  function save(){ try{ localStorage.setItem(KEY,JSON.stringify(fold)); }catch(e){window.__swl&&window.__swl(e)} }
  function setFold(g,k,on){ g.classList.toggle("ins-fold",on); var b=g.querySelector(".ins-chev"); if(b){ b.setAttribute("aria-expanded",String(!on)); b.setAttribute("aria-label",(on?"Expand ":"Collapse ")+k); } }
  function build(){
    var insp=document.getElementById("inspector"); if(!insp||insp.querySelector(".inspector-empty")) return;
    css();
    var groups=[].slice.call(insp.children).filter(function(g){ return g.classList&&g.classList.contains("group")&&g.querySelector("h3"); });
    if(groups.length<2) return;
    var head=groups[0], rest=groups.slice(1).map(function(g,i){ var h=g.querySelector("h3"), t=titleOf(h); return {g:g,i:i,h:h,t:t,k:keyFor(t),r:rankFor(t)}; });
    rest.sort(function(a,b){ return a.r-b.r||a.i-b.i; });
    var anchor=head.nextSibling;
    rest.forEach(function(x){ insp.insertBefore(x.g,anchor); });   /* moves the existing boxes: their handlers stay attached */
    rest.forEach(function(x){
      var h=x.h; h.classList.add("ins-h","ins-chev-h");
      var b=document.createElement("button"); b.type="button"; b.className="ins-chev"; b.textContent="▾";
      h.insertBefore(b,h.firstChild);
      /* the heading itself must be the first child of its group for the CSS sibling rule */
      x.g.insertBefore(b,x.g.firstChild); b.className="ins-chev ins-chev-h"; x.g.insertBefore(h,b.nextSibling);
      setFold(x.g,x.k,isFolded(x.k));
      var go=function(){ var on=!x.g.classList.contains("ins-fold"); fold[x.k]=on; save(); setFold(x.g,x.k,on); };
      b.addEventListener("click",function(e){ e.stopPropagation(); go(); });
      h.addEventListener("click",function(e){ if(e.target.closest("input,label,button,select,a")) return; go(); });
    });
    if(rest.length>=4&&!insp.querySelector(".ins-all")){
      var bar=document.createElement("div"); bar.className="ins-all";
      bar.innerHTML='<button type="button" class="chip" data-all="0">Expand all</button><button type="button" class="chip" data-all="1">Collapse all</button>';
      insp.insertBefore(bar,head.nextSibling);
      bar.addEventListener("click",function(e){ var b=e.target.closest("[data-all]"); if(!b) return; var on=b.dataset.all==="1";
        rest.forEach(function(x){ fold[x.k]=on; setFold(x.g,x.k,on); }); save(); });
    }
  }
  var prev=window.renderInspector;
  window.renderInspector=function(){ var r=prev.apply(this,arguments); try{ build(); }catch(e){ try{ console.warn("Inspector groups",e); }catch(_){window.__swl&&window.__swl(_)} } return r; };
  try{ renderInspector(); }catch(e){window.__swl&&window.__swl(e)}
})();

