  try{ on=localStorage.getItem(KEY)!=="0"; }catch(e){window.__swl&&window.__swl(e)}
  function $(id){ return document.getElementById(id); }
  function say(m,t){ try{ notify(m,t||3600); }catch(e){window.__swl&&window.__swl(e)} }
