    ["pointerdown","mousedown","touchstart"].forEach(function(t){ document.addEventListener(t,press,true); });
    ["pointerup","mouseup","touchend","pointercancel","touchcancel","dragend"].forEach(function(t){ document.addEventListener(t,release,true); });
    window.addEventListener("blur",release); document.addEventListener("visibilitychange",release);
    window.renderInspector=function(){
      var now=performance.now();
      if(!down||now-last>=GAP){ if(pend){ clearTimeout(pend); pend=0; } last=now; return ri.apply(this,arguments); }
      if(!pend) pend=setTimeout(function(){ pend=0; last=performance.now(); try{ ri(); }catch(e){window.__swl&&window.__swl(e)} },GAP-(now-last));
    };
