/* ==================== Script 181 id="amiyo-seek-while-playing" ==================== */
/* Step 93: moving the playhead while the video is playing now works.
   Playback used to compute the time from where you pressed Play plus the time since, so any jump (dragging the playhead,
   tapping the ruler, Frame buttons, markers) was overwritten on the very next frame and the line snapped back.
   Now playback notices the jump and carries on from the new spot. It also stops at the end of your clips instead of
   running on through empty timeline to the 30 s minimum (unless you start from past the end, or Loop is on). */
(function(){
  "use strict";
  function limitFor(t){
    var ce=window.amiyoContentEnd?window.amiyoContentEnd():0, d=getProjectDuration();
    return (ce>0&&t<ce)?ce:d;
  }
  window.play=function(){
    if(isPlaying) return;
    isPlaying=true;
    var pb=document.getElementById("playBtn"); if(pb) pb.textContent="❚❚ Pause";
    var origin=currentTime, started=performance.now(), expect=currentTime, lim=limitFor(currentTime);
    var tick=async function(now){
      if(!isPlaying) return;
      if(Math.abs(currentTime-expect)>0.0005){ origin=currentTime; started=now; lim=limitFor(currentTime); }
      currentTime=origin+(now-started)/1000;
      if(currentTime>=lim){
        if(project.settings.loop){
          currentTime=0; origin=0; started=now; expect=0; lim=limitFor(0);
        } else {
          currentTime=lim; pause();
          try{ updateTimeUI(); renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)}
          return;
        }
      }
      expect=currentTime;
      try{ updateTimeUI(); await renderPreviewFrame(); await updateAudioPlayback(); renderMarkerStrip(); }catch(e){ try{ console.warn("Playback frame",e); }catch(_){window.__swl&&window.__swl(_)} }
      if(isPlaying) renderRAF=requestAnimationFrame(tick);
    };
    renderRAF=requestAnimationFrame(tick);
  };
})();

