/* ==================== Script 183 id="amiyo-no-overlap" ==================== */
/* Step 96: clips on the same video or audio track no longer pile on top of each other.
   - Dropping a clip onto its neighbour moves it to the nearest free spot (just before or just after).
   - Clips added by any route (import, library, director) that would land on top of another are moved after it.
   - Overlaps made on purpose by a transition are left alone; text, caption and graphic tracks can still stack.
   Also: the "couldn't store thumbnail" message is not shown when this page can't store anything at all (opened from a file). */
(function(){
  "use strict";
  window.__noStoreCache=!!window.__amiyoMemStorage;
  function allowed(a,b){ return ((b.transitionIn&&b.transitionIn.duration)||0)+((a.transitionOut&&a.transitionOut.duration)||0)+0.06; }
  function spot(others,clip){
    var d=clip.duration, want=clip.start;
    function free(s){ return s>=0&&others.every(function(o){ return s+d<=o.start+0.001||s>=o.start+o.duration-0.001; }); }
    var c=[want]; others.forEach(function(o){ c.push(o.start+o.duration,o.start-d); });
    c=c.filter(free); if(!c.length) return null;
    c.sort(function(a,b){ return Math.abs(a-want)-Math.abs(b-want); }); return c[0];
  }
  function tidy(){
    var moved=0;
    try{ if(project.tracks.some(function(t){ return t.clips.filter(function(c){ return c.selected; }).length>1; })) return 0; }catch(e){window.__swl&&window.__swl(e)}
    project.tracks.forEach(function(t){
      if((t.kind!=="video"&&t.kind!=="audio")||t.locked) return;
      for(var pass=0;pass<t.clips.length+2;pass++){
        var cs=t.clips.slice().sort(function(a,b){ return a.start-b.start; }), bad=null;
        for(var i=1;i<cs.length&&!bad;i++) for(var j=0;j<i&&!bad;j++){
          if((cs[j].start+cs[j].duration)-cs[i].start>allowed(cs[j],cs[i])) bad={a:cs[j],b:cs[i]};
        }
        if(!bad) break;
        var v=(typeof selectedClipId!=="undefined"&&selectedClipId===bad.a.id)?bad.a:bad.b;
        var s=spot(t.clips.filter(function(c){ return c!==v; }),v);
        if(s==null) break;
        v.start=Math.round(s*1000)/1000; moved++;
      }
      t.clips.sort(function(a,b){ return a.start-b.start; });
    });
    return moved;
  }
  var busy=false;
  function run(msg){
    if(busy) return; busy=true;
    try{
      var n=tidy();
      if(n){ renderTracks(); try{ updateTimeUI(); }catch(e){window.__swl&&window.__swl(e)} try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} try{ toast(msg||"Moved to the nearest free spot so clips don't overlap"); }catch(e){window.__swl&&window.__swl(e)} }
    }catch(e){ try{ console.warn("Overlap check",e); }catch(_){window.__swl&&window.__swl(_)} }
    busy=false;
  }
  /* 1) after you drop a clip you dragged */
  var drag=false;
  var ts=document.getElementById("timelineScroll");
  if(ts) ts.addEventListener("pointerdown",function(e){ drag=!!(e.target.closest&&e.target.closest(".clip"))&&!e.target.closest(".handle"); },true);
  window.addEventListener("pointerup",function(){ if(drag){ drag=false; run(); } },true);
  window.addEventListener("pointercancel",function(){ drag=false; },true);
  /* 2) after clips are added by any route */
  function count(){ var n=0; try{ project.tracks.forEach(function(t){ if(t.kind==="video"||t.kind==="audio") n+=t.clips.length; }); }catch(e){window.__swl&&window.__swl(e)} return n; }
  var last=count(), ra=window.renderAll;
  if(typeof ra==="function") window.renderAll=function(){
    var r=ra.apply(this,arguments), n=count();
    if(n>last&&!busy){ last=n; setTimeout(function(){ run("Clips placed one after another so they don't overlap"); },0); } else last=n;
    return r;
  };
})();

